"use client";

import { useEffect, useState, Suspense, useRef } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";
import { Loader2, CheckCircle2, XCircle, Sprout, ArrowRight, LogIn, UserPlus, Eye, EyeOff, Camera } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Card } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { AuthLayout } from "@/components/auth/auth-layout";

interface InviteDetails {
    tenant_nome: string;
    perfil_nome: string;
    email_convidado: string;
    expira_em: string;
    fazendas: string[];
    usuario_existe: boolean;
}

function AcceptInviteContent() {
    const searchParams = useSearchParams();
    const router = useRouter();
    const { token: userLoggedInToken, user } = useAppStore();

    const [status, setStatus] = useState<"loading" | "details" | "register" | "success" | "error">("loading");
    const [invite, setInvite] = useState<InviteDetails | null>(null);
    const [message, setMessage] = useState("");
    const [isProcessing, setIsProcessing] = useState(false);

    // Register form state
    const [nome, setNome] = useState("");
    const [senha, setSenha] = useState("");
    const [senhaConfirm, setSenhaConfirm] = useState("");
    const [showSenha, setShowSenha] = useState(false);
    const [fotoPreview, setFotoPreview] = useState<string | null>(null);
    const [fotoFile, setFotoFile] = useState<File | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const inviteToken = searchParams.get("token");

    // 1. Buscar detalhes do convite ao carregar
    useEffect(() => {
        if (!inviteToken) {
            setStatus("error");
            setMessage("O link de convite é inválido ou está corrompido.");
            return;
        }

        const fetchDetails = async () => {
            try {
                const data = await apiFetch<InviteDetails>(`/onboarding/convites/${inviteToken}`);
                setInvite(data);
                // Se usuário não existe e não está logado → ir direto para registro
                if (!data.usuario_existe && !userLoggedInToken) {
                    setStatus("register");
                } else {
                    setStatus("details");
                }

                // Se já estiver logado e o email for o mesmo (ou se simplesmente estiver logado e quisermos facilitar),
                // podemos até auto-aceitar, mas melhor pedir confirmação.
            } catch (error: any) {
                setStatus("error");
                setMessage(error.message || "Este convite expirou ou não é mais válido.");
            }
        };

        fetchDetails();
    }, [inviteToken]);

    const handleAccept = async () => {
        if (!userLoggedInToken) {
            toast.error("Você precisa estar logado para aceitar.");
            router.push(`/login?redirect=/convite/aceitar?token=${inviteToken}`);
            return;
        }

        setIsProcessing(true);
        try {
            await apiFetch<any>(`/onboarding/convites/aceitar?token=${inviteToken}`, {
                method: "POST"
            });
            setStatus("success");
            setMessage("Agora você faz parte da equipe! Bem-vindo.");
            toast.success("Convite aceito com sucesso!");
        } catch (error: any) {
            toast.error(error.message || "Erro ao aceitar convite.");
            setStatus("error");
            setMessage(error.message || "Não foi possível aceitar este convite.");
        } finally {
            setIsProcessing(false);
        }
    };

    const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setFotoFile(file);
        const reader = new FileReader();
        reader.onload = (ev) => setFotoPreview(ev.target?.result as string);
        reader.readAsDataURL(file);
    };

    const handleRegister = async (e: React.FormEvent) => {
        e.preventDefault();
        if (senha !== senhaConfirm) {
            toast.error("As senhas não coincidem.");
            return;
        }
        if (senha.length < 8) {
            toast.error("A senha deve ter pelo menos 8 caracteres.");
            return;
        }

        setIsProcessing(true);
        try {
            let foto_perfil_url: string | null = null;

            // Upload da foto se informada
            if (fotoFile) {
                const formData = new FormData();
                formData.append("file", fotoFile);
                try {
                    const uploadRes = await apiFetch<{ url: string }>("/users/me/avatar", {
                        method: "POST",
                        body: formData,
                    });
                    foto_perfil_url = uploadRes.url;
                } catch {
                    // foto não é obrigatória, continua sem ela
                }
            }

            await apiFetch<{ access_token: string }>("/onboarding/convites/registrar", {
                method: "POST",
                body: JSON.stringify({
                    token: inviteToken,
                    senha,
                    nome_completo: nome || undefined,
                    foto_perfil_url,
                }),
            });

            setStatus("success");
            setMessage("Conta criada com sucesso! Faça login para entrar.");
            toast.success("Conta criada! Redirecionando para o login...");
            setTimeout(() => router.push(`/login?email=${encodeURIComponent(invite!.email_convidado)}`), 1800);
        } catch (error: any) {
            toast.error(error.message || "Erro ao criar conta.");
        } finally {
            setIsProcessing(false);
        }
    };

    // Renderização baseada no status
    return (
        <div className="w-full max-w-[420px] animate-in fade-in zoom-in duration-500">
            {/* Cabeçalho de Logo */}
                <div className="flex flex-col items-center mb-8 gap-3">
                    <div className="flex size-11 items-center justify-center rounded-sm bg-primary border border-primary/20 shadow-lg shadow-primary/20 transition-all duration-300">
                        <Sprout className="size-6 text-primary-foreground" />
                    </div>
                </div>

                <Card className="rounded-sm border-border bg-card/60 backdrop-blur-xl shadow-premium p-8 relative overflow-hidden group">
                    {/* Linha de acento no topo */}
                    <div className="absolute top-0 left-0 w-full h-[1.5px] bg-gradient-to-r from-transparent via-primary/40 to-transparent" />

                    {status === "loading" && (
                        <div className="flex flex-col items-center py-8 gap-4 text-center">
                            <Loader2 className="size-10 animate-spin text-primary" />
                            <p className="text-sm text-muted-foreground font-medium animate-pulse">Autenticando convite no sistema...</p>
                        </div>
                    )}

                    {status === "details" && invite && (
                        <div className="space-y-6">
                            <div className="space-y-2 text-center">
                                <Badge variant="outline" className="bg-primary/5 border-primary/20 text-primary text-[10px] uppercase font-black tracking-widest px-2 py-0.5">
                                    Acesso Autorizado
                                </Badge>
                                <h3 className="text-2xl font-black text-foreground leading-tight tracking-tight">
                                    Convite Recebido
                                </h3>
                                <p className="text-sm text-muted-foreground">
                                    Você foi convidado para integrar a equipe.
                                </p>
                            </div>

                            <div className="space-y-4 py-4 border-y border-border/10">
                                <div className="flex justify-between items-center text-sm">
                                    <span className="text-muted-foreground font-medium">Organização</span>
                                    <span className="text-foreground font-bold">{invite.tenant_nome}</span>
                                </div>
                                <div className="flex justify-between items-center text-sm">
                                    <span className="text-muted-foreground font-medium">Perfil de Acesso</span>
                                    <Badge variant="secondary" className="bg-secondary text-secondary-foreground font-bold border-border">
                                        {invite.perfil_nome}
                                    </Badge>
                                </div>
                                {invite.fazendas.length > 0 && (
                                    <div className="space-y-2">
                                        <span className="text-[10px] text-muted-foreground uppercase font-black tracking-widest">Unidades de Produção</span>
                                        <div className="flex flex-wrap gap-1.5">
                                            {invite.fazendas.map((f) => (
                                                <Badge key={f} variant="ghost" className="bg-primary/5 text-primary text-[10px] font-bold border-primary/10">
                                                    {f}
                                                </Badge>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {!userLoggedInToken ? (
                                <div className="space-y-3 pt-2">
                                    <p className="text-xs text-muted-foreground text-center leading-relaxed">
                                        Já possui uma conta ativa? Acesse para vincular o convite.
                                    </p>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        className="w-full gap-2 border-border hover:bg-accent text-foreground font-bold"
                                        onClick={() => router.push(`/login?redirect=/convite/aceitar?token=${inviteToken}`)}
                                    >
                                        <LogIn size={14} />
                                        Entrar com conta existente
                                    </Button>
                                </div>
                            ) : (
                                <div className="space-y-4 pt-2">
                                    {user?.email !== invite.email_convidado && (
                                        <div className="p-3 rounded-sm bg-orange-500/10 border border-orange-500/20 text-[11px] text-orange-600 leading-relaxed text-center italic font-medium">
                                            Atenção: Conectado como <span className="font-bold underline">{user?.email}</span>. O convite é para <span className="font-bold underline">{invite.email_convidado}</span>.
                                        </div>
                                    )}
                                    <Button 
                                        disabled={isProcessing}
                                        className="w-full h-10 bg-primary hover:bg-primary/90 text-primary-foreground font-black uppercase tracking-widest text-xs border-0 shadow-lg shadow-primary/20 group"
                                        onClick={handleAccept}
                                    >
                                        {isProcessing ? (
                                            <Loader2 className="animate-spin size-4" />
                                        ) : (
                                            <>
                                                Aceitar e Acessar Plataforma
                                                <ArrowRight size={16} className="ml-2 group-hover:translate-x-1 transition-transform" />
                                            </>
                                        )}
                                    </Button>
                                </div>
                            )}
                        </div>
                    )}

                    {status === "register" && invite && (
                        <form onSubmit={handleRegister} className="space-y-5">
                            <div className="space-y-2 text-center">
                                <Badge variant="outline" className="bg-primary/5 border-primary/20 text-primary text-[10px] uppercase font-black tracking-widest px-2 py-0.5">
                                    Concluir Onboarding
                                </Badge>
                                <h3 className="text-2xl font-black text-foreground leading-tight tracking-tight">
                                    Criar sua conta
                                </h3>
                                <p className="text-xs text-muted-foreground leading-relaxed">
                                    Registre-se em <span className="text-foreground font-semibold">{invite.tenant_nome}</span> para começar.
                                </p>
                            </div>

                            {/* Avatar upload */}
                            <div className="flex flex-col items-center gap-2 py-2">
                                <button
                                    type="button"
                                    onClick={() => fileInputRef.current?.click()}
                                    className="relative size-16 rounded-full bg-muted/30 border border-border flex items-center justify-center overflow-hidden hover:bg-muted/50 transition-colors group shadow-inner"
                                >
                                    {fotoPreview ? (
                                        <img src={fotoPreview} alt="foto" className="size-full object-cover" />
                                    ) : (
                                        <Camera className="size-6 text-muted-foreground/30 group-hover:text-muted-foreground/60 transition-colors" />
                                    )}
                                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                        <Camera className="size-4 text-white" />
                                    </div>
                                </button>
                                <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-tighter">Foto Perfil (Opcional)</span>
                                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFotoChange} />
                            </div>

                            <div className="space-y-1.5">
                                <Label htmlFor="reg-email" className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">E-mail Corporativo</Label>
                                <Input id="reg-email" value={invite.email_convidado} disabled className="opacity-60 grayscale cursor-not-allowed" />
                            </div>

                            <div className="space-y-1.5">
                                <Label htmlFor="reg-nome" className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider text-primary">Nome Completo</Label>
                                <Input
                                    id="reg-nome"
                                    placeholder="Como quer ser chamado?"
                                    value={nome}
                                    onChange={(e) => setNome(e.target.value)}
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                <div className="space-y-1.5">
                                    <Label htmlFor="reg-senha" className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Senha</Label>
                                    <div className="relative">
                                        <Input
                                            id="reg-senha"
                                            type={showSenha ? "text" : "password"}
                                            placeholder="Sua senha"
                                            value={senha}
                                            onChange={(e) => setSenha(e.target.value)}
                                            required
                                            className="pr-10"
                                        />
                                        <button type="button" onClick={() => setShowSenha(v => !v)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground/30 hover:text-muted-foreground/60">
                                            {showSenha ? <EyeOff size={14} /> : <Eye size={14} />}
                                        </button>
                                    </div>
                                </div>

                                <div className="space-y-1.5">
                                    <Label htmlFor="reg-confirm" className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Repetir Senha</Label>
                                    <Input
                                        id="reg-confirm"
                                        type="password"
                                        placeholder="Confirme"
                                        value={senhaConfirm}
                                        onChange={(e) => setSenhaConfirm(e.target.value)}
                                        required
                                    />
                                </div>
                            </div>

                            <Button
                                type="submit"
                                disabled={isProcessing}
                                className="w-full h-10 bg-primary hover:bg-primary/90 text-primary-foreground font-black uppercase tracking-widest text-xs border-0 shadow-lg shadow-primary/20 group"
                            >
                                {isProcessing ? (
                                    <Loader2 className="animate-spin size-4" />
                                ) : (
                                    <>
                                        <UserPlus size={14} className="mr-2" />
                                        Confirmar Registro
                                        <ArrowRight size={14} className="ml-2 group-hover:translate-x-1 transition-transform" />
                                    </>
                                )}
                            </Button>

                            <p className="text-center text-[11px] text-muted-foreground">
                                Já possui conta?{" "}
                                <button type="button" className="text-primary font-bold hover:underline" onClick={() => router.push(`/login?redirect=/convite/aceitar?token=${inviteToken}`)}>
                                    Realizar Login
                                </button>
                            </p>
                        </form>
                    )}

                    {status === "success" && (
                        <div className="flex flex-col items-center text-center py-6 space-y-6">
                            <div className="size-20 rounded-full bg-primary/10 flex items-center justify-center border border-primary/20 animate-bounce duration-1000">
                                <CheckCircle2 className="size-10 text-primary shadow-sm" />
                            </div>
                            <div className="space-y-2">
                                 <h3 className="text-2xl font-black text-foreground tracking-tight">Sucesso Total!</h3>
                                 <p className="text-sm text-muted-foreground leading-relaxed max-w-[280px]">
                                    {message} Seu perfil foi atualizado com as novas permissões.
                                 </p>
                            </div>
                            <Button 
                                className="w-full h-10 bg-primary text-primary-foreground font-black uppercase tracking-widest text-xs hover:bg-primary/90 shadow-primary/20 shadow-xl transition-all"
                                onClick={() => router.push("/dashboard")}
                            >
                                Ir para o Painel Inicial
                            </Button>
                        </div>
                    )}

                    {status === "error" && (
                        <div className="flex flex-col items-center text-center py-6 space-y-6">
                             <div className="size-20 rounded-full bg-destructive/10 flex items-center justify-center border border-destructive/20">
                                <XCircle className="size-10 text-destructive" />
                            </div>
                            <div className="space-y-2">
                                 <h3 className="text-2xl font-black text-foreground">Link Indisponível</h3>
                                 <p className="text-sm text-muted-foreground leading-relaxed">
                                    {message}
                                 </p>
                            </div>
                            <Button 
                                variant="outline"
                                size="sm"
                                className="w-full h-10 border-border text-foreground font-bold hover:bg-accent"
                                onClick={() => router.push("/login")}
                            >
                                Voltar para o Início
                            </Button>
                        </div>
                    )}
                </Card>

                <p className="text-center text-[10px] text-muted-foreground/30 mt-8 font-bold uppercase tracking-widest">
                    Segurança AgroSaaS · 2026
                </p>
            </div>
    );
}

export default function AcceptInvitePage() {
    return (
        <AuthLayout badgeLabel="Convite Oficial">
            <Suspense fallback={
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="animate-spin text-primary size-12" />
                    <p className="text-white/20 text-xs font-bold uppercase tracking-widest">Carregando...</p>
                </div>
            }>
                <AcceptInviteContent />
            </Suspense>
        </AuthLayout>
    );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { 
    CalendarCheck, 
    Plus, 
    Leaf,
    AlertCircle,
    Sprout
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { DataTable, type ColumnDef } from "@/components/ui/data-table";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter, DialogDescription
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { FenologiaRegistroCreateSchema, type FenologiaRegistroCreate } from "@farm/zod-schemas";
import { toast } from "sonner";
import { Skeleton } from "@/components/ui/skeleton";
import { PageHeader } from "@/components/shared/page-header";
import { StatCard } from "@/components/shared/stat-card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

interface Safra {
    id: string;
    ano_safra: string;
    cultura: string;
    status: string;
    talhao_id: string;
}

interface EscalaBBCH {
    id: string;
    cultura: string;
    codigo: string;
    nome: string;
    descricao: string | null;
    ordem: number;
}

interface RegistroFenologia {
    id: string;
    safra_id: string;
    talhao_id: string;
    escala_id: string;
    data_observacao: string;
    observacao: string | null;
    escala: EscalaBBCH;
    created_at: string;
}

export default function FenologiaPage() {
    const queryClient = useQueryClient();
    const [selectedSafraId, setSelectedSafraId] = useState<string>("all");
    const [isAddOpen, setIsAddOpen] = useState(false);

    // Fetch safras ativas para o filtro e form
    const { data: safras = [], isLoading: isLoadingSafras } = useQuery<Safra[]>({
        queryKey: ["safras", "ativas"],
        queryFn: () => apiFetch("/safras"),
    });

    const activeSafras = safras.filter(s => !["ENCERRADA", "CANCELADA"].includes(s.status));
    const safraSelecionadaParam = selectedSafraId === "all" ? (activeSafras[0]?.id || null) : selectedSafraId;
    const safraAtualObj = safras.find(s => s.id === safraSelecionadaParam);

    // Fetch registros fenológicos
    const { data: registros = [], isLoading: isLoadingRegistros } = useQuery<RegistroFenologia[]>({
        queryKey: ["fenologia", safraSelecionadaParam],
        queryFn: () => apiFetch(`/safras/${safraSelecionadaParam}/fenologia`),
        enabled: !!safraSelecionadaParam,
    });

    // Fetch escalas BBCH da cultura selecionada
    const { data: escalas = [] } = useQuery<EscalaBBCH[]>({
        queryKey: ["escalas", safraAtualObj?.cultura],
        queryFn: () => apiFetch(`/fenologia/escalas?cultura=${safraAtualObj?.cultura}`),
        enabled: !!safraAtualObj?.cultura,
    });

    const createMutation = useMutation({
        mutationFn: (data: FenologiaRegistroCreate) => 
            apiFetch(`/safras/${data.safra_id}/talhoes/${data.talhao_id}/fenologia`, {
                method: "POST",
                body: JSON.stringify(data),
            }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["fenologia", safraSelecionadaParam] });
            toast.success("Observação fenológica registrada com sucesso!");
            setIsAddOpen(false);
            reset();
        },
        onError: (err: any) => toast.error(err?.message ?? "Erro ao registrar observação"),
    });

    const { register, handleSubmit, reset, control, watch, setValue } = useForm<FenologiaRegistroCreate>({
        resolver: zodResolver(FenologiaRegistroCreateSchema),
        defaultValues: {
            safra_id: safraAtualObj?.id ?? "",
            talhao_id: safraAtualObj?.talhao_id ?? "",
            data_observacao: new Date().toISOString().split('T')[0],
        }
    });

    // Atualiza form se safra selecionada mudar externamente
    const formSafraId = watch("safra_id");
    const selectedFormSafra = safras.find(s => s.id === formSafraId);

    const columns: ColumnDef<RegistroFenologia>[] = [
        {
            id: "data",
            header: "Data",
            accessorKey: "data_observacao",
            sortable: true,
            exportFormat: (val) => format(new Date(val), "dd/MM/yyyy"),
            cell: (val: string) => (
                <span className="font-medium whitespace-nowrap">
                    {format(new Date(val), "dd MMM yyyy", { locale: ptBR })}
                </span>
            ),
        },
        {
            id: "estagio",
            header: "Estágio (BBCH)",
            accessorFn: (row) => `${row.escala.codigo} - ${row.escala.nome}`,
            sortable: true,
            filterable: true,
            cell: (_, row) => (
                <div>
                    <Badge variant="outline" className="mr-2 rounded-sm font-mono bg-emerald-50 text-emerald-700 border-emerald-200">
                        {row.escala.codigo}
                    </Badge>
                    <span className="font-medium">{row.escala.nome}</span>
                </div>
            )
        },
        {
            id: "cultura",
            header: "Cultura",
            accessorFn: () => safraAtualObj?.cultura ?? "N/A",
            sortable: true,
        },
        {
            id: "observacao",
            header: "Observação",
            accessorKey: "observacao",
            cell: (val: string | null) => (
                <span className="text-muted-foreground text-sm truncate max-w-[300px] block">
                    {val || "—"}
                </span>
            ),
        },
    ];

    if (isLoadingSafras) {
        return (
            <div className="p-6 space-y-6">
                <Skeleton className="h-10 w-64" />
                <Skeleton className="h-48 w-full" />
                <Skeleton className="h-96 w-full" />
            </div>
        );
    }

    if (activeSafras.length === 0) {
        return (
            <div className="p-6 space-y-6">
                <PageHeader
                    title="Fenologia"
                    description="Acompanhamento fenológico das culturas"
                    icon={<Sprout className="text-primary" size={22} />}
                    breadcrumbs={[{ label: "Agrícola", href: "/agricola" }, { label: "Fenologia" }]}
                />
                <Alert variant="default" className="bg-amber-50 text-amber-900 border-amber-200">
                    <AlertCircle className="h-4 w-4 stroke-amber-600" />
                    <AlertTitle>Nenhuma safra ativa</AlertTitle>
                    <AlertDescription>
                        Para registrar estágios fenológicos, é necessário ter pelo menos uma safra em andamento.
                    </AlertDescription>
                </Alert>
            </div>
        );
    }

    return (
        <div className="p-6 space-y-6">
            <PageHeader
                title="Fenologia"
                description="Registre e acompanhe o desenvolvimento (escala BBCH) das culturas no campo."
                icon={<Sprout className="text-primary" size={22} />}
                breadcrumbs={[{ label: "Agrícola", href: "/agricola" }, { label: "Fenologia" }]}
                actions={
                    <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
                        <DialogTrigger 
                            render={
                                <Button variant="outline" size="sm" onClick={() => {
                                    reset({ 
                                        safra_id: safraAtualObj?.id ?? "", 
                                        talhao_id: safraAtualObj?.talhao_id ?? "",
                                        data_observacao: new Date().toISOString().split('T')[0],
                                    });
                                }}>
                                    <Plus className="size-3.5 mr-1.5" /> Registrar BBCH
                                </Button>
                            }
                        />
                        <DialogContent className="sm:max-w-[500px]">
                            <form onSubmit={handleSubmit(d => createMutation.mutate(d))}>
                                <DialogHeader>
                                    <DialogTitle>Novo Registro Fenológico</DialogTitle>
                                    <DialogDescription>
                                        Registre o estágio de desenvolvimento atual da cultura no talhão.
                                    </DialogDescription>
                                </DialogHeader>
                                <div className="grid gap-5 py-4">
                                    <div className="space-y-1.5">
                                        <Label>Safra</Label>
                                        <Controller
                                            name="safra_id"
                                            control={control}
                                            render={({ field }) => (
                                                <Select value={field.value} onValueChange={(val: string) => {
                                                    field.onChange(val);
                                                    const s = safras.find(x => x.id === val);
                                                    if (s) setValue("talhao_id", s.talhao_id);
                                                    setValue("escala_id", "");
                                                }}>
                                                    <SelectTrigger>
                                                        <SelectValue placeholder="Selecione a safra atrelada" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        {activeSafras.map(s => (
                                                            <SelectItem key={s.id} value={s.id}>
                                                                {s.cultura} - {s.ano_safra}
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            )}
                                        />
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-1.5">
                                            <Label>Data de Observação</Label>
                                            <Input type="date" {...register("data_observacao")} />
                                        </div>
                                        {/* Futuro: se o backend suportar dropdown interativo do talhão, faremos select. Hoje usamos o talhao_id da safra para simplificar. */}
                                    </div>

                                    <div className="space-y-1.5">
                                        <Label>Estágio BBCH ({selectedFormSafra?.cultura || "N/A"})</Label>
                                        <Controller
                                            name="escala_id"
                                            control={control}
                                            render={({ field }) => (
                                                <Select value={field.value} onValueChange={field.onChange}>
                                                    <SelectTrigger>
                                                        <SelectValue placeholder="Selecione a fase BBCH" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        {escalas.length === 0 && (
                                                            <SelectItem value="empty" disabled>Carregando escalas...</SelectItem>
                                                        )}
                                                        {escalas.map(e => (
                                                            <SelectItem key={e.id} value={e.id}>
                                                                <span className="font-mono text-muted-foreground mr-1">[{e.codigo}]</span>
                                                                {e.nome}
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            )}
                                        />
                                    </div>

                                    <div className="space-y-1.5">
                                        <Label>Observações (Opcional)</Label>
                                        <Textarea placeholder="Descreva condição foliar, pragas aparentes, etc" className="resize-none" {...register("observacao")} />
                                    </div>
                                </div>
                                <DialogFooter>
                                    <Button variant="outline" size="sm" type="submit" disabled={createMutation.isPending}>Salvar Registro</Button>
                                </DialogFooter>
                            </form>
                        </DialogContent>
                    </Dialog>
                }
            />

            <div className="grid gap-4 md:grid-cols-4">
                <div className="col-span-1 md:col-span-1">
                    <Card className="shadow-sm border-none bg-emerald-700 text-white rounded-sm">
                        <CardContent className="p-6">
                            <Leaf className="size-8 opacity-50 mb-4" />
                            <p className="text-emerald-100 text-sm font-medium">Ciclos Monitorados</p>
                            <h2 className="text-3xl font-bold mt-1">{registros.length}</h2>
                        </CardContent>
                    </Card>
                </div>
                <div className="col-span-1 md:col-span-3">
                    <Card className="shadow-sm flex h-full items-center px-6">
                        <div className="flex flex-col gap-1 w-full max-w-sm">
                            <Label className="text-muted-foreground text-xs uppercase tracking-wider">Filtrar por Safra Ativa</Label>
                            <Select value={selectedSafraId} onValueChange={setSelectedSafraId}>
                                <SelectTrigger className="w-full">
                                    <SelectValue placeholder="Todas as safras..." />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Foco Automático (Destaque)</SelectItem>
                                    {activeSafras.map(s => (
                                        <SelectItem key={s.id} value={s.id}>{s.cultura} — {s.ano_safra}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </Card>
                </div>
            </div>

            {isLoadingRegistros ? (
                <Card className="shadow-sm rounded-sm">
                    <CardContent className="p-6">
                        <div className="space-y-2">
                            <Skeleton className="h-10 w-full" />
                            <Skeleton className="h-10 w-full" />
                            <Skeleton className="h-10 w-full" />
                        </div>
                    </CardContent>
                </Card>
            ) : (
                <DataTable
                    data={registros}
                    columns={columns}
                    searchable
                    searchPlaceholder="Buscar por observações ou fases..."
                    exportable
                    exportFileName={`fenologia_${safraAtualObj?.cultura ?? "todas"}`}
                    emptyMessage="Nenhuma observação fenológica nesta safra."
                />
            )}
        </div>
    );
}

