"use client";

import { useEffect, useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import {
    Calculator,
    Pencil,
    Plus,
    PiggyBank,
    TrendingUp,
    TrendingDown,
    PieChart,
    Trash2,
    MapPin,
    Wheat,
    XCircle,
    Save
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { DataTable, type ColumnDef } from "@/components/ui/data-table";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter, DialogBody
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useForm, Controller, type Resolver } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { 
    ItemOrcamentoCreateSchema, type ItemOrcamentoCreate,
} from "@farm/zod-schemas";
import { toast } from "sonner";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { PageHeader } from "@/components/shared/page-header";
import { CategoryProgressBar } from "@/components/agricola/category-progress-bar";
import { formatCurrency, formatArea } from "@farm/utils";

interface Safra {
    id: string;
    ano_safra: string;
    cultura: string;
    status: string;
}

interface Cultura {
    id: string;
    nome: string;
}

interface Cultivo {
    id: string;
    cultura: string;
    cultivar_nome: string | null;
}

interface CustoCategoria {
    categoria: string;
    custo_total: number;
    custo_por_ha: number;
    percentual: number;
}

interface OrcamentoPrevisto {
    custo_total: number;
    custo_por_ha: number;
    receita_esperada: number;
    receita_por_ha: number;
    margem_bruta: number;
    ponto_equilibrio_sc_ha: number | null;
    por_categoria: CustoCategoria[];
}

interface DesvioOrcamento {
    custo_desvio_valor: number;
    custo_desvio_pct: number;
    status: string;
}

interface OrcamentoSafraResponse {
    safra_id: string;
    cultura: string;
    ano_safra: string;
    area_ha: number;
    status_safra: string;
    previsto: OrcamentoPrevisto | null;
    realizado: any;
    desvio: DesvioOrcamento | null;
}

interface ItemOrcamento {
    id: string;
    safra_id: string;
    cultivo_id?: string | null;
    categoria: string;
    descricao: string;
    quantidade: number;
    unidade: string;
    custo_unitario: number;
    custo_total: number;
    ordem: number;
    observacoes?: string | null;
}

const CATEGORIAS = [
    { value: "SEMENTE", label: "Semente" },
    { value: "FERTILIZANTE", label: "Fertilizante" },
    { value: "DEFENSIVO", label: "Defensivo" },
    { value: "COMBUSTIVEL", label: "Combustível" },
    { value: "MAO_DE_OBRA", label: "Mão de Obra" },
    { value: "SERVICO", label: "Serviço" },
    { value: "SEGURO", label: "Seguro" },
    { value: "OUTROS", label: "Outros" },
];

function categoriaLabel(value: string) {
    return CATEGORIAS.find((c) => c.value === value)?.label ?? value;
}

export default function PlanejamentoPage() {
    const queryClient = useQueryClient();
    const [selectedSafraId, setSelectedSafraId] = useState<string>("");
    const [isAddOpen, setIsAddOpen] = useState(false);
    const [editItem, setEditItem] = useState<ItemOrcamento | null>(null);
    const [deleteDialog, setDeleteDialog] = useState<{ open: boolean; itemId?: string }>({ open: false });

    // Fetch safras ativas (em planejamento ou início)
    const { data: safras = [], isLoading: isLoadingSafras } = useQuery<Safra[]>({
        queryKey: ["safras"],
        queryFn: () => apiFetch("/safras"),
    });

    // Fetch culturas para relacional de nomes
    const { data: listCulturas = [] } = useQuery<Cultura[]>({
        queryKey: ["culturas"],
        queryFn: () => apiFetch("/cadastros/culturas"),
    });

    const getCulturaNome = (cId: string) => {
        const match = listCulturas.find(c => c.id === cId || c.nome === cId);
        return match ? match.nome : cId;
    };
    const getCultivoLabel = (cultivoId?: string | null) => {
        if (!cultivoId) return "Geral da safra";
        const cultivo = cultivos.find((item) => item.id === cultivoId);
        if (!cultivo) return "Cultivo não identificado";
        return `${cultivo.cultura}${cultivo.cultivar_nome ? ` · ${cultivo.cultivar_nome}` : ""}`;
    };

    const activeSafras = safras.filter(s => !["ENCERRADA", "CANCELADA"].includes(s.status));
    const safraSelecionadaParam = selectedSafraId || null;
    const safraAtualObj = safras.find(s => s.id === safraSelecionadaParam);
    const { data: cultivos = [] } = useQuery<Cultivo[]>({
        queryKey: ["cultivos", safraSelecionadaParam],
        queryFn: () => apiFetch(`/safras/${safraSelecionadaParam}/cultivos`),
        enabled: !!safraSelecionadaParam,
    });

    // Fetch Resumo do Orçamento
    const { data: orcamento, isLoading: isLoadingOrcamento } = useQuery<OrcamentoSafraResponse>({
        queryKey: ["orcamento", safraSelecionadaParam],
        queryFn: () => apiFetch(`/agricola/planejamento/safras/${safraSelecionadaParam}/orcamento`),
        enabled: !!safraSelecionadaParam,
    });

    // Fetch Itens
    const { data: itens = [], isLoading: isLoadingItens } = useQuery<ItemOrcamento[]>({
        queryKey: ["orcamento", "itens", safraSelecionadaParam],
        queryFn: () => apiFetch(`/agricola/planejamento/safras/${safraSelecionadaParam}/itens`),
        enabled: !!safraSelecionadaParam,
    });

    const createMutation = useMutation({
        mutationFn: (data: ItemOrcamentoCreate) => {
            if (!safraSelecionadaParam) throw new Error("Selecione uma safra primeiro");
            const payload: ItemOrcamentoCreate = {
                ...data,
                cultivo_id: data.cultivo_id ?? (cultivos.length === 1 ? cultivos[0].id : null),
            };
            return apiFetch(`/agricola/planejamento/safras/${safraSelecionadaParam}/itens`, {
                method: "POST",
                body: JSON.stringify(payload),
            });
        },
        onSuccess: async () => {
            console.log("✅ Item criado com sucesso. Hard refresh...", safraSelecionadaParam);
            // Remove cache e força refetch
            queryClient.removeQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam] });
            queryClient.removeQueries({ queryKey: ["orcamento", safraSelecionadaParam] });

            // Refetch com força
            await Promise.all([
                queryClient.refetchQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam], type: "active" }),
                queryClient.refetchQueries({ queryKey: ["orcamento", safraSelecionadaParam], type: "active" })
            ]);

            toast.success("Item de orçamento registrado!");
            setIsAddOpen(false);
            resetCreate();
        },
        onError: (err: any) => {
            console.error("❌ Erro ao criar item:", err);
            toast.error(err?.message ?? "Erro ao registrar item");
        },
    });

    const updateMutation = useMutation({
        mutationFn: ({ itemId, data }: { itemId: string; data: ItemOrcamentoCreate }) => {
            if (!safraSelecionadaParam) throw new Error("Selecione uma safra primeiro");
            const payload: ItemOrcamentoCreate = {
                ...data,
                cultivo_id: data.cultivo_id ?? (cultivos.length === 1 ? cultivos[0].id : null),
            };
            return apiFetch(`/agricola/planejamento/safras/${safraSelecionadaParam}/itens/${itemId}`, {
                method: "PATCH",
                body: JSON.stringify(payload),
            });
        },
        onSuccess: async () => {
            queryClient.removeQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam] });
            queryClient.removeQueries({ queryKey: ["orcamento", safraSelecionadaParam] });

            await Promise.all([
                queryClient.refetchQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam], type: "active" }),
                queryClient.refetchQueries({ queryKey: ["orcamento", safraSelecionadaParam], type: "active" }),
            ]);

            toast.success("Item de orçamento atualizado!");
            setIsAddOpen(false);
            setEditItem(null);
            resetCreate();
        },
        onError: (err: any) => {
            console.error("❌ Erro ao atualizar item:", err);
            toast.error(err?.message ?? "Erro ao atualizar item");
        },
    });

    const deleteMutation = useMutation({
        mutationFn: (id: string) => {
            if (!safraSelecionadaParam) throw new Error("Selecione uma safra primeiro");
            return apiFetch(`/agricola/planejamento/safras/${safraSelecionadaParam}/itens/${id}`, {
                method: "DELETE",
            });
        },
        onSuccess: async () => {
            console.log("✅ Item removido com sucesso. Hard refresh...", safraSelecionadaParam);
            // Remove cache e força refetch
            queryClient.removeQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam] });
            queryClient.removeQueries({ queryKey: ["orcamento", safraSelecionadaParam] });

            // Refetch com força
            await Promise.all([
                queryClient.refetchQueries({ queryKey: ["orcamento", "itens", safraSelecionadaParam], type: "active" }),
                queryClient.refetchQueries({ queryKey: ["orcamento", safraSelecionadaParam], type: "active" })
            ]);

            toast.success("Item removido com sucesso!");
        },
        onError: (err: any) => {
            console.error("❌ Erro ao excluir item:", err);
            toast.error(err?.message ?? "Erro ao excluir");
        },
    });

    const { register: regCreate, handleSubmit: submitCreate, reset: resetCreate, control: ctrlCreate, watch } = useForm<ItemOrcamentoCreate>({
        resolver: zodResolver(ItemOrcamentoCreateSchema) as unknown as Resolver<ItemOrcamentoCreate>,
        defaultValues: {
            cultivo_id: null,
            categoria: "FERTILIZANTE",
            descricao: "",
            quantidade: 1,
            unidade: "kg",
            custo_unitario: 1,
            ordem: 0,
            observacoes: "",
        }
    });

    useEffect(() => {
        if (!isAddOpen) return;

        if (!editItem) {
            resetCreate({
                cultivo_id: cultivos.length === 1 ? cultivos[0].id : null,
                categoria: "FERTILIZANTE",
                descricao: "",
                quantidade: 1,
                unidade: "kg",
                custo_unitario: 1,
                ordem: 0,
                observacoes: "",
            });
            return;
        }

        resetCreate({
            cultivo_id: editItem.cultivo_id ?? null,
            categoria: editItem.categoria as ItemOrcamentoCreate["categoria"],
            descricao: editItem.descricao,
            quantidade: editItem.quantidade,
            unidade: editItem.unidade,
            custo_unitario: editItem.custo_unitario,
            ordem: editItem.ordem,
            observacoes: editItem.observacoes ?? "",
        });
    }, [cultivos, editItem, isAddOpen, resetCreate]);

    useEffect(() => {
        setEditItem(null);
        setIsAddOpen(false);
    }, [selectedSafraId]);

    // Calcula total preview
    const qtd = watch("quantidade") || 0;
    const pu = watch("custo_unitario") || 0;
    const totalPreview = qtd * pu;

    const columns: ColumnDef<ItemOrcamento>[] = [
        {
            id: "cultivo",
            header: "Cultivo",
            accessorFn: (row) => getCultivoLabel(row.cultivo_id),
            sortable: true,
            filterable: true,
            filterPlaceholder: "Filtrar cultivo...",
            cell: (val: string, row) => (
                <span className={row.cultivo_id ? "text-foreground" : "text-muted-foreground"}>
                    {val}
                </span>
            ),
        },
        {
            id: "categoria",
            header: "Categoria",
            accessorFn: (row) => categoriaLabel(row.categoria),
            sortable: true,
            filterable: true,
            filterPlaceholder: "Filtrar categoria...",
            cell: (val: string) => <Badge variant="outline" className="text-[10px] uppercase font-bold tracking-widest text-primary bg-primary/10 border-primary/20 rounded-sm">{val}</Badge>,
        },
        {
            id: "descricao",
            header: "Descrição",
            accessorKey: "descricao",
            sortable: true,
            filterable: true,
            cell: (val: string) => <span className="font-medium max-w-[200px] truncate block" title={val}>{val}</span>,
        },
        {
            id: "quantidade",
            header: "Quant.",
            accessorFn: (row) => row.quantidade,
            cell: (_, row) => (
                <span className="text-muted-foreground">{row.quantidade} <span className="text-xs">{row.unidade}</span></span>
            )
        },
        {
            id: "custo_unitario",
            header: "Custo Un.",
            accessorKey: "custo_unitario",
            cell: (val: number) => <span className="font-mono">{formatCurrency(val)}</span>,
        },
        {
            id: "custo_total",
            header: "Total Orçado",
            accessorKey: "custo_total",
            sortable: true,
            cell: (val: number) => <span className="font-mono font-medium text-blue-700">{formatCurrency(val)}</span>,
        },
        {
            id: "acoes",
            header: "",
            exportable: false,
            sortable: false,
            filterable: false,
            cell: (_, row) => (
                <div className="flex items-center gap-0 justify-end">
                    <Button
                        size="icon"
                        variant="ghost"
                        className="size-7"
                        aria-label="Editar item"
                        onClick={() => {
                            setEditItem(row);
                            setIsAddOpen(true);
                        }}
                    >
                        <Pencil className="size-3.5" />
                    </Button>
                    <Button
                        size="icon"
                        variant="ghost"
                        className="size-7 text-destructive hover:text-destructive"
                        disabled={deleteMutation.isPending}
                        aria-label="Excluir item"
                        onClick={() => setDeleteDialog({ open: true, itemId: row.id })}
                    >
                        <Trash2 className="size-3.5" />
                    </Button>
                </div>
            ),
        },
    ];

    if (isLoadingSafras || isLoadingOrcamento) {
        return (
            <div className="space-y-6 p-6">
                <Skeleton className="h-10 w-64" />
                <Skeleton className="h-32 w-full" />
                <Skeleton className="h-96 w-full" />
            </div>
        );
    }

    const pr = orcamento?.previsto;
    const area = orcamento?.area_ha ?? 1;

    return (
        <div className="p-6 space-y-6">
            <PageHeader
                title="Orçamento de Safra"
                description="Planejamento de custeio e projeção de resultados"
                breadcrumbs={[{ label: "Agrícola", href: "/agricola" }, { label: "Orçamento de Safra" }]}
                icon={<Calculator className="text-primary" size={22} />}
                actions={
                    <Dialog
                        open={isAddOpen}
                        onOpenChange={(open) => {
                            setIsAddOpen(open);
                            if (!open) {
                                setEditItem(null);
                            }
                        }}
                    >
                    <DialogTrigger
                            render={
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => {
                                        setEditItem(null);
                                        resetCreate();
                                    }}
                                    disabled={!safraSelecionadaParam}
                                >
                                    <Plus className="size-3.5 mr-1.5" /> Adicionar Custo
                                </Button>
                            }
                        />
                        <DialogContent className="max-w-lg">
                            <form
                                onSubmit={submitCreate((d: ItemOrcamentoCreate) => (
                                    editItem
                                        ? updateMutation.mutate({ itemId: editItem.id, data: d })
                                        : createMutation.mutate(d)
                                ))}
                            >
                                <DialogHeader>
                                    <DialogTitle className="flex items-center gap-2">
                                        <div className="size-8 rounded-sm bg-primary/10 flex items-center justify-center">
                                            <PiggyBank className="size-4 text-primary" />
                                        </div>
                                        {editItem ? "Editar Item do Orçamento" : "Item do Orçamento"}
                                    </DialogTitle>
                                </DialogHeader>
                                <DialogBody className="space-y-4">
                                    {cultivos.length > 1 && (
                                        <div className="space-y-1.5">
                                            <Label className="text-xs font-medium">
                                                Cultivo <span className="text-[10px] text-muted-foreground">(opcional para custo geral da safra)</span>
                                            </Label>
                                            <Controller
                                                name="cultivo_id"
                                                control={ctrlCreate}
                                                render={({ field }) => (
                                                    <Select
                                                        value={field.value ?? "__ALL__"}
                                                        onValueChange={(value) => field.onChange(value === "__ALL__" ? null : value)}
                                                    >
                                                        <SelectTrigger className="h-8 text-xs rounded-sm">
                                                            <SelectValue placeholder="Todos os cultivos" />
                                                        </SelectTrigger>
                                                        <SelectContent className="rounded-sm">
                                                            <SelectItem value="__ALL__">Todos os cultivos</SelectItem>
                                                            {cultivos.map((cultivo) => (
                                                                <SelectItem key={cultivo.id} value={cultivo.id}>
                                                                    {cultivo.cultura}{cultivo.cultivar_nome ? ` · ${cultivo.cultivar_nome}` : ""}
                                                                </SelectItem>
                                                            ))}
                                                        </SelectContent>
                                                    </Select>
                                                )}
                                            />
                                        </div>
                                    )}
                                    {cultivos.length === 1 && (
                                        <div className="space-y-1.5">
                                            <Label className="text-xs font-medium">Cultivo</Label>
                                            <div className="h-8 rounded-sm border bg-muted/40 px-3 text-xs flex items-center text-muted-foreground">
                                                {cultivos[0].cultura}{cultivos[0].cultivar_nome ? ` · ${cultivos[0].cultivar_nome}` : ""}
                                            </div>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-1.5 min-w-0">
                                            <Label>Categoria</Label>
                                            <Controller
                                                name="categoria"
                                                control={ctrlCreate}
                                                render={({ field }) => (
                                                    <Select value={field.value} onValueChange={field.onChange}>
                                                        <SelectTrigger className="h-8 text-xs rounded-sm">
                                                            <SelectValue placeholder="Selecione a categoria" />
                                                        </SelectTrigger>
                                                        <SelectContent className="rounded-sm">
                                                            {CATEGORIAS.map(c => (
                                                                <SelectItem key={c.value} value={c.value}>
                                                                    {c.label}
                                                                </SelectItem>
                                                            ))}
                                                        </SelectContent>
                                                    </Select>
                                                )}
                                            />
                                        </div>
                                        <div className="space-y-1.5 flex-1 min-w-0">
                                            <Label className="text-xs">Descrição</Label>
                                            <Input className="h-8 text-xs rounded-sm" placeholder="Ex: Cloreto de Potássio" {...regCreate("descricao")} />
                                        </div>
                                    </div>
                                    <div className="grid grid-cols-3 gap-4">
                                        <div className="space-y-1.5">
                                            <Label className="text-xs">Quant.</Label>
                                            <Input className="h-8 text-xs rounded-sm" type="number" step="0.01" {...regCreate("quantidade", { valueAsNumber: true })} />
                                        </div>
                                        <div className="space-y-1.5">
                                            <Label className="text-xs">Un.</Label>
                                            <Input className="h-8 text-xs rounded-sm" placeholder="kg, L, sc" {...regCreate("unidade")} />
                                        </div>
                                        <div className="space-y-1.5">
                                            <Label className="text-xs">Preço Un.</Label>
                                            <Input className="h-8 text-xs rounded-sm" type="number" step="0.01" {...regCreate("custo_unitario", { valueAsNumber: true })} />
                                        </div>
                                    </div>
                                    <div className="bg-muted p-3 rounded-sm flex justify-between items-center text-sm font-medium">
                                        <span className="text-muted-foreground">Total Orçado:</span>
                                        <span className="text-blue-700 text-lg">{formatCurrency(totalPreview)}</span>
                                    </div>
                                    <div className="space-y-1.5">
                                        <Label className="text-xs uppercase font-bold text-muted-foreground">Observações (Opcional)</Label>
                                        <Input className="h-8 text-xs rounded-sm" placeholder="Detalhes do fornecimento ou aplicação" {...regCreate("observacoes")} />
                                    </div>
                                </DialogBody>
                                <DialogFooter className="pt-2">
                                    <Button
                                        type="button"
                                        variant="outline"
                                        size="sm"
                                        className="rounded-sm"
                                        onClick={() => {
                                            setIsAddOpen(false);
                                            setEditItem(null);
                                        }}
                                        disabled={createMutation.isPending || updateMutation.isPending}
                                    >
                                        <XCircle className="size-3.5 mr-1.5" />
                                        Cancelar
                                    </Button>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        type="submit"
                                        className="rounded-sm border-primary/50 text-primary hover:bg-primary/5"
                                        disabled={createMutation.isPending || updateMutation.isPending}
                                    >
                                        <Save className="size-3.5 mr-1.5" />
                                        {createMutation.isPending || updateMutation.isPending
                                            ? "Salvando..."
                                            : editItem
                                            ? "Salvar Alterações"
                                            : "Salvar"}
                                    </Button>
                                </DialogFooter>
                            </form>
                        </DialogContent>
                    </Dialog>
                }
            />

            {/* Seletor de Safra */}
            {(() => {
                return (
                    <Card className="shadow-sm rounded-sm">
                        <CardContent className="p-4">
                            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                                <div className="flex flex-col gap-1">
                                    <Label className="text-xs text-muted-foreground uppercase tracking-wider">Qual Safra Planejar?</Label>
                                    {orcamento && (
                                        <p className="text-sm text-muted-foreground">
                                            {getCulturaNome(orcamento.cultura)} • Safra {orcamento.ano_safra} • {formatArea(orcamento.area_ha)}
                                        </p>
                                    )}
                                </div>
                                <Select value={selectedSafraId} onValueChange={setSelectedSafraId}>
                                    <SelectTrigger className="w-full md:w-[240px] h-8 text-xs rounded-sm font-medium">
                                        <SelectValue placeholder="Selecionar safra..." />
                                    </SelectTrigger>
                                    <SelectContent className="rounded-sm">
                                        {activeSafras.map(s => (
                                            <SelectItem key={s.id} value={s.id}>
                                                {getCulturaNome(s.cultura)} — {s.ano_safra}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </CardContent>
                    </Card>
                );
            })()}

            {/* KPIs em Grid 2x2 */}
            {pr && (
                <div className="grid gap-4 md:grid-cols-2">
                    <Card className="shadow-sm rounded-sm">
                        <CardHeader className="pb-2 flex flex-row items-center justify-between">
                            <CardTitle className="text-sm font-medium text-muted-foreground">Custo Total Previsto</CardTitle>
                            <Calculator className="size-5 text-blue-500 opacity-40" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold text-blue-700">{formatCurrency(pr.custo_total)}</div>
                            <p className="text-sm text-muted-foreground mt-2 font-mono">
                                {formatCurrency(pr.custo_por_ha)} por hectare
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="shadow-sm rounded-sm">
                        <CardHeader className="pb-2 flex flex-row items-center justify-between">
                            <CardTitle className="text-sm font-medium text-muted-foreground">Receita Esperada</CardTitle>
                            <TrendingUp className="size-5 text-emerald-500 opacity-40" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold text-emerald-700">{formatCurrency(pr.receita_esperada)}</div>
                            <p className="text-sm text-muted-foreground mt-2 font-mono">
                                {formatCurrency(pr.receita_por_ha)} por hectare
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="shadow-sm rounded-sm">
                        <CardHeader className="pb-2 flex flex-row items-center justify-between">
                            <CardTitle className="text-sm font-medium text-muted-foreground">Margem Bruta Projetada</CardTitle>
                            <PiggyBank className="size-5 text-amber-500 opacity-40" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold text-amber-600">{formatCurrency(pr.margem_bruta)}</div>
                            <p className="text-sm text-muted-foreground mt-2">
                                {pr.receita_esperada > 0 ? ((pr.margem_bruta / pr.receita_esperada) * 100).toFixed(1) : 0}% de rentabilidade
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="shadow-sm bg-gradient-to-br from-blue-50 to-blue-100/50 border-blue-200 rounded-sm">
                        <CardHeader className="pb-2 flex flex-row items-center justify-between">
                            <CardTitle className="text-sm font-medium text-blue-900">Break-even Point</CardTitle>
                            <TrendingDown className="size-5 text-blue-600 opacity-40" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-bold text-blue-900">{pr.ponto_equilibrio_sc_ha?.toFixed(1) ?? "—"} sc/ha</div>
                            <p className="text-sm text-blue-800/70 mt-2">Produtividade mínima para lucro zero</p>
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* Categorias com Progress Bars */}
            {pr?.por_categoria && pr.por_categoria.length > 0 && (
                <div>
                    <h3 className="text-sm font-semibold mb-3 flex items-center gap-2 text-muted-foreground">
                        <PieChart className="size-4" />
                        Distribuição por Categoria
                    </h3>
                    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                        {pr.por_categoria.sort((a, b) => b.custo_total - a.custo_total).map(c => (
                            <CategoryProgressBar
                                key={c.categoria}
                                categoria={c.categoria}
                                percentual={c.percentual}
                                custo_por_ha={c.custo_por_ha}
                                custo_total={c.custo_total}
                            />
                        ))}
                    </div>
                </div>
            )}

            {/* Tabela de Itens */}
            <DataTable
                data={itens}
                columns={columns}
                searchable
                searchPlaceholder="Buscar por descrição..."
                exportable
                exportFileName={`orcamento_${safraAtualObj?.ano_safra ?? "safra"}`}
                emptyMessage={safraSelecionadaParam ? "Nenhum item do orçamento cadastrado." : "Selecione uma safra para visualizar o orçamento."}
            />

            <ConfirmDialog
                open={deleteDialog.open}
                title="Remover Item"
                description="Tem certeza que deseja remover este item? Esta ação não pode ser desfeita."
                confirmText="Remover"
                cancelText="Cancelar"
                destructive
                onConfirm={() => deleteDialog.itemId && deleteMutation.mutate(deleteDialog.itemId)}
                onCancel={() => setDeleteDialog({ open: false })}
            />
        </div>
    );
}

