            {/* Tabs por fase */}
            <Card className="shadow-sm">
                <CardContent className="p-6">
                    <Tabs value={faseSelecionada} onValueChange={setFaseSelecionada}>
                        <TabsList className="flex-wrap h-auto gap-1 mb-4">
                            {FASES.map(f => {
                                const kpi = resumo?.fases.find(r => r.fase === f.key);
