                                            />
                                            {errors.insumos?.[index]?.dose_por_ha && (
                                                <p className="text-xs text-destructive">{errors.insumos[index]?.dose_por_ha?.message}</p>
                                            )}
                                        </div>
                                        <div className="space-y-2">
