        <DialogHeader className="border-b px-6 py-5">
          <DialogTitle className="flex items-center gap-2">
            <Layers />
            Nova Unidade Operacional
          </DialogTitle>
          <div className="text-sm text-muted-foreground">
            Vincule um cultivo a uma área e defina a unidade operacional desta safra.
          </div>
        </DialogHeader>
        <Form {...form}>
          <form
            onSubmit={form.handleSubmit((data) =>
              onSubmit({
                ...data,
                cultivo_area_id: form.getValues("cultivo_area_id") ?? null,
              }),
            )}
            className="flex max-h-[85vh] min-h-0 flex-col"
          >
            <ScrollArea className="min-h-0 flex-1">
              <DialogBody className="px-6 py-5">
                <div className="flex flex-col gap-5">
                  <section className="rounded-sm border bg-muted/30 p-4">
                    <div className="mb-4">
                      <h3 className="text-sm font-medium text-foreground">Vinculação da unidade</h3>
                      <p className="text-xs text-muted-foreground">
                        Primeiro escolha o cultivo e a área que serão associados a esta unidade operacional.
                      </p>
                    </div>

                    <div className="flex flex-col gap-4">
                      <FormField
                        control={form.control}
                        name="cultivo_id"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Cultivo *</FormLabel>
                            <Select
                              onValueChange={(value) => {
                                field.onChange(value);
                                form.setValue("area_id", "");
                                form.setValue("cultivo_area_id", null);
                              }}
                              value={field.value}
                            >
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue placeholder="Selecione o cultivo" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {cultivos.map((c) => (
                                  <SelectItem key={c.id} value={c.id}>
                                    {c.cultura}{c.cultivar_nome ? ` — ${c.cultivar_nome}` : ""}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="area_id"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Área *</FormLabel>
                            <Select
                              onValueChange={(value) => {
                                const selectedArea = areaOptions.find((a) => a.areaId === value);
                                field.onChange(value);
                                form.setValue("cultivo_area_id", selectedArea?.cultivoAreaId ?? null);
                              }}
                              value={field.value}
                              disabled={!selectedCultivoId}
                            >
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue
                                    placeholder={
                                      selectedCultivoId
                                        ? "Selecione a área"
                                        : "Selecione um cultivo primeiro"
                                    }
                                  />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {!selectedCultivoId ? (
                                  <SelectItem value="__empty" disabled>
                                    Selecione um cultivo primeiro
                                  </SelectItem>
                                ) : areaOptions.length === 0 ? (
                                  <SelectItem value="__empty" disabled>
                                    Nenhum talhão disponível
                                  </SelectItem>
                                ) : (
                                  areaOptions.map((a) => (
                                    <SelectItem key={a.areaId} value={a.areaId}>
                                      {a.unidadeProdutivaNome} · {a.nome}
                                      {a.codigo ? ` (${a.codigo})` : ""}
                                      {a.areaHectares != null
                                        ? ` · ${Number(a.areaHectares).toLocaleString("pt-BR", {
                                            minimumFractionDigits: 2,
                                            maximumFractionDigits: 4,
                                          })} ha`
                                        : ""}
                                    </SelectItem>
                                  ))
                                )}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                            {selectedCultivoId && areaOptions.length > 0 && (
                              <p className="text-xs text-muted-foreground">
                                Talhões já vinculados à safra são ocultados automaticamente para evitar duplicidade.
                              </p>
                            )}
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="cultivo_area_id"
                        render={({ field }) => (
                          <input
                            type="hidden"
                            name={field.name}
                            value={field.value ?? ""}
                            onChange={field.onChange}
                            onBlur={field.onBlur}
                            ref={field.ref}
                          />
                        )}
                      />
                    </div>
                  </section>

                  <section className="rounded-sm border bg-muted/30 p-4">
                    <div className="mb-4">
                      <h3 className="text-sm font-medium text-foreground">Dimensões e período</h3>
                      <p className="text-xs text-muted-foreground">
                        Informe a área da unidade, a participação no arranjo e o intervalo de vigência.
                      </p>
                    </div>

                    <div className="flex flex-col gap-4">
                      <div className="grid gap-4 sm:grid-cols-2">
                        <FormField
                          control={form.control}
                          name="area_ha"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Área (ha) *</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  step="0.0001"
                                  placeholder="0,0000"
                                  name={field.name}
                                  value={toInputValue(field.value)}
                                  onChange={field.onChange}
                                  onBlur={field.onBlur}
                                  ref={field.ref}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="percentual_participacao"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Participação (%)</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  step="0.01"
                                  min={0}
                                  max={100}
                                  name={field.name}
                                  value={toInputValue(field.value)}
                                  onChange={field.onChange}
                                  onBlur={field.onBlur}
                                  ref={field.ref}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <div className="grid gap-4 sm:grid-cols-2">
                        <FormField
                          control={form.control}
                          name="data_inicio"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Data início</FormLabel>
                              <FormControl>
                                <Input
                                  type="date"
                                  value={typeof field.value === "string" ? field.value : ""}
                                  onChange={field.onChange}
                                  onBlur={field.onBlur}
                                  ref={field.ref}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="data_fim"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Data fim</FormLabel>
                              <FormControl>
                                <Input
                                  type="date"
                                  value={typeof field.value === "string" ? field.value : ""}
                                  onChange={field.onChange}
                                  onBlur={field.onBlur}
                                  ref={field.ref}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </section>
                </div>
              </DialogBody>
            </ScrollArea>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ? "Salvando..." : "Criar unidade operacional"}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

