                                <div className="mt-2 flex items-center justify-between rounded-sm border bg-background p-3">
                                    <div className="space-y-0.5">
                                        <Label htmlFor="ativo" className="text-xs font-bold uppercase">Propriedade Ativa</Label>
                                        <p className="text-[10px] text-muted-foreground">Define se a propriedade está em uso operacional.</p>
                                    </div>
                                    <Controller
                                        control={control}
                                        name="ativo"
                                        render={({ field }) => (
                                            <Switch
                                                id="ativo"
                                                checked={field.value}
                                                onCheckedChange={field.onChange}
                                                disabled={isPending}
                                            />
                                        )}
                                    />
                                </div>
                            </div>
                    </div>

                    <DialogFooter className="border-t px-5 py-3">
                        <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={isPending} className="rounded-sm" size="sm">
                            Cancelar
                        </Button>
                        <Button type="submit" disabled={isPending} className="rounded-sm" size="sm">
                            {isPending ? "Salvando..." : isEdit ? "Salvar Alterações" : "Cadastrar Propriedade"}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

