"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  Activity,
  AlertCircle,
  CalendarRange,
  Factory,
  LineChart,
  Tractor,
  TrendingUp,
  Wallet,
} from "lucide-react";

import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";
import { getSafraLabel } from "@/lib/safra-label";
import { useHasTier } from "@/hooks/use-has-tier";
import { PageHeader } from "@/components/shared/page-header";
import { TierUpgradeCard } from "@/components/shared/tier-upgrade-card";
import { EmptyState } from "@/components/shared/empty-state";
import { StatCard } from "@/components/shared/stat-card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";

interface SafraResumo {
  id: string;
  cultura: string | null;
  ano_safra: string;
  nome?: string | null;
}

interface ProductionUnitResumo {
  id: string;
  cultivo_nome: string | null;
  area_nome: string | null;
}

interface EficienciaWarning {
  codigo: string;
  titulo: string;
  severidade: string;
  mensagem: string;
  origem: string;
}

interface EficienciaItem {
  scope: "SAFRA" | "PRODUCTION_UNIT" | "EQUIPMENT" | "OPERATION";
  id: string;
  label: string;
  safra_id: string;
  production_unit_id?: string | null;
  unidade_produtiva_id?: string | null;
  equipamento_id?: string | null;
  operacao_id?: string | null;
  area_total_ha: number;
  hectares_totais: number;
  horas_totais: number;
  quantidade_operacoes: number;
  quantidade_jornadas: number;
  quantidade_apontamentos: number;
  custo_operacional_total: number;
  custo_operacional_por_hectare: number | null;
  custo_operacional_por_operacao: number | null;
  horas_por_hectare: number | null;
  hectares_por_jornada: number | null;
  resultado_operacional: number | null;
  resultado_por_hectare: number | null;
  margem_pct: number | null;
  sujeito_reconciliacao: boolean;
  observacao_reconciliacao: string | null;
  warnings_relevantes: string[];
  posicao?: number | null;
}

interface EficienciaResponse {
  tenant_id: string;
  gerado_em: string;
  safra_id: string;
  production_unit_id?: string | null;
  unidade_produtiva_id?: string | null;
  data_inicio?: string | null;
  data_fim?: string | null;
  safra: EficienciaItem;
  production_units: EficienciaItem[];
  equipamentos: EficienciaItem[];
  operacoes: EficienciaItem[];
  ranking: EficienciaItem[];
  warnings: EficienciaWarning[];
  sujeito_reconciliacao: boolean;
  observacao_reconciliacao: string | null;
}

const currencyFormatter = new Intl.NumberFormat("pt-BR", {
  style: "currency",
  currency: "BRL",
});

function formatCurrency(value: number | null | undefined) {
  return value === null || value === undefined ? "—" : currencyFormatter.format(value);
}

function formatPercent(value: number | null | undefined) {
  return value === null || value === undefined ? "—" : `${value.toFixed(1)}%`;
}

function formatDate(value: string | null | undefined) {
  if (!value) return "—";
  return new Intl.DateTimeFormat("pt-BR").format(new Date(value));
}

function warningTone(severidade: string) {
  if (severidade === "RISCO_ECONOMICO") {
    return { label: "Risco econômico", badge: "destructive" as const };
  }
  if (severidade === "INCONSISTENCIA_MODERADA") {
    return { label: "Inconsistência moderada", badge: "warning" as const };
  }
  return { label: "Warning leve", badge: "secondary" as const };
}

export default function EficienciaOperacionalAgricolaPage() {
  const hasProfessionalTier = useHasTier("PROFISSIONAL");
  const activeFazendaId = useAppStore((state) => state.activeFazendaId);
  const unidadesProdutivas = useAppStore((state) => state.unidadesProdutivasAutorizadas);

  const [selectedSafraId, setSelectedSafraId] = useState<string>("");
  const [selectedProductionUnitId, setSelectedProductionUnitId] = useState<string>("TODAS");
  const [selectedUnidadeProdutivaId, setSelectedUnidadeProdutivaId] = useState<string>("");
  const [dataInicio, setDataInicio] = useState<string>("");
  const [dataFim, setDataFim] = useState<string>("");

  const effectiveUnidadeProdutivaId = selectedUnidadeProdutivaId || activeFazendaId || "";
  const safraScopeId = effectiveUnidadeProdutivaId || undefined;

  const { data: safras = [], isLoading: isLoadingSafras, isError: isErrorSafras, error: safraError } = useQuery<SafraResumo[]>({
    queryKey: ["agricola-eficiencia", "safras", safraScopeId],
    queryFn: () => apiFetch(`/safras${safraScopeId ? `?unidade_produtiva_id=${safraScopeId}` : ""}`),
    enabled: hasProfessionalTier,
  });

  const effectiveSafraId = selectedSafraId || safras[0]?.id || "";

  const { data: productionUnits = [], isLoading: isLoadingProductionUnits } = useQuery<ProductionUnitResumo[]>({
    queryKey: ["agricola-eficiencia", "production-units", effectiveSafraId],
    queryFn: () => apiFetch(`/safras/${effectiveSafraId}/production-units`),
    enabled: hasProfessionalTier && !!effectiveSafraId,
  });

  const eficienciaParams = useMemo(() => {
    if (!effectiveSafraId) return null;
    return {
      safra_id: effectiveSafraId,
      production_unit_id: selectedProductionUnitId !== "TODAS" ? selectedProductionUnitId : undefined,
      unidade_produtiva_id: effectiveUnidadeProdutivaId || undefined,
      data_inicio: dataInicio || undefined,
      data_fim: dataFim || undefined,
    };
  }, [dataFim, dataInicio, effectiveSafraId, effectiveUnidadeProdutivaId, selectedProductionUnitId]);

  const {
    data: eficiencia,
    isLoading: isLoadingEficiencia,
    isError: isErrorEficiencia,
    error: eficienciaError,
  } = useQuery<EficienciaResponse>({
    queryKey: ["agricola-eficiencia", "v1", eficienciaParams],
    queryFn: () => apiFetch("/agricola/eficiencia/v1", { params: eficienciaParams ?? undefined }),
    enabled: hasProfessionalTier && !!eficienciaParams,
  });

  const safraAtual = safras.find((safra) => safra.id === effectiveSafraId) ?? null;
  const highlightedUnit =
    eficiencia?.ranking.find((item) => item.id === selectedProductionUnitId) ??
    eficiencia?.ranking[0] ??
    null;
  const periodLabel =
    eficiencia?.data_inicio || eficiencia?.data_fim
      ? `${formatDate(eficiencia?.data_inicio)} → ${formatDate(eficiencia?.data_fim)}`
      : "Sem recorte temporal";
  const hasWarnings = Boolean(eficiencia?.warnings?.length);

  if (!hasProfessionalTier) {
    return (
      <div className="flex flex-col gap-6 p-6">
        <PageHeader
          title="Eficiência Operacional Agrícola"
          description="Leitura oficial de custo e produtividade derivada da DRE agrícola v1."
          breadcrumbs={[
            { label: "Agrícola", href: "/dashboard/agricola" },
            { label: "Eficiência Operacional" },
          ]}
          icon={<Activity className="size-5" />}
        />
        <TierUpgradeCard
          title="Eficiência operacional disponível no PROFISSIONAL"
          description="A visão oficial reutiliza DRE agrícola v1, rentabilidade oficial e registros operacionais."
          requiredTier="PROFISSIONAL"
          feature="agricola.eficiencia_v1"
          surface="agricola.eficiencia.page"
        />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-6">
      <PageHeader
        title="Eficiência Operacional Agrícola"
        description="Base oficial de custo, horas e produtividade derivada da DRE agrícola v1 e dos registros operacionais."
        breadcrumbs={[
          { label: "Agrícola", href: "/dashboard/agricola" },
          { label: "DRE Agrícola v1", href: "/dashboard/agricola/dre" },
          { label: "Eficiência Operacional", href: "/dashboard/agricola/eficiencia" },
        ]}
        actions={(
          <Button asChild variant="outline" size="sm" className="rounded-sm">
            <Link href="/dashboard/agricola/dre">
              <LineChart className="size-4" />
              Voltar à DRE
            </Link>
          </Button>
        )}
        icon={<Activity className="size-5" />}
      />

      <Alert className="rounded-sm">
        <AlertCircle className="size-4" />
        <AlertTitle>Leitura oficial</AlertTitle>
        <AlertDescription>
          A eficiência consome DREAgricolaV1Service, AgricolaDreKpiService, RentabilidadeService e registros operacionais já existentes. Não há recalculo fora da DRE.
        </AlertDescription>
      </Alert>

      <Card className="rounded-sm shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center gap-2">
            <CalendarRange className="size-4 text-muted-foreground" />
            Filtros oficiais
          </CardTitle>
        </CardHeader>
        <CardContent className="flex flex-col gap-4">
          <div className="grid gap-4 lg:grid-cols-4">
            <div className="flex flex-col gap-1.5">
              <label id="eficiencia-safra-label" className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                Safra
              </label>
              <Select
                value={effectiveSafraId}
                onValueChange={(value) => {
                  setSelectedSafraId(value);
                  setSelectedProductionUnitId("TODAS");
                }}
                disabled={isLoadingSafras || safras.length === 0}
              >
                <SelectTrigger aria-labelledby="eficiencia-safra-label" data-testid="eficiencia-safra-select">
                  <SelectValue placeholder={isLoadingSafras ? "Carregando safras..." : "Selecionar safra"} />
                </SelectTrigger>
                <SelectContent>
                  {safras.map((safra) => (
                    <SelectItem key={safra.id} value={safra.id}>
                      {getSafraLabel(safra)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col gap-1.5">
              <label id="eficiencia-unidade-label" className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                Unidade produtiva
              </label>
              <Select
                value={selectedUnidadeProdutivaId || "TODAS"}
                onValueChange={(value) => {
                  setSelectedUnidadeProdutivaId(value === "TODAS" ? "" : value);
                  setSelectedProductionUnitId("TODAS");
                }}
                disabled={!unidadesProdutivas.length}
              >
                <SelectTrigger aria-labelledby="eficiencia-unidade-label" data-testid="eficiencia-unidade-produtiva-select">
                  <SelectValue placeholder="Todas as unidades" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TODAS">Todas as unidades</SelectItem>
                  {unidadesProdutivas.map((unidade) => (
                    <SelectItem key={unidade.id} value={unidade.id}>
                      {unidade.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col gap-1.5">
              <label id="eficiencia-pu-label" className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                ProductionUnit
              </label>
              <Select
                value={selectedProductionUnitId}
                onValueChange={setSelectedProductionUnitId}
                disabled={isLoadingProductionUnits || productionUnits.length === 0}
              >
                <SelectTrigger aria-labelledby="eficiencia-pu-label" data-testid="eficiencia-production-unit-select">
                  <SelectValue placeholder={isLoadingProductionUnits ? "Carregando..." : "Todas as unidades"} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TODAS">Todas as unidades</SelectItem>
                  {productionUnits.map((unit) => (
                    <SelectItem key={unit.id} value={unit.id}>
                      {unit.cultivo_nome ?? "Cultivo"} • {unit.area_nome ?? unit.id.slice(0, 8)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1.5">
                <label htmlFor="eficiencia-data-inicio" className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                  Início
                </label>
                <Input
                  id="eficiencia-data-inicio"
                  data-testid="eficiencia-data-inicio"
                  type="date"
                  value={dataInicio}
                  onChange={(event) => setDataInicio(event.target.value)}
                  className="rounded-sm"
                />
              </div>
              <div className="flex flex-col gap-1.5">
                <label htmlFor="eficiencia-data-fim" className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                  Fim
                </label>
                <Input
                  id="eficiencia-data-fim"
                  data-testid="eficiencia-data-fim"
                  type="date"
                  value={dataFim}
                  onChange={(event) => setDataFim(event.target.value)}
                  className="rounded-sm"
                />
              </div>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            <Badge variant="secondary" className="rounded-sm">DREAgricolaV1Service</Badge>
            <Badge variant="secondary" className="rounded-sm">AgricolaDreKpiService</Badge>
            <Badge variant="secondary" className="rounded-sm">RentabilidadeService</Badge>
          </div>
        </CardContent>
      </Card>

      {isErrorSafras ? (
        <Alert variant="destructive" className="rounded-sm">
          <AlertCircle className="size-4" />
          <AlertTitle>Falha ao carregar safras</AlertTitle>
          <AlertDescription>{safraError instanceof Error ? safraError.message : "Não foi possível listar as safras para consolidar a eficiência operacional."}</AlertDescription>
        </Alert>
      ) : isErrorEficiencia ? (
        <Alert variant="destructive" className="rounded-sm">
          <AlertCircle className="size-4" />
          <AlertTitle>Falha ao consolidar a eficiência</AlertTitle>
          <AlertDescription>{eficienciaError instanceof Error ? eficienciaError.message : "Não foi possível carregar a visão oficial de eficiência operacional."}</AlertDescription>
        </Alert>
      ) : eficiencia ? (
        <div className="flex flex-col gap-6">
          {hasWarnings && (
            <Alert className="rounded-sm border-amber-300 bg-amber-50/60">
              <AlertCircle className="size-4 text-amber-600" />
              <AlertTitle>indicadores sujeitos à reconciliação.</AlertTitle>
              <AlertDescription>
                A visão utiliza DRE agrícola v1, rentabilidade oficial e registros operacionais. Warnings relevantes foram propagados para preservar a leitura oficial.
              </AlertDescription>
            </Alert>
          )}

          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5">
            <StatCard
              icon={Wallet}
              label="Custo operacional da safra"
              value={formatCurrency(eficiencia.safra.custo_operacional_total)}
              subtitle={safraAtual ? getSafraLabel(safraAtual) : "Safra consolidada"}
              color="destructive"
            />
            <StatCard
              icon={Factory}
              label="Custo operacional por hectare"
              value={formatCurrency(eficiencia.safra.custo_operacional_por_hectare)}
              subtitle="Base oficial da DRE v1"
              color="primary"
            />
            <StatCard
              icon={Activity}
              label="Horas por hectare"
              value={eficiencia.safra.horas_por_hectare === null ? "—" : eficiencia.safra.horas_por_hectare.toFixed(2)}
              subtitle="Jornadas / hectares"
              color="agro"
            />
            <StatCard
              icon={Tractor}
              label="Hectares por jornada"
              value={eficiencia.safra.hectares_por_jornada === null ? "—" : eficiencia.safra.hectares_por_jornada.toFixed(2)}
              subtitle="Produtividade operacional"
              color="success"
            />
            <StatCard
              icon={TrendingUp}
              label="Resultado por hectare"
              value={formatCurrency(eficiencia.safra.resultado_por_hectare)}
              subtitle="Eficiência econômica"
              color={eficiencia.safra.resultado_por_hectare !== null && eficiencia.safra.resultado_por_hectare < 0 ? "destructive" : "success"}
            />
          </div>

          <div className="grid gap-4 xl:grid-cols-2">
            <Card className="rounded-sm shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <Tractor className="size-4 text-muted-foreground" />
                  Unidade Operacional em destaque
                </CardTitle>
              </CardHeader>
              <CardContent className="flex flex-col gap-4">
                {highlightedUnit ? (
                  <>
                    <div className="flex flex-wrap items-center gap-2">
                      <Badge variant="secondary" className="rounded-sm">
                        {highlightedUnit.posicao ? `#${highlightedUnit.posicao}` : "Destaque"}
                      </Badge>
                      <span className="text-sm font-semibold">{highlightedUnit.label}</span>
                    </div>
                    <div className="grid gap-4 md:grid-cols-2">
                      <StatCard
                        icon={Wallet}
                        label="Custo operacional"
                        value={formatCurrency(highlightedUnit.custo_operacional_total)}
                        subtitle="Base oficial da DRE v1"
                        color="destructive"
                      />
                      <StatCard
                        icon={Activity}
                        label="Horas por hectare"
                        value={highlightedUnit.horas_por_hectare === null ? "—" : highlightedUnit.horas_por_hectare.toFixed(2)}
                        subtitle="Eficiência operacional"
                        color="primary"
                      />
                      <StatCard
                        icon={Factory}
                        label="Custo por hectare"
                        value={formatCurrency(highlightedUnit.custo_operacional_por_hectare)}
                        subtitle="Ranking simples"
                        color="agro"
                      />
                      <StatCard
                        icon={TrendingUp}
                        label="Resultado por hectare"
                        value={formatCurrency(highlightedUnit.resultado_por_hectare)}
                        subtitle="Rentabilidade oficial"
                        color={highlightedUnit.resultado_por_hectare !== null && highlightedUnit.resultado_por_hectare < 0 ? "destructive" : "success"}
                      />
                    </div>
                  </>
                ) : (
                  <EmptyState
                    icon={<Tractor />}
                    title="Nenhuma Unidade Operacional no recorte atual"
                    description="A visão oficial de eficiência só exibe unidades derivadas da DRE v1 com os filtros informados."
                  />
                )}
              </CardContent>
            </Card>

            <Card className="rounded-sm shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <AlertCircle className="size-4 text-muted-foreground" />
                  Contexto do recorte
                </CardTitle>
              </CardHeader>
              <CardContent className="grid gap-3 sm:grid-cols-2 text-sm">
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Safra</p>
                  <p className="mt-1 font-medium">{safraAtual ? getSafraLabel(safraAtual) : "—"}</p>
                </div>
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Unidade produtiva</p>
                  <p className="mt-1 font-medium">
                    {!selectedUnidadeProdutivaId
                      ? "Todas as fazendas"
                      : unidadesProdutivas.find((unidade) => unidade.id === selectedUnidadeProdutivaId)?.nome ?? selectedUnidadeProdutivaId}
                  </p>
                </div>
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">ProductionUnit</p>
                  <p className="mt-1 font-medium">
                    {selectedProductionUnitId === "TODAS"
                      ? "Todas as unidades"
                      : productionUnits.find((unit) => unit.id === selectedProductionUnitId)
                        ? `${productionUnits.find((unit) => unit.id === selectedProductionUnitId)?.cultivo_nome ?? "Cultivo"} • ${productionUnits.find((unit) => unit.id === selectedProductionUnitId)?.area_nome ?? selectedProductionUnitId.slice(0, 8)}`
                        : selectedProductionUnitId}
                  </p>
                </div>
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Período</p>
                  <p className="mt-1 font-medium">{periodLabel}</p>
                </div>
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Gerado em</p>
                  <p className="mt-1 font-medium">{formatDate(eficiencia.gerado_em)}</p>
                </div>
                <div className="rounded-sm border border-border/70 p-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Rankeadas</p>
                  <p className="mt-1 font-medium">{eficiencia.ranking.length} unidade(s)</p>
                </div>
              </CardContent>
            </Card>
          </div>

          <Card className="rounded-sm shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm flex items-center gap-2">
                <TrendingUp className="size-4 text-muted-foreground" />
                Ranking simples de eficiência
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              {eficiencia.ranking.length === 0 ? (
                <EmptyState
                  icon={<TrendingUp />}
                  title="Nenhuma unidade para ranquear"
                  description="A visão atual não encontrou Units Operacionais após aplicar os filtros oficiais."
                />
              ) : (
                <Table data-testid="eficiencia-ranking-table">
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-20">Pos.</TableHead>
                      <TableHead>Unidade Operacional</TableHead>
                      <TableHead className="text-right">Custo/ha</TableHead>
                      <TableHead className="text-right">Horas/ha</TableHead>
                      <TableHead className="text-right">Resultado/ha</TableHead>
                      <TableHead className="text-right">Warnings</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {eficiencia.ranking.map((item) => (
                      <TableRow key={item.id} className={cn(item.id === selectedProductionUnitId && "bg-muted/30")}>
                        <TableCell className="font-black tabular-nums">{item.posicao ?? "—"}</TableCell>
                        <TableCell>
                          <div className="flex flex-col gap-1">
                            <span className="font-semibold">{item.label}</span>
                            <span className="text-xs text-muted-foreground">{item.area_total_ha.toFixed(1)} ha</span>
                          </div>
                        </TableCell>
                        <TableCell className="text-right font-bold tabular-nums">{formatCurrency(item.custo_operacional_por_hectare)}</TableCell>
                        <TableCell className="text-right font-bold tabular-nums">{item.horas_por_hectare === null ? "—" : item.horas_por_hectare.toFixed(2)}</TableCell>
                        <TableCell className="text-right font-bold tabular-nums">{formatCurrency(item.resultado_por_hectare)}</TableCell>
                        <TableCell className="text-right">
                          <Badge variant={item.warnings_relevantes.length > 0 ? "warning" : "secondary"} className="rounded-sm">
                            {item.warnings_relevantes.length}
                          </Badge>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>

          <div className="grid gap-4 xl:grid-cols-2">
            <Card className="rounded-sm shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <Activity className="size-4 text-muted-foreground" />
                  Equipamentos
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {eficiencia.equipamentos.length === 0 ? (
                  <EmptyState
                    icon={<Activity />}
                    title="Nenhum equipamento no recorte atual"
                    description="Os equipamentos aparecem quando há jornadas ou apontamentos operacionais no período."
                  />
                ) : (
                  <Table data-testid="eficiencia-equipamentos-table">
                    <TableHeader>
                      <TableRow>
                        <TableHead>Equipamento</TableHead>
                        <TableHead className="text-right">Horas</TableHead>
                        <TableHead className="text-right">Hectares</TableHead>
                        <TableHead className="text-right">Custo total</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {eficiencia.equipamentos.slice(0, 8).map((item) => (
                        <TableRow key={item.id}>
                          <TableCell className="font-semibold">{item.label}</TableCell>
                          <TableCell className="text-right tabular-nums">{item.horas_totais.toFixed(1)}</TableCell>
                          <TableCell className="text-right tabular-nums">{item.hectares_totais.toFixed(1)}</TableCell>
                          <TableCell className="text-right font-bold tabular-nums">{formatCurrency(item.custo_operacional_total)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>

            <Card className="rounded-sm shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm flex items-center gap-2">
                  <Factory className="size-4 text-muted-foreground" />
                  Operações
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {eficiencia.operacoes.length === 0 ? (
                  <EmptyState
                    icon={<Factory />}
                    title="Nenhuma operação no recorte atual"
                    description="As operações aparecem quando há produção agrícola registrada no período."
                  />
                ) : (
                  <Table data-testid="eficiencia-operacoes-table">
                    <TableHeader>
                      <TableRow>
                        <TableHead>Operação</TableHead>
                        <TableHead className="text-right">Hectares</TableHead>
                        <TableHead className="text-right">Custo total</TableHead>
                        <TableHead className="text-right">Custo/ha</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {eficiencia.operacoes.slice(0, 8).map((item) => (
                        <TableRow key={item.id}>
                          <TableCell className="font-semibold">{item.label}</TableCell>
                          <TableCell className="text-right tabular-nums">{item.hectares_totais.toFixed(1)}</TableCell>
                          <TableCell className="text-right font-bold tabular-nums">{formatCurrency(item.custo_operacional_total)}</TableCell>
                          <TableCell className="text-right font-bold tabular-nums">{formatCurrency(item.custo_operacional_por_hectare)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </div>

          <Card className="rounded-sm shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm flex items-center gap-2">
                <AlertCircle className="size-4 text-muted-foreground" />
                Warnings propagados
              </CardTitle>
            </CardHeader>
            <CardContent className="flex flex-col gap-3">
              {eficiencia.warnings.length === 0 ? (
                <EmptyState
                  icon={<AlertCircle />}
                  title="Nenhum warning no recorte atual"
                  description="A eficiência operacional não encontrou inconsistências relevantes no período e filtros aplicados."
                />
              ) : (
                eficiencia.warnings.map((warning) => {
                  const tone = warningTone(warning.severidade);
                  return (
                    <div key={`${warning.codigo}-${warning.origem}`} className="rounded-sm border border-border/70 p-4 flex flex-col gap-3">
                      <div className="flex flex-wrap items-start justify-between gap-3">
                        <div className="flex flex-col gap-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <Badge variant={tone.badge} className="rounded-sm">
                              {tone.label}
                            </Badge>
                            <span className="text-xs text-muted-foreground">{warning.codigo}</span>
                          </div>
                          <p className="font-semibold text-sm">{warning.titulo}</p>
                          <p className="text-sm text-muted-foreground">{warning.mensagem}</p>
                        </div>
                        <Badge variant="outline" className="rounded-sm">
                          {warning.origem}
                        </Badge>
                      </div>
                    </div>
                  );
                })
              )}
            </CardContent>
          </Card>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useState, useMemo, useCallback, useRef, useEffect } from "react";
import Map, { NavigationControl, Source, Layer, GeolocateControl, ScaleControl, MapRef } from "react-map-gl/maplibre";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import * as turf from "@turf/turf";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    Plus, Save, Undo2, MousePointerClick, Satellite as SatelliteIcon,
    Map as MapIcon, Crosshair, Layers as LayersIcon, Activity,
    TrendingUp, Info, Tractor, ArrowUpRight, Hexagon, Maximize2,
    Trash2, Edit3, MapPin, Box, FileUp
} from "lucide-react";
import { PageHeader } from "@/components/shared/page-header";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Card, CardContent } from "@/components/ui/card";

// -- Configs
const INITIAL_VIEW_STATE = {
    longitude: -51.9253,
    latitude: -23.4205,
    zoom: 4
};

const MAP_STYLES = {
    STREETS: "https://basemaps.cartocdn.com/gl/positron-gl-style/style.json",
    SATELLITE: {
        version: 8,
        sources: {
            "satellite-tiles": {
                type: "raster",
                tiles: ["https://mt1.google.com/vt/lyrs=s&x={x}&y={y}&z={z}"],
                tileSize: 256,
                attribution: "© Google"
            }
        },
        layers: [{ id: "satellite-layer", type: "raster", source: "satellite-tiles" }]
    }
};

type DrawingType = "TALHAO" | "PERIMETRO_FAZENDA";

export default function MapaGeoprocessamentoPage() {
    const { activeFazendaId } = useAppStore();
    const queryClient = useQueryClient();
    const mapRef = useRef<MapRef>(null);

    // State
    const [mapStyle, setMapStyle] = useState<any>(MAP_STYLES.SATELLITE);
    const [overlay, setOverlay] = useState<"none" | "ndvi" | "productivity">("none");
    const [drawingMode, setDrawingMode] = useState(false);
    const [drawingType, setDrawingType] = useState<DrawingType>("TALHAO");
    const [drawnFeatures, setDrawnFeatures] = useState<GeoJSON.Feature[]>([]);
    const [nomeTalhao, setNomeTalhao] = useState("");
    const [selectedTalhao, setSelectedTalhao] = useState<any>(null);
    const [hoveredTalhao, setHoveredTalhao] = useState<any>(null);
    const [mapCursor, setMapCursor] = useState<string>("grab");
    const [view3d, setView3d] = useState(false);

    // --- DATA FETCHING ---
    const { data: configs } = useQuery({
        queryKey: ["tenant-configs", "mapas"],
        queryFn: () => apiFetch<any[]>("/config/tenant?categoria=mapas")
    });

    const is3dEnabled = useMemo(() => configs?.find(c => c.chave === "enable_3d_terrain")?.valor?.enabled, [configs]);
    const isTrailEnabled = useMemo(() => configs?.find(c => c.chave === "telemetry_trail")?.valor?.enabled, [configs]);
    const isKmlEnabled = useMemo(() => configs?.find(c => c.chave === "kml_import")?.valor?.enabled, [configs]);

    const { data: fazenda } = useQuery({
        queryKey: ["fazenda", activeFazendaId],
        queryFn: () => apiFetch<any>(`/fazendas/${activeFazendaId}`),
        enabled: !!activeFazendaId
    });

    const { data: talhoes = [], isLoading: loadingTalhoes } = useQuery({
        queryKey: ["talhoes", activeFazendaId],
        queryFn: () => apiFetch<any[]>(`/cadastros/areas-rurais/?tipo=TALHAO&unidade_produtiva_id=${activeFazendaId}`),
        enabled: !!activeFazendaId
    });

    // --- MUTATIONS ---
    const updateFazendaMutation = useMutation({
        mutationFn: (payload: any) => apiFetch(`/fazendas/${activeFazendaId}`, { method: "PUT", body: JSON.stringify(payload) }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["fazenda", activeFazendaId] });
            toast.success("Perímetro da fazenda atualizado!");
            setDrawingMode(false);
            setDrawnFeatures([]);
        }
    });

    const createTalhaoMutation = useMutation({
        mutationFn: (payload: any) => apiFetch("/cadastros/areas-rurais/", { method: "POST", body: JSON.stringify(payload) }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["talhoes", activeFazendaId] });
            toast.success("Talhão registrado com sucesso!");
            setDrawingMode(false);
            setDrawnFeatures([]);
            setNomeTalhao("");
        }
    });

    // --- LOGIC ---
    useEffect(() => {
        if (!loadingTalhoes && talhoes?.length > 0 && mapRef.current) {
            const features = talhoes.filter((t: any) => t.geometria_geojson);
            if (features.length > 0) {
                const collection = turf.featureCollection(features.map(t => ({ type: "Feature", geometry: t.geometria_geojson, properties: {} })));
                const bbox = turf.bbox(collection);
                mapRef.current.fitBounds([[bbox[0], bbox[1]], [bbox[2], bbox[3]]], { padding: 100, duration: 1000 });
            }
        } else if (fazenda?.geometria && mapRef.current) {
            const bbox = turf.bbox(fazenda.geometria);
            mapRef.current.fitBounds([[bbox[0], bbox[1]], [bbox[2], bbox[3]]], { padding: 100, duration: 1000 });
        }
    }, [talhoes?.length, fazenda?.geometria, loadingTalhoes]);

    const onHover = useCallback((event: any) => {
        if (drawingMode) return;

        const features = event.target.queryRenderedFeatures(event.point, { layers: ["talhoes-fill"] });
        if (features.length > 0) {
            setMapCursor("pointer");
            const t = talhoes.find((t: any) => t.id === features[0].properties?.id);
            setHoveredTalhao(t);
        } else {
            setMapCursor("grab");
            setHoveredTalhao(null);
        }
    }, [drawingMode, talhoes]);

    const onMapClick = useCallback((event: maplibregl.MapMouseEvent) => {
        if (drawingMode) {
            const { lng, lat } = event.lngLat;
            const coord = [lng, lat];

            setDrawnFeatures(prev => {
                if (prev.length === 0) {
                    return [{
                        type: "Feature",
                        properties: {},
                        geometry: { type: "Polygon", coordinates: [[coord, coord, coord, coord]] }
                    }];
                } else {
                    const poly = prev[0] as GeoJSON.Feature<GeoJSON.Polygon>;
                    const coords = [...poly.geometry.coordinates[0]];
                    coords.splice(coords.length - 1, 0, coord);
                    return [{ type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [coords] } }];
                }
            });
        } else {
            const features = event.target.queryRenderedFeatures(event.point, { layers: ["talhoes-fill"] });
            if (features.length > 0) {
                const t = talhoes.find((t: any) => t.id === features[0].properties?.id);
                setSelectedTalhao(t);
            } else {
                setSelectedTalhao(null);
            }
        }
    }, [drawingMode, talhoes]);

    const calculatedArea = useMemo(() => {
        if (drawnFeatures.length > 0) {
            const poly = drawnFeatures[0] as any;
            if (poly.geometry.coordinates[0].length >= 4) {
                const areaM2 = turf.area(poly);
                return areaM2 / 10000;
            }
        }
        return 0;
    }, [drawnFeatures]);

    const handleSave = () => {
        if (calculatedArea === 0) return toast.error("Desenhe um polígono válido.");

        if (drawingType === "PERIMETRO_FAZENDA") {
            updateFazendaMutation.mutate({ geometria: drawnFeatures[0].geometry, area_total_ha: calculatedArea });
        } else {
            if (!nomeTalhao) return toast.error("Informe o nome do talhão.");
            createTalhaoMutation.mutate({ nome: nomeTalhao, unidade_produtiva_id: activeFazendaId, geometria_geojson: drawnFeatures[0].geometry, area_ha_manual: calculatedArea });
        }
    };

    return (
        <div className="p-6 space-y-6 h-[calc(100vh-90px)] flex flex-col">
            <PageHeader
                title={`Geoprocessamento | ${fazenda?.nome || "Fazenda"}`}
                description="Cartografia Digital • Satélite Ativo"
                icon={<MapPin className="text-primary" size={22} />}
                breadcrumbs={[{ label: "Agrícola", href: "/agricola" }, { label: "Mapas" }]}
                actions={
                    <div className="flex agro-glass p-1 rounded-sm ring-1 ring-black/5 shadow-2xl gap-1">
                        <Button variant={mapStyle === MAP_STYLES.STREETS ? "secondary" : "ghost"} size="sm" className="rounded-sm" onClick={() => setMapStyle(MAP_STYLES.STREETS)}>
                            <MapIcon className="size-4 mr-2" /> Mapa
                        </Button>
                        <Button variant={mapStyle === MAP_STYLES.SATELLITE ? "secondary" : "ghost"} size="sm" className="rounded-sm" onClick={() => setMapStyle(MAP_STYLES.SATELLITE)}>
                            <SatelliteIcon className="size-4 mr-2" /> Satélite
                        </Button>
                        <div className="w-px bg-border mx-1" />
                        {!drawingMode ? (
                            <DropdownMenu>
                                <DropdownMenuTrigger 
                                    render={
                                        <Button variant="outline" size="sm" className="gap-2">
                                            <Plus className="size-4" /> Mapear Área
                                        </Button>
                                    }
                                />
                                <DropdownMenuContent align="end" className="w-56 agro-glass p-2">
                                    <DropdownMenuItem className="gap-2 rounded-sm" onClick={() => { setDrawingMode(true); setDrawingType("TALHAO"); }}>
                                        <Hexagon className="size-4 text-primary" /> Novo Talhão
                                    </DropdownMenuItem>
                                    <DropdownMenuItem className="gap-2 rounded-sm font-bold" onClick={() => { setDrawingMode(true); setDrawingType("PERIMETRO_FAZENDA"); }}>
                                        <Maximize2 className="size-4 text-orange-500" /> Perímetro da Fazenda
                                    </DropdownMenuItem>
                                </DropdownMenuContent>
                            </DropdownMenu>
                        ) : (
                            <div className="flex gap-1 animate-in zoom-in duration-300">
                                <Badge variant="secondary" className="bg-orange-500/10 text-orange-600 border-none px-4 flex items-center gap-2 rounded-sm">
                                    <span className="animate-pulse w-2 h-2 rounded-full bg-orange-600" />
                                    {drawingType === "TALHAO" ? "Novo Talhão" : "Limite Fazenda"}
                                </Badge>
                                <Button variant="ghost" size="sm" className="rounded-sm" onClick={() => { setDrawingMode(false); setDrawnFeatures([]); }}>Cancelar</Button>
                            </div>
                        )}
                    </div>
                }
            />

            <div className="relative flex-1 rounded-sm overflow-hidden shadow-2xl border border-border flex flex-col lg:flex-row bg-muted/50 backdrop-blur-3xl">
                {/* Drawing Sidebar */}
                {drawingMode && (
                    <div className="w-full lg:w-80 agro-glass border-b lg:border-b-0 lg:border-r border-primary/10 p-8 flex flex-col gap-8 z-10 animate-in fade-in duration-200">
                        <div>
                            <h3 className="text-xl font-black uppercase italic">Editor Vetorial</h3>
                            <p className="text-[10px] text-muted-foreground font-bold tracking-widest mt-1">Marque os pontos no mapa conforme o limite físico.</p>
                        </div>

                        <div className="space-y-6">
                            {isKmlEnabled && (
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase text-primary tracking-widest px-1">Interoperabilidade</label>
                                    <Button variant="outline" className="w-full h-12 rounded-sm border-primary/20 text-primary font-bold gap-2 bg-primary/5 hover:bg-primary/10 transition-all shadow-sm" onClick={() => toast.info("Módulo de parsing KML/Shapefile: Aguardando upload...")}>
                                        <FileUp size={16} /> Importar KML / SHP
                                    </Button>
                                </div>
                            )}

                            {drawingType === "TALHAO" && (
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase text-primary tracking-widest px-1">Nome do Talhão</label>
                                    <Input placeholder="Ex: G-04 Soja Safrinha" value={nomeTalhao} onChange={(e) => setNomeTalhao(e.target.value)} className="h-12 rounded-sm bg-background/50 border-primary/20 focus-visible:ring-primary/20" />
                                </div>
                            )}

                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase text-primary tracking-widest px-1">Superfície Cartográfica</label>
                                <div className="p-6 bg-primary/5 rounded-sm border border-primary/10 flex justify-between items-baseline shadow-inner">
                                    <span className="text-4xl font-black text-primary font-mono tabular-nums leading-none">{calculatedArea.toFixed(2)}</span>
                                    <span className="text-[10px] font-black text-primary/40 uppercase">hectares</span>
                                </div>
                            </div>
                        </div>

                        <div className="mt-auto space-y-3">
                            <Button variant="outline" className="w-full h-12 rounded-sm border-orange-200 text-orange-600 hover:bg-orange-50 font-bold" onClick={() => setDrawnFeatures([])}>
                                <Undo2 className="size-4 mr-2" /> Limpar Esboço
                            </Button>
                            <Button className="w-full h-14 rounded-sm font-black shadow-xl shadow-primary/20 text-lg hover:scale-[1.02] transition-transform" onClick={handleSave} disabled={calculatedArea === 0}>
                                <Save className="w-5 h-5 mr-3" /> Finalizar Mapa
                            </Button>
                        </div>
                    </div>
                )}

                {/* Map Interface */}
                <div className="flex-1 relative">
                    <div className="absolute top-4 left-4 z-10 w-64 agro-glass p-2 rounded-sm shadow-xl flex gap-2 ring-1 ring-black/5">
                        <Input
                            placeholder="Buscar coordenada..."
                            className="h-9 rounded-sm text-[11px] bg-background/50 border-none focus-visible:ring-primary/20"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    const val = (e.target as HTMLInputElement).value;
                                    const coords = val.split(',').map(n => Number(n.trim()));
                                    if (coords.length === 2 && !isNaN(coords[0]) && !isNaN(coords[1])) {
                                        mapRef.current?.flyTo({ center: [coords[1], coords[0]], zoom: 16 });
                                        toast.success("Navegando para coordenada");
                                    } else {
                                        toast.error("Formato: lat, lng");
                                    }
                                }
                            }}
                        />
                        <Button size="icon" variant="ghost" className="h-9 w-9 rounded-sm hover:bg-primary/10">
                            <MapPin size={16} className="text-primary" />
                        </Button>
                    </div>

                    <Map
                        ref={mapRef}
                        mapLib={maplibregl}
                        initialViewState={INITIAL_VIEW_STATE}
                        mapStyle={mapStyle}
                        style={{ width: "100%", height: "100%" }}
                        onClick={onMapClick}
                        onMouseMove={onHover}
                        cursor={drawingMode ? "crosshair" : mapCursor}
                        terrain={is3dEnabled && view3d ? { source: "terrain-source", exaggeration: 1.5 } : undefined}
                    >
                        <NavigationControl position="top-right" showCompass={view3d} />
                        <GeolocateControl position="top-right" />
                        <ScaleControl position="bottom-right" />

                        {is3dEnabled && (
                            <Source
                                id="terrain-source"
                                type="raster-dem"
                                url="https://demotiles.maplibre.org/terrain-tiles/tiles.json"
                                tileSize={256}
                            />
                        )}

                        {/* Top Perspective Toggle */}
                        {is3dEnabled && (
                            <div className="absolute top-4 right-14 z-10">
                                <Button
                                    size="sm"
                                    variant={view3d ? "secondary" : "outline"}
                                    className={`rounded-sm agro-glass border-none shadow-xl transition-all ${view3d ? 'text-primary font-black' : 'text-muted-foreground opacity-70'}`}
                                    onClick={() => {
                                        const next = !view3d;
                                        setView3d(next);
                                        if (next) {
                                            mapRef.current?.easeTo({ pitch: 60, bearing: -20, duration: 1000 });
                                        } else {
                                            mapRef.current?.easeTo({ pitch: 0, bearing: 0, duration: 1000 });
                                        }
                                    }}
                                >
                                    <Box className="size-4 mr-2" /> 3D View
                                </Button>
                            </div>
                        )}

                        {/* Farm Boundary Layer */}
                        {fazenda?.geometria && (
                            <Source id="fazenda-boundary" type="geojson" data={fazenda.geometria}>
                                <Layer id="fazenda-line" type="line" paint={{ "line-color": "#ffffff", "line-width": 3, "line-dasharray": [2, 1], "line-opacity": 0.5 }} />
                                <Layer id="fazenda-glow" type="line" paint={{ "line-color": "#ffffff", "line-width": 8, "line-blur": 10, "line-opacity": 0.2 }} />
                            </Source>
                        )}

                        {/* Machine Trail Layer (Simulated) */}
                        {isTrailEnabled && (
                            <Source id="trail-source" type="geojson" data={{
                                type: "FeatureCollection",
                                features: [{
                                    type: "Feature",
                                    geometry: {
                                        type: "LineString",
                                        coordinates: [
                                            [-51.9253, -23.4205], [-51.926, -23.421], [-51.927, -23.420], [-51.928, -23.422]
                                        ]
                                    },
                                    properties: {}
                                }]
                            }}>
                                <Layer id="trail-glow" type="line" paint={{ "line-color": "#fbbf24", "line-width": 8, "line-blur": 6, "line-opacity": 0.3 }} />
                                <Layer id="trail-line" type="line" paint={{ "line-color": "#fbbf24", "line-width": 2.5, "line-opacity": 0.9 }} />
                            </Source>
                        )}

                        {/* Talhões Layer */}
                        <Source id="talhoes-source" type="geojson" data={{
                            type: "FeatureCollection",
                            features: [
                                ...(talhoes || []).filter((t: any) => t.geometria_geojson).map((t: any) => ({
                                    type: "Feature",
                                    geometry: t.geometria_geojson,
                                    properties: { id: t.id, nome: t.nome, area: t.area_efetiva_ha }
                                })),
                                ...drawnFeatures
                            ] as any
                        }}>
                            <Layer id="talhoes-fill" type="fill" paint={{
                                "fill-color": ["case",
                                    ["==", ["get", "id"], hoveredTalhao?.id || ""], "#81C784",
                                    ["has", "id"], "#4CAF50",
                                    "#FFC107"
                                ],
                                "fill-opacity": ["case", ["has", "id"], 0.4, 0.6]
                            }} />
                            <Layer id="talhoes-border" type="line" paint={{
                                "line-color": "#ffffff",
                                "line-width": ["case", ["==", ["get", "id"], hoveredTalhao?.id || ""], 3, 1.5],
                                "line-opacity": ["case", ["==", ["get", "id"], hoveredTalhao?.id || ""], 1, 0.7]
                            }} />
                            <Layer id="talhoes-label" type="symbol" layout={{ "text-field": ["get", "nome"], "text-size": 11 }} paint={{ "text-color": "#fff", "text-halo-color": "#000", "text-halo-width": 1 }} />
                        </Source>
                    </Map>

                    {/* Quick Info Tooltip (Floating) */}
                    {hoveredTalhao && !selectedTalhao && (
                        <div className="absolute agro-glass px-3 py-1.5 rounded-sm shadow-xl pointer-events-none z-50 animate-in fade-in zoom-in duration-200" style={{ left: '50%', top: '50%', transform: 'translate(-50%, -120%)' }}>
                            <p className="text-[10px] font-black uppercase text-primary leading-none">{hoveredTalhao.nome}</p>
                            <p className="text-[9px] font-bold opacity-60">{Number(hoveredTalhao.area_efetiva_ha).toFixed(1)} ha</p>
                        </div>
                    )}

                    {/* Right Panel: Data Analysis */}
                    {selectedTalhao && (
                        <div className="absolute top-4 right-4 bottom-4 w-80 agro-glass rounded-sm shadow-2xl flex flex-col z-50 animate-in fade-in duration-200 ring-1 ring-black/5 overflow-hidden">
                            <div className="p-8 border-b border-primary/10">
                                <div className="flex items-center justify-between mb-8">
                                    <Badge className="bg-primary/20 text-primary border-none text-[10px] font-black uppercase py-1 px-3 italic">Digital Twin 4.0</Badge>
                                    <Button variant="ghost" size="icon" onClick={() => setSelectedTalhao(null)} className="rounded-full h-8 w-8 hover:bg-destructive/10 hover:text-destructive"><Plus className="rotate-45" /></Button>
                                </div>
                                <h2 className="text-4xl font-black text-foreground leading-tight drop-shadow-sm">{selectedTalhao.nome}</h2>
                                <div className="flex items-center gap-2 mt-3">
                                    <Badge variant="outline" className="text-[9px] font-bold border-primary/20 text-muted-foreground uppercase">{selectedTalhao.cultura_atual || "Soja"}</Badge>
                                    <Badge variant="outline" className="text-[9px] font-bold border-primary/20 text-muted-foreground uppercase">Safra 24/25</Badge>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
                                <div className="grid grid-cols-1 gap-4">
                                    <div className="p-6 bg-background/40 rounded-sm shadow-sm border border-border/50 group hover:border-primary/30 transition-all">
