                breadcrumbs={[{ label: "Agrícola", href: "/agricola" }, { label: "Monitoramento" }, { label: "MIP" }]}
                actions={
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" className="gap-2">
                            <Download size={14} /> Exportar Laudo
