interface DroppableColumnProps {
    id: string;
    children: React.ReactNode;
    items: string[];
}

function DroppableColumn({ id, children, items }: DroppableColumnProps) {
    const { setNodeRef } = useDroppable({
        id: id,
        data: {
            type: "Column",
        },
    });

    return (
        <div ref={setNodeRef} className="flex-1 flex flex-col min-h-[150px]">
            <SortableContext
                id={id}
                items={items}
                strategy={verticalListSortingStrategy}
            >
                {children}
            </SortableContext>
        </div>
    );
}

interface SortableLeadCardProps {
    lead: Lead;
    onClick: () => void;
    onMove: (leadId: string, estagioId: string) => void;
    onConvert: (leadId: string) => void;
    onLose: (lead: Lead) => void;
    estagios: Estagio[];
}

function SortableLeadCard({ lead, onClick, onMove, onConvert, onLose, estagios }: SortableLeadCardProps) {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({
        id: lead.id,
        data: {
            type: "Lead",
            lead,
        },
    });

    const style = {
        transform: CSS.Translate.toString(transform),
        transition,
        opacity: isDragging ? 0.3 : 1,
    };

    return (
        <Card
            ref={setNodeRef}
            style={style}
            className={cn(
                "cursor-default hover:shadow-md transition-shadow group relative",
                isDragging && "ring-2 ring-primary border-primary"
            )}
            onClick={onClick}
        >
            <CardContent className="p-3 space-y-2">
                <div className="flex items-start justify-between">
                    <p className="font-semibold text-sm leading-tight flex-1 pr-6">{lead.nome}</p>
                    <div className="flex items-center gap-1 absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        {/* Drag Handle */}
                        <div
                            {...attributes}
                            {...listeners}
                            className="p-1 cursor-grab active:cursor-grabbing hover:bg-accent rounded-sm"
                        >
                            <GripVertical className="size-3 text-muted-foreground" />
                        </div>
                        <DropdownMenu>
                            <DropdownMenuTrigger
                                className={cn(
                                    buttonVariants({ variant: "ghost", size: "icon-sm" }),
                                    "h-6 w-6 p-0"
                                )}
                                onClick={(e) => e.stopPropagation()}
                            >
                                <MoreHorizontal className="size-3" />
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                                {estagios
                                    .filter((e) => e.id !== lead.estagio_id)
                                    .map((e) => (
                                        <DropdownMenuItem
                                            key={e.id}
                                            onClick={(ev) => {
                                                ev.stopPropagation();
                                                onMove(lead.id, e.id);
                                            }}
                                        >
                                            <ArrowRight className="size-3 mr-2" />
                                            Mover para {e.nome}
                                        </DropdownMenuItem>
                                    ))}
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                    onClick={(ev) => { ev.stopPropagation(); onConvert(lead.id); }}
                                    className="text-green-600"
                                >
                                    <CheckCircle2 className="size-3 mr-2" /> Converter
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                    onClick={(ev) => { ev.stopPropagation(); onLose(lead); }}
                                    className="text-red-600"
                                >
                                    <XCircle className="size-3 mr-2" /> Marcar como perdido
                                </DropdownMenuItem>
                            </DropdownMenuContent>
                        </DropdownMenu>
                    </div>
                </div>

                {lead.empresa && (
                    <div className="flex items-center gap-1 text-xs text-muted-foreground">
                        <Building2 className="size-3" />
                        <span className="truncate">{lead.empresa}</span>
                    </div>
                )}

                <div className="flex items-center justify-between">
                    <Badge className={cn("text-[9px] border font-normal", ORIGENS[lead.origem]?.color ?? ORIGENS.manual.color)}>
                        {ORIGENS[lead.origem]?.label ?? lead.origem}
                    </Badge>
                    {lead.valor_estimado != null && lead.valor_estimado > 0 && (
                        <span className="text-xs font-semibold text-emerald-600">
                            {new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(lead.valor_estimado)}
                        </span>
                    )}
                </div>

                <div className="flex items-center gap-2 text-[10px] text-muted-foreground">
                    {lead.telefone && (
                        <span className="flex items-center gap-0.5">
                            <Phone className="size-2.5" /> {lead.telefone}
                        </span>
                    )}
                    {lead.email && (
                        <span className="flex items-center gap-0.5 truncate">
                            <Mail className="size-2.5" /> {lead.email}
                        </span>
                    )}
                </div>

                <p className="text-[10px] text-muted-foreground">
                    {formatDistanceToNow(new Date(lead.updated_at), { addSuffix: true, locale: ptBR })}
                </p>
            </CardContent>
        </Card>
    );
}

// ==================== COMPONENT ====================

export default function CRMPage() {
    const queryClient = useQueryClient();
    const [activeTab, setActiveTab] = useState("kanban");
    const [showNewLead, setShowNewLead] = useState(false);
    const [showNewEstagio, setShowNewEstagio] = useState(false);
    const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
    const [statusFilter, setStatusFilter] = useState("ativo");
    const [loseTarget, setLoseTarget] = useState<Lead | null>(null);
    const [motivoPerda, setMotivoPerda] = useState("");
    const [convertWizardLead, setConvertWizardLead] = useState<Lead | null>(null);

    // ---- New Lead form ----
    const [newLead, setNewLead] = useState({
        nome: "", email: "", telefone: "", empresa: "", documento: "",
        estagio_id: "", origem: "manual", valor_estimado: "",
        plano_interesse: "", qtd_fazendas: "", qtd_usuarios: "", notas: "",
    });

    // ---- New Estagio form ----
    const [newEstagio, setNewEstagio] = useState({ nome: "", cor: "#3b82f6", ordem: "0" });

    // ---- New Atividade form ----
    const [showNewAtividade, setShowNewAtividade] = useState(false);
    const [newAtividade, setNewAtividade] = useState({ tipo: "nota", descricao: "" });

    // ---- New Oferta form ----
    const [showNewOferta, setShowNewOferta] = useState(false);
    const [newOferta, setNewOferta] = useState({
        tipo_oferta: "plano_padrao",
        plano_base_id: "",
        modulos_selecionados: [] as string[],
        preco_total_mensal: "",
        preco_total_anual: "",
        desconto_percentual: "0",
        justificativa: "",
        vigencia_dias: "30",
    });

    // ==================== QUERIES ====================

    const { data: stats } = useQuery<CRMStats>({
        queryKey: ["crm", "stats"],
        queryFn: () => apiFetch("/backoffice/crm/stats"),
    });

    const { data: kanban, isLoading: kanbanLoading, isFetching: kanbanFetching } = useQuery<KanbanData>({
        queryKey: ["crm", "kanban"],
        queryFn: () => apiFetch("/backoffice/crm/kanban"),
        enabled: activeTab === "kanban",
    });

    const startContainerRef = useRef<string | null>(null);

    // ==================== MUTATIONS ====================

    const invalidateCRM = useCallback(() => {
        queryClient.invalidateQueries({ queryKey: ["crm"] });
    }, [queryClient]);

    const moveLeadMutation = useMutation({
        mutationFn: ({ leadId, estagioId }: { leadId: string; estagioId: string }) =>
            apiFetch(`/backoffice/crm/leads/${leadId}/move`, {
                method: "PATCH",
                body: JSON.stringify({ estagio_id: estagioId }),
            }),
        onSuccess: () => {
            invalidateCRM();
            toast.success("Lead movido!");
        },
        onError: (err: any) => toast.error(err.message || "Erro ao mover lead"),
    });

    const createLeadMutation = useMutation({
        mutationFn: (data: Record<string, unknown>) =>
            apiFetch("/backoffice/crm/leads", { method: "POST", body: JSON.stringify(data) }),
        onSuccess: () => {
            invalidateCRM();
            setShowNewLead(false);
            setNewLead({
                nome: "", email: "", telefone: "", empresa: "", documento: "",
                estagio_id: "", origem: "manual", valor_estimado: "",
                plano_interesse: "", qtd_fazendas: "", qtd_usuarios: "", notas: "",
            });
            toast.success("Lead criado!");
        },
        onError: (err: any) => toast.error(err.message || "Erro ao criar lead"),
    });

    const convertLeadMutation = {
        mutate: (leadId: string) => {
            const lead = (leadsList?.items ?? []).find((l: Lead) => l.id === leadId) ?? selectedLead;
            if (!lead) return;
            setConvertWizardLead(lead);
        },
        isPending: false,
    };

    const loseLeadMutation = useMutation({
        mutationFn: ({ leadId, motivo }: { leadId: string; motivo: string }) =>
            apiFetch(`/backoffice/crm/leads/${leadId}/lose`, {
                method: "PATCH",
                body: JSON.stringify({ motivo_perda: motivo }),
            }),
        onSuccess: () => {
            invalidateCRM();
            setLoseTarget(null);
            setMotivoPerda("");
            setSelectedLead(null);
            toast.success("Lead marcado como perdido");
        },
        onError: (err: any) => toast.error(err.message || "Erro"),
    });

    const reopenLeadMutation = useMutation({
        mutationFn: (leadId: string) =>
            apiFetch(`/backoffice/crm/leads/${leadId}/reopen`, { method: "PATCH" }),
        onSuccess: () => {
            invalidateCRM();
            setSelectedLead(null);
            toast.success("Lead reaberto!");
        },
        onError: (err: any) => toast.error(err.message || "Erro"),
    });

    const createEstagioMutation = useMutation({
        mutationFn: (data: Record<string, unknown>) =>
            apiFetch("/backoffice/crm/pipeline", { method: "POST", body: JSON.stringify(data) }),
        onSuccess: () => {
            invalidateCRM();
            setShowNewEstagio(false);
            setNewEstagio({ nome: "", cor: "#3b82f6", ordem: "0" });
            toast.success("Estágio criado!");
        },
        onError: (err: any) => toast.error(err.message || "Erro"),
    });

    const createAtividadeMutation = useMutation({
        mutationFn: ({ leadId, data }: { leadId: string; data: Record<string, unknown> }) =>
            apiFetch(`/backoffice/crm/leads/${leadId}/atividades`, {
                method: "POST",
                body: JSON.stringify(data),
            }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["crm", "lead", selectedLead?.id] });
            setShowNewAtividade(false);
            setNewAtividade({ tipo: "nota", descricao: "" });
            toast.success("Atividade registrada!");
        },
        onError: (err: any) => toast.error(err.message || "Erro"),
    });

    const toggleAtividadeMutation = useMutation({
        mutationFn: (atividadeId: string) =>
            apiFetch(`/backoffice/crm/atividades/${atividadeId}/toggle`, { method: "PATCH" }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["crm", "lead", selectedLead?.id] });
        },
    });

    const createOfertaMutation = useMutation({
        mutationFn: (data: Record<string, unknown>) =>
            apiFetch(`/backoffice/crm/ofertas/leads/${selectedLead!.id}/oferta`, {
                method: "POST",
                body: JSON.stringify(data),
            }),
        onSuccess: () => {
            invalidateCRM();
            setShowNewOferta(false);
            setNewOferta({
                tipo_oferta: "plano_padrao",
                plano_base_id: "",
                modulos_selecionados: [],
                preco_total_mensal: "",
                preco_total_anual: "",
                desconto_percentual: "0",
                justificativa: "",
                vigencia_dias: "30",
            });
            toast.success("Oferta criada com sucesso!");
        },
        onError: (err: any) => toast.error(err.message || "Erro ao criar oferta"),
    });

    // ---- DND State ----
    const [kanbanLeads, setKanbanLeads] = useState<Record<string, Lead[]>>({});
    const [activeLead, setActiveLead] = useState<Lead | null>(null);

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        }),
        useSensor(KeyboardSensor, {
            coordinateGetter: sortableKeyboardCoordinates,
        })
    );

    // Sync local state when query finishes OR when we are NOT dragging and NOT mutating
    useEffect(() => {
        if (kanban?.leads_por_estagio && !activeLead && !moveLeadMutation.isPending) {
            setKanbanLeads(kanban.leads_por_estagio);
        }
    }, [kanban?.leads_por_estagio, activeLead, moveLeadMutation.isPending]);

    const findContainer = useCallback((id: UniqueIdentifier) => {
        const idAsString = String(id);
        if (idAsString in kanbanLeads) return idAsString;

        return Object.keys(kanbanLeads).find((key) =>
            kanbanLeads[key].some((item) => String(item.id) === idAsString)
        );
    }, [kanbanLeads]);

    const handleDragStart = useCallback((event: DragStartEvent) => {
        const { active } = event;
        const lead = active.data.current?.lead as Lead;
        if (lead) {
            setActiveLead(lead);
            // Capture the starting container
            const startContainer = findContainer(active.id);
            if (startContainer) startContainerRef.current = startContainer;
        }
    }, [findContainer]);

    const handleDragOver = useCallback((event: DragOverEvent) => {
        const { active, over } = event;
        const overId = over?.id;

        if (!overId || active.id === overId) return;

        const activeId = active.id;
        const activeContainer = findContainer(activeId);
        const overContainer = findContainer(overId);

        if (!activeContainer || !overContainer || activeContainer === overContainer) {
            return;
        }

        setKanbanLeads((prev) => {
            const activeItems = prev[activeContainer] || [];
            const overItems = prev[overContainer] || [];

            const activeIndex = activeItems.findIndex((item) => item.id === activeId);
            const overIndex = overItems.findIndex((item) => item.id === overId);

            let newIndex: number;
            if (String(overId) in prev) {
                newIndex = overItems.length;
            } else {
                const isAtEnd = overIndex === overItems.length - 1;
                newIndex = overIndex >= 0 ? overIndex + (isAtEnd ? 1 : 0) : overItems.length;
            }

            const itemToMove = activeItems[activeIndex];
            if (!itemToMove) return prev;

            return {
                ...prev,
                [activeContainer]: activeItems.filter((item) => item.id !== activeId),
                [overContainer]: [
                    ...overItems.slice(0, newIndex),
                    { ...itemToMove, estagio_id: overContainer },
                    ...overItems.slice(newIndex),
                ],
            };
        });
    }, [findContainer]);

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event;
        const overId = over?.id;

        if (!overId) {
            setActiveLead(null);
            startContainerRef.current = null;
            if (kanban?.leads_por_estagio) setKanbanLeads(kanban.leads_por_estagio);
            return;
        }

        const activeId = String(active.id);
        const startContainer = startContainerRef.current;
        const overContainer = findContainer(overId);

        if (!startContainer || !overContainer) {
            setActiveLead(null);
            startContainerRef.current = null;
            return;
        }

        // Check if moved to a different column
        if (startContainer !== overContainer) {
            moveLeadMutation.mutate({ leadId: activeId, estagioId: overContainer });
        } else if (active.id !== overId) {
            // Reorder within the same column
            const oldIndex = kanbanLeads[startContainer]?.findIndex((item) => item.id === activeId);
            const newIndex = kanbanLeads[overContainer]?.findIndex((item) => item.id === String(overId));

            if (oldIndex !== undefined && newIndex !== undefined && oldIndex !== newIndex && oldIndex !== -1 && newIndex !== -1) {
                setKanbanLeads((items) => ({
                    ...items,
                    [overContainer]: arrayMove(items[overContainer], oldIndex, newIndex),
                }));
                // In a production environment, you might want to call a "reorder" mutation here
            }
        }

        setActiveLead(null);
        startContainerRef.current = null;
    }, [findContainer, kanbanLeads, kanban?.leads_por_estagio, moveLeadMutation]);

    const { data: pipeline } = useQuery<Estagio[]>({
        queryKey: ["crm", "pipeline"],
        queryFn: () => apiFetch("/backoffice/crm/pipeline?ativo=true"),
    });

    const { data: planos } = useQuery<PlanoComercial[]>({
        queryKey: ["crm", "ofertas", "planos"],
        queryFn: () => apiFetch("/backoffice/crm/ofertas/planos?ativo_apenas=true"),
        enabled: showNewLead || showNewOferta,
    });

    const { data: modulos } = useQuery<ModuloOferta[]>({
        queryKey: ["crm", "ofertas", "produtos"],
        queryFn: () => apiFetch("/backoffice/crm/ofertas/produtos"),
        enabled: showNewOferta,
    });

    const { data: leadsList, isLoading: leadsLoading } = useQuery<LeadListData>({
        queryKey: ["crm", "leads", statusFilter],
        queryFn: () => {
            const params = new URLSearchParams();
            if (statusFilter) params.set("status", statusFilter);
            return apiFetch(`/backoffice/crm/leads?${params.toString()}`);
        },
        enabled: activeTab === "lista",
    });

    const { data: leadDetail } = useQuery<Lead>({
        queryKey: ["crm", "lead", selectedLead?.id],
        queryFn: () => apiFetch(`/backoffice/crm/leads/${selectedLead!.id}`),
        enabled: !!selectedLead,
    });

    // ==================== HANDLERS ====================

    function handleCreateLead() {
        if (!newLead.nome || !newLead.estagio_id) {
            toast.error("Nome e estágio são obrigatórios");
            return;
        }

        const payload: Record<string, unknown> = {
            nome: newLead.nome,
            estagio_id: newLead.estagio_id,
            origem: newLead.origem,
        };

        if (newLead.email) payload.email = newLead.email;
        if (newLead.telefone) payload.telefone = newLead.telefone;
        if (newLead.empresa) payload.empresa = newLead.empresa;
        if (newLead.documento) payload.documento = newLead.documento;

        if (newLead.valor_estimado) {
            // Converts from formatted currency string back to standard number
            const numVal = parseFloat(newLead.valor_estimado.replace(/\./g, "").replace(",", "."));
            if (!isNaN(numVal)) payload.valor_estimado = numVal;
        }

        if (newLead.plano_interesse) payload.plano_interesse = newLead.plano_interesse;
        if (newLead.qtd_fazendas) payload.qtd_fazendas = parseInt(newLead.qtd_fazendas, 10);
        if (newLead.qtd_usuarios) payload.qtd_usuarios = parseInt(newLead.qtd_usuarios, 10);
        if (newLead.notas) payload.notas = newLead.notas;

        createLeadMutation.mutate(payload);
    }

    function handleCreateEstagio() {
        if (!newEstagio.nome) { toast.error("Nome é obrigatório"); return; }
        createEstagioMutation.mutate({
            nome: newEstagio.nome,
            cor: newEstagio.cor,
            ordem: parseInt(newEstagio.ordem) || 0,
        });
    }

    function handleCreateAtividade() {
        if (!newAtividade.descricao || !selectedLead) { toast.error("Descrição é obrigatória"); return; }
        createAtividadeMutation.mutate({
            leadId: selectedLead.id,
            data: { tipo: newAtividade.tipo, descricao: newAtividade.descricao },
        });
    }

    function handleCreateOferta() {
        if (!newOferta.preco_total_mensal || !newOferta.preco_total_anual) {
            toast.error("Preços (mensal e anual) são obrigatórios");
            return;
        }
        const payload: Record<string, unknown> = {
            tipo_oferta: newOferta.tipo_oferta,
            preco_total_mensal: parseFloat(newOferta.preco_total_mensal),
            preco_total_anual: parseFloat(newOferta.preco_total_anual),
            desconto_percentual: parseFloat(newOferta.desconto_percentual) || 0,
            vigencia_dias: parseInt(newOferta.vigencia_dias) || 30,
        };
        if (newOferta.tipo_oferta === "plano_padrao" && newOferta.plano_base_id) {
            payload.plano_base_id = newOferta.plano_base_id;
        }
        if (newOferta.tipo_oferta === "custom_modular" && newOferta.modulos_selecionados.length > 0) {
            payload.modulos_selecionados = newOferta.modulos_selecionados;
        }
        if (newOferta.justificativa) {
            payload.justificativa = newOferta.justificativa;
        }
        createOfertaMutation.mutate(payload);
    }

    const formatCurrency = (val: number) =>
        new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);

    // ==================== COLUMNS ====================

    const leadsColumns: ColumnDef<Lead>[] = [
        {
            id: "lead",
            header: "Lead",
            accessorKey: "nome",
            cell: (value, row) => (
                <div>
                    <p className="font-medium text-sm">{row.nome}</p>
                    <div className="flex gap-2 text-[10px] text-muted-foreground">
                        {row.email && <span>{row.email}</span>}
                        {row.telefone && <span>{row.telefone}</span>}
                    </div>
                </div>
            ),
        },
        {
            id: "empresa",
            header: "Empresa",
            accessorKey: "empresa",
            cell: (value) => value || "—",
        },
        {
            id: "estagio",
            header: "Estágio",
            accessorKey: "estagio",
            sortable: false,
            filterable: false,
            cell: (value, row) => {
                if (!row.estagio) return null;
                return (
                    <Badge
                        variant="outline"
                        className="text-xs"
                        style={{
                            backgroundColor: row.estagio.cor + "22",
                            color: row.estagio.cor,
                            borderColor: row.estagio.cor + "55",
                        }}
                    >
                        {row.estagio.nome}
                    </Badge>
                );
            },
        },
        {
            id: "origem",
            header: "Origem",
            accessorKey: "origem",
            sortable: false,
            filterable: false,
            cell: (value, row) => {
                const origemConfig = ORIGENS[row.origem] ?? ORIGENS.manual;
                return (
                    <Badge variant="outline" className="text-xs">
                        {origemConfig.label}
                    </Badge>
                );
            },
        },
        {
            id: "valor",
            header: "Valor",
            accessorKey: "valor_estimado",
            cell: (value) => (value ? formatCurrency(value) : "—"),
        },
        {
            id: "status",
            header: "Status",
            accessorKey: "status",
            sortable: false,
            filterable: false,
            cell: (value, row) => (
                row.status === "ativo" ? (
                    <Badge variant="default" className="bg-emerald-600">Ativo</Badge>
                ) : row.status === "convertido" ? (
                    <Badge variant="default">Convertido</Badge>
                ) : (
                    <Badge variant="secondary">Perdido</Badge>
                )
            ),
        },
        {
            id: "atualizado",
            header: "Atualizado",
            accessorKey: "updated_at",
            cell: (value) => (
                <span className="text-xs text-muted-foreground">
                    {formatDistanceToNow(new Date(value), { addSuffix: true, locale: ptBR })}
                </span>
            ),
        },
        {
            id: "acao",
            header: "",
            sortable: false,
            filterable: false,
            exportable: false,
            cell: (_, row) => (
                <Button
                    size="icon"
                    variant="ghost"
                    className="size-7 text-primary hover:text-primary"
                    onClick={(e) => {
                        e.stopPropagation();
                        setSelectedLead(row);
                    }}
                >
                    <Eye className="size-3.5" />
                </Button>
            ),
        },
    ];

    // ==================== LOADING ====================

    if (kanbanLoading && activeTab === "kanban") {
        return (
            <div className="p-6 space-y-6 w-full max-w-full">
                <Skeleton className="h-16 w-full" />
                <div className="grid gap-4 md:grid-cols-4">
                    {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-24" />)}
                </div>
                <div className="flex gap-4">
                    {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-96 w-72" />)}
                </div>
            </div>
        );
    }

    // ==================== RENDER ====================

    return (
        <div className="p-6 space-y-6 w-full max-w-full">
            <PageHeader
                title="CRM"
                description="Gerencie leads e oportunidades comerciais."
                icon={<Target className="text-primary" size={22} />}
                // breadcrumbs={[{ label: "Backoffice" }, { label: "Comercial" }, { label: "CRM" }]}
                actions={
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" onClick={() => setShowNewEstagio(true)}>
                            <Plus className="size-4 mr-1" /> Estágio
                        </Button>
                        <Button size="sm" onClick={() => setShowNewLead(true)}>
                            <Plus className="size-4 mr-1" /> Novo Lead
                        </Button>
                    </div>
                }
            />

            {/* KPIs */}
            <div className="grid gap-4 md:grid-cols-4">
                <StatCard
                    icon={Target}
                    label="Leads Ativos"
                    value={stats?.leads_ativos ?? 0}
                    color="primary"
                />
                <StatCard
                    icon={TrendingUp}
                    label="Convertidos"
                    value={stats?.leads_convertidos ?? 0}
                    color="success"
                />
                <StatCard
                    icon={DollarSign}
                    label="Pipeline"
                    value={formatCurrency(stats?.valor_pipeline ?? 0)}
                    color="warning"
                />
                <StatCard
                    icon={CheckCircle2}
                    label="Conversões/Mês"
                    value={stats?.conversoes_mes ?? 0}
                    color="backoffice"
                />
            </div>

            {/* Tabs: Kanban | Lista */}
            <Tabs value={activeTab} onValueChange={setActiveTab}>
                <DndContext
                    sensors={sensors}
                    collisionDetection={rectIntersection}
                    onDragStart={handleDragStart}
                    onDragOver={handleDragOver}
                    onDragEnd={handleDragEnd}
                >
                    <div className="flex items-center justify-between">
                        <TabsList className="w-full justify-start h-auto gap-1 bg-transparent p-0 border-b rounded-none">
                            <TabsTrigger
                                value="kanban"
                                className="rounded-t-sm border-b-2 border-transparent data-[selected]:border-primary data-[selected]:bg-accent transition-all hover:bg-accent gap-1.5 px-3 py-2"
                            >
                                <LayoutGrid className="size-3.5" /> Kanban
