                        <DragOverlay adjustScale={false}>
                            {activeLead ? (
                                <div className="w-[280px]">
                                    <SortableLeadCard
                                        lead={activeLead}
                                        onClick={() => { }}
                                        onMove={() => { }}
                                        onConvert={() => { }}
                                        onLose={() => { }}
                                        estagios={kanban?.estagios ?? []}
                                    />
                                </div>
