                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="fazendas">Qtd. Fazendas</Label>
                                <Input id="fazendas" type="number" value={newLead.qtd_fazendas} onChange={(e) => setNewLead({ ...newLead, qtd_fazendas: e.target.value })} />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="usuarios">Qtd. Usuários</Label>
                                <Input id="usuarios" type="number" value={newLead.qtd_usuarios} onChange={(e) => setNewLead({ ...newLead, qtd_usuarios: e.target.value })} />
                            </div>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="notas">Notas</Label>
                            <Textarea id="notas" value={newLead.notas} onChange={(e) => setNewLead({ ...newLead, notas: e.target.value })} placeholder="Observações sobre o lead..." rows={3} />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowNewLead(false)}>Cancelar</Button>
                        <Button onClick={handleCreateLead} disabled={createLeadMutation.isPending}>
                            {createLeadMutation.isPending ? "Criando..." : "Criar Lead"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* New Estagio Dialog */}
            <Dialog open={showNewEstagio} onOpenChange={setShowNewEstagio}>
                <DialogContent className="max-w-sm">
                    <DialogHeader>
                        <DialogTitle>Novo Estágio</DialogTitle>
                        <DialogDescription>Adicione uma coluna ao pipeline.</DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-2">
                        <div className="grid gap-2">
                            <Label htmlFor="nome-estagio">Nome *</Label>
                            <Input id="nome-estagio" value={newEstagio.nome} onChange={(e) => setNewEstagio({ ...newEstagio, nome: e.target.value })} placeholder="Ex: Qualificação" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="grid gap-2">
                                <Label htmlFor="cor">Cor</Label>
                                <div className="flex gap-2 items-center">
                                    <input
                                        id="cor"
                                        type="color"
                                        value={newEstagio.cor}
                                        onChange={(e) => setNewEstagio({ ...newEstagio, cor: e.target.value })}
                                        className="w-10 h-9 rounded border cursor-pointer"
                                    />
                                    <Input value={newEstagio.cor} onChange={(e) => setNewEstagio({ ...newEstagio, cor: e.target.value })} className="flex-1" />
                                </div>
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="ordem">Ordem</Label>
                                <Input id="ordem" type="number" value={newEstagio.ordem} onChange={(e) => setNewEstagio({ ...newEstagio, ordem: e.target.value })} />
                            </div>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowNewEstagio(false)}>Cancelar</Button>
                        <Button onClick={handleCreateEstagio} disabled={createEstagioMutation.isPending}>
                            {createEstagioMutation.isPending ? "Criando..." : "Criar Estágio"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Lose Lead Dialog */}
            <Dialog open={!!loseTarget} onOpenChange={() => setLoseTarget(null)}>
                <DialogContent className="max-w-sm">
                    <DialogHeader>
                        <DialogTitle>Marcar como Perdido</DialogTitle>
                        <DialogDescription>
                            Por que o lead <strong>{loseTarget?.nome}</strong> foi perdido?
                        </DialogDescription>
                    </DialogHeader>
                    <Textarea
                        value={motivoPerda}
                        onChange={(e) => setMotivoPerda(e.target.value)}
                        placeholder="Motivo da perda..."
                        rows={3}
                    />
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setLoseTarget(null)}>Cancelar</Button>
                        <Button
                            variant="destructive"
                            onClick={() => loseTarget && loseLeadMutation.mutate({ leadId: loseTarget.id, motivo: motivoPerda })}
                            disabled={!motivoPerda || loseLeadMutation.isPending}
                        >
                            Confirmar Perda
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* New Oferta Dialog */}
            <Dialog open={showNewOferta} onOpenChange={setShowNewOferta}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle>Criar Oferta Personalizada</DialogTitle>
                        <DialogDescription>
                            Para: <strong>{selectedLead?.nome}</strong>
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-4">
                        {/* Tipo de Oferta */}
                        <div className="grid gap-2">
                            <Label htmlFor="tipo-oferta">Tipo de Oferta *</Label>
                            <Select value={newOferta.tipo_oferta} onValueChange={(v: string) => setNewOferta({ ...newOferta, tipo_oferta: v })}>
                                <SelectTrigger id="tipo-oferta">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="plano_padrao">Plano Padrão</SelectItem>
                                    <SelectItem value="custom_modular">Modular (À la carte)</SelectItem>
                                    <SelectItem value="enterprise">Enterprise (Customizado)</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        {/* Plano Base (se plano_padrao) */}
                        {newOferta.tipo_oferta === "plano_padrao" && (
                            <div className="grid gap-2">
                                <Label htmlFor="plano-base">Plano Base</Label>
                                <Select value={newOferta.plano_base_id} onValueChange={(v: string) => setNewOferta({ ...newOferta, plano_base_id: v })}>
                                    <SelectTrigger id="plano-base">
                                        <SelectValue placeholder="Selecione um plano..." />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {planos?.map((p) => (
                                            <SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        )}

                        {/* Módulos (se custom_modular) */}
                        {newOferta.tipo_oferta === "custom_modular" && (
                            <div className="grid gap-2">
                                <Label>Módulos Selecionados</Label>
                                <div className="border rounded p-3 space-y-2 max-h-48 overflow-y-auto">
                                    {modulos?.map((m) => (
                                        <div key={m.id} className="flex items-center gap-2">
                                            <input
                                                type="checkbox"
                                                id={m.id}
                                                checked={newOferta.modulos_selecionados.includes(m.id)}
                                                onChange={(e) => {
                                                    const selected = e.target.checked
                                                        ? [...newOferta.modulos_selecionados, m.id]
                                                        : newOferta.modulos_selecionados.filter(x => x !== m.id);
                                                    setNewOferta({ ...newOferta, modulos_selecionados: selected });
                                                }}
                                                className="rounded"
                                            />
                                            <label htmlFor={m.id} className="text-sm cursor-pointer flex-1">
                                                {m.icone && <span className="mr-1">{m.icone}</span>}
                                                {m.nome}
                                            </label>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Preços */}
                        <div className="grid grid-cols-2 gap-2">
                            <div className="grid gap-2">
                                <Label htmlFor="preco-mensal">Preço Mensal (R$) *</Label>
                                <Input
                                    id="preco-mensal"
                                    type="number"
                                    step="0.01"
                                    value={newOferta.preco_total_mensal}
                                    onChange={(e) => setNewOferta({ ...newOferta, preco_total_mensal: e.target.value })}
                                    placeholder="0.00"
                                />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="preco-anual">Preço Anual (R$) *</Label>
                                <Input
                                    id="preco-anual"
                                    type="number"
                                    step="0.01"
                                    value={newOferta.preco_total_anual}
                                    onChange={(e) => setNewOferta({ ...newOferta, preco_total_anual: e.target.value })}
                                    placeholder="0.00"
                                />
                            </div>
                        </div>

                        {/* Desconto */}
                        <div className="grid gap-2">
