                        <Button variant="outline" onClick={() => setShowNewOferta(false)}>Cancelar</Button>
                        <Button onClick={handleCreateOferta} disabled={createOfertaMutation.isPending}>
                            {createOfertaMutation.isPending ? "Criando..." : "Criar Oferta"}
                        </Button>
                    </DialogFooter>
