                        </SheetDescription>
                    </SheetHeader>

                    {selectedLead && (
                        <div className="mt-6 space-y-6">
                            {/* Contact Info */}
                            <div className="space-y-2">
                                <h4 className="text-xs font-bold uppercase text-muted-foreground tracking-widest">Contato</h4>
                                <div className="grid grid-cols-2 gap-2 text-sm">
