                                    {selectedLead.documento && (
                                        <div className="flex items-center gap-2">
                                            <FileText className="size-3 text-muted-foreground" />
                                            <span>{selectedLead.documento}</span>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <Separator />

                            {/* Pipeline Info */}
                            <div className="space-y-2">
                                <h4 className="text-xs font-bold uppercase text-muted-foreground tracking-widest">Pipeline</h4>
                                <div className="text-sm">
                                    <span className="text-muted-foreground text-xs">Estágio Atual:</span>
                                    <p className="font-semibold">
                                        {selectedLead?.estagio ? (
                                            <span style={{ display: 'inline-block', marginRight: '6px', width: '8px', height: '8px', borderRadius: '50%', backgroundColor: selectedLead.estagio.cor }} />
                                        ) : null}
                                        {selectedLead?.estagio?.nome ?? "Desconhecido"}
                                    </p>
                                </div>
                            </div>

                            <Separator />

                            {/* Commercial Info */}
                            <div className="space-y-2">
                                <h4 className="text-xs font-bold uppercase text-muted-foreground tracking-widest">Comercial</h4>
                                <div className="grid grid-cols-2 gap-2 text-sm">
                                    <div>
                                        <span className="text-muted-foreground text-xs">Origem:</span>
                                        <p>{ORIGENS[selectedLead.origem]?.label ?? selectedLead.origem}</p>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground text-xs">Valor:</span>
                                        <p className="font-semibold">{selectedLead.valor_estimado ? formatCurrency(selectedLead.valor_estimado) : "—"}</p>
                                    </div>
                                    {selectedLead.plano_interesse && (
                                        <div>
                                            <span className="text-muted-foreground text-xs">Plano:</span>
                                            <p>
                                                {planos?.find(p => p.id === selectedLead.plano_interesse || p.nome === selectedLead.plano_interesse)?.nome ?? selectedLead.plano_interesse}
                                            </p>
                                        </div>
                                    )}
                                    {selectedLead.qtd_fazendas != null && (
                                        <div>
                                            <span className="text-muted-foreground text-xs">Fazendas:</span>
                                            <p>{selectedLead.qtd_fazendas}</p>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {selectedLead.notas && (
                                <>
                                    <Separator />
                                    <div>
                                        <h4 className="text-xs font-bold uppercase text-muted-foreground tracking-widest mb-1">Notas</h4>
                                        <p className="text-sm whitespace-pre-wrap">{selectedLead.notas}</p>
                                    </div>
                                </>
                            )}

                            {selectedLead.motivo_perda && (
                                <>
                                    <Separator />
                                    <div className="bg-red-50 border border-red-200 rounded p-3">
                                        <h4 className="text-xs font-bold text-red-600 uppercase mb-1">Motivo da Perda</h4>
                                        <p className="text-sm text-red-700">{selectedLead.motivo_perda}</p>
                                    </div>
                                </>
                            )}

                            <Separator />

                            {/* Actions */}
                            <div className="flex gap-2 flex-wrap">
                                {(selectedLead.status === "ativo" || selectedLead.status === "aprovado") && (
                                    <>
                                        <Button size="sm" variant="outline" className="text-blue-600" onClick={() => setShowNewOferta(true)}>
                                            <ShoppingCart className="size-3 mr-1" /> Oferta
                                        </Button>
                                        <Button size="sm" variant="outline" className="text-green-600" onClick={() => convertLeadMutation.mutate(selectedLead.id)}>
                                            <CheckCircle2 className="size-3 mr-1" /> Converter
                                        </Button>
                                        <Button size="sm" variant="outline" className="text-red-600" onClick={() => setLoseTarget(selectedLead)}>
                                            <XCircle className="size-3 mr-1" /> Perdido
                                        </Button>
                                    </>
                                )}
                                {(selectedLead.status === "perdido" || selectedLead.status === "convertido") && (
                                    <Button size="sm" variant="outline" onClick={() => reopenLeadMutation.mutate(selectedLead.id)}>
                                        <RotateCcw className="size-3 mr-1" /> Reabrir
                                    </Button>
                                )}
                            </div>

                            <Separator />

                            {/* Atividades */}
                            <div className="space-y-3">
                                <div className="flex items-center justify-between">
                                    <h4 className="text-xs font-bold uppercase text-muted-foreground tracking-widest">Atividades</h4>
                                    <Button size="sm" variant="outline" onClick={() => setShowNewAtividade(true)}>
                                        <Plus className="size-3 mr-1" /> Adicionar
                                    </Button>
                                </div>

                                {leadDetail?.atividades.length === 0 && (
                                    <p className="text-sm text-muted-foreground text-center py-4">Nenhuma atividade registrada.</p>
                                )}

                                {leadDetail?.atividades.map((atv) => {
                                    const tipoConfig = ATIVIDADE_TIPOS[atv.tipo] ?? ATIVIDADE_TIPOS.nota;
                                    const TipoIcon = tipoConfig.icon;
                                    return (
                                        <div
                                            key={atv.id}
                                            className={`flex gap-3 p-2 rounded border text-sm ${atv.concluida ? "opacity-50" : ""}`}
                                        >
                                            <button
                                                onClick={() => toggleAtividadeMutation.mutate(atv.id)}
                                                className="mt-0.5"
                                            >
                                                <CheckCircle2
                                                    className={`size-4 ${atv.concluida ? "text-green-500" : "text-muted-foreground"}`}
                                                />
                                            </button>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 mb-0.5">
                                                    <Badge variant="outline" className="text-[9px] gap-0.5">
                                                        <TipoIcon className="size-2.5" /> {tipoConfig.label}
                                                    </Badge>
                                                    <span className="text-[10px] text-muted-foreground">
                                                        {formatDistanceToNow(new Date(atv.created_at), { addSuffix: true, locale: ptBR })}
                                                    </span>
                                                </div>
                                                <p className={`text-sm ${atv.concluida ? "line-through" : ""}`}>{atv.descricao}</p>
                                                {atv.admin_email && (
                                                    <p className="text-[10px] text-muted-foreground mt-0.5">por {atv.admin_email}</p>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* New Atividade inline */}
                            {showNewAtividade && (
                                <div className="border rounded p-3 space-y-3 bg-muted/20">
                                    <Select value={newAtividade.tipo} onValueChange={(v: string) => setNewAtividade({ ...newAtividade, tipo: v })}>
                                        <SelectTrigger className="h-8 text-xs">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {Object.entries(ATIVIDADE_TIPOS).map(([k, v]) => (
                                                <SelectItem key={k} value={k}>{v.label}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                    <Textarea
                                        value={newAtividade.descricao}
                                        onChange={(e) => setNewAtividade({ ...newAtividade, descricao: e.target.value })}
                                        placeholder="Descreva a atividade..."
                                        rows={2}
                                        className="text-sm"
                                    />
                                    <div className="flex gap-2 justify-end">
                                        <Button variant="ghost" onClick={() => setShowNewAtividade(false)}>Cancelar</Button>
                                        <Button onClick={handleCreateAtividade} disabled={createAtividadeMutation.isPending}>
                                            Salvar
                                        </Button>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </SheetContent>
            </Sheet>

            <ConvertLeadWizard
                lead={convertWizardLead}
                open={!!convertWizardLead}
                onOpenChange={(v) => { if (!v) setConvertWizardLead(null); }}
                onSuccess={() => { invalidateCRM(); setSelectedLead(null); }}
            />
        </div>
    );
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import {
    Plus, Edit, Trash2, Save, Eye, LayoutGrid, Search,
    BookPlus, EyeOff, Filter, ArrowUpDown, Check, X,
    Undo2, Redo2, History, Copy, Book
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { useState, useMemo, useEffect } from "react";
import { toast } from "sonner";
import { PageHeader } from "@/components/shared/page-header";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
    DialogDescription
} from "@/components/ui/dialog";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle
} from "@/components/ui/alert-dialog";
import ReactMarkdown from 'react-markdown';
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Switch } from "@/components/ui/switch";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Article {
    id: string;
    categoria_id: string;
    titulo: string;
    slug: string;
    conteudo: string;
    is_publico: boolean;
    visualizacoes: number;
    created_at?: string;
    updated_at?: string;
}

interface Category {
    id: string;
    nome: string;
    icone: string;
    ordem: number;
    artigos: Article[];
}

type ArticleModalMode = 'create' | 'edit' | null;
type CategoryModalMode = 'create' | 'edit' | null;

export default function BackofficeKBPage() {
    const queryClient = useQueryClient();

    // States - Articles
    const [articleModalMode, setArticleModalMode] = useState<ArticleModalMode>(null);
    const [editingArticle, setEditingArticle] = useState<any>(null);
    const [searchTerm, setSearchTerm] = useState("");
    const [statusFilter, setStatusFilter] = useState<"all" | "public" | "private">("all");
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [articleToDelete, setArticleToDelete] = useState<{ id: string; titulo: string } | null>(null);

    // States - Categories
    const [categoryModalMode, setCategoryModalMode] = useState<CategoryModalMode>(null);
    const [editingCategory, setEditingCategory] = useState<any>(null);
    const [categoryDeleteDialogOpen, setCategoryDeleteDialogOpen] = useState(false);
    const [categoryToDelete, setCategoryToDelete] = useState<{ id: string; nome: string } | null>(null);

    const { data: categories, isLoading } = useQuery<Category[]>({
        queryKey: ["backoffice", "kb"],
        queryFn: () => apiFetch("/kb/categories")
    });

    // ─── Article Mutations ───────────────────────────────────────────────────

    const saveArticleMutation = useMutation({
        mutationFn: (data: any) => {
            const method = data.id ? "PATCH" : "POST";
            const url = data.id ? `/kb/articles/${data.id}` : "/kb/articles";
            return apiFetch(url, { method, body: JSON.stringify(data) });
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["backoffice", "kb"] });
            setArticleModalMode(null);
            setEditingArticle(null);
            toast.success("Artigo salvo com sucesso!");
        },
        onError: (e: any) => {
            toast.error(e.message || "Erro ao salvar artigo");
        }
    });

    const deleteArticleMutation = useMutation({
        mutationFn: (id: string) => apiFetch(`/kb/articles/${id}`, { method: "DELETE" }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["backoffice", "kb"] });
            setDeleteDialogOpen(false);
            setArticleToDelete(null);
            toast.success("Artigo removido com sucesso!");
        },
        onError: (e: any) => {
            toast.error(e.message || "Erro ao remover artigo");
        }
    });

    // ─── Category Mutations ──────────────────────────────────────────────────

    const saveCategoryMutation = useMutation({
        mutationFn: (data: any) => {
            const method = data.id ? "PATCH" : "POST";
            const url = data.id ? `/kb/categories/${data.id}` : "/kb/categories";
            return apiFetch(url, { method, body: JSON.stringify(data) });
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["backoffice", "kb"] });
            setCategoryModalMode(null);
            setEditingCategory(null);
            toast.success("Categoria salva com sucesso!");
        },
        onError: (e: any) => {
            toast.error(e.message || "Erro ao salvar categoria");
        }
    });

    const deleteCategoryMutation = useMutation({
        mutationFn: (id: string) => apiFetch(`/kb/categories/${id}`, { method: "DELETE" }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["backoffice", "kb"] });
            setCategoryDeleteDialogOpen(false);
            setCategoryToDelete(null);
            toast.success("Categoria removida com sucesso!");
        },
        onError: (e: any) => {
            toast.error(e.message || "Erro ao remover categoria");
        }
    });

    // ─── Handlers ────────────────────────────────────────────────────────────

    const handleOpenArticleModal = (article: any = null, categoryId: string = "") => {
        if (article) {
            setEditingArticle({ ...article });
            setArticleModalMode('edit');
        } else {
            setEditingArticle({ 
                titulo: "", 
                slug: "", 
                conteudo: "", 
                categoria_id: categoryId, 
                is_publico: true 
            });
            setArticleModalMode('create');
        }
    };

    const handleOpenCategoryModal = (category: any = null) => {
        if (category) {
            setEditingCategory({ ...category });
            setCategoryModalMode('edit');
        } else {
            setEditingCategory({ nome: "", icone: "FileText", ordem: 0 });
            setCategoryModalMode('create');
        }
    };

    const confirmDeleteArticle = (id: string, titulo: string) => {
        setArticleToDelete({ id, titulo });
        setDeleteDialogOpen(true);
    };

    const confirmDeleteCategory = (id: string, nome: string) => {
        setCategoryToDelete({ id, nome });
        setCategoryDeleteDialogOpen(true);
    };

    const generateSlug = (title: string): string => {
        return title
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/\s+/g, '-')
            .replace(/[^\w-]/g, '');
    };

    // ─── Filtered Categories ─────────────────────────────────────────────────

    const filteredCategories = useMemo(() => {
        if (!categories) return [];

        return categories
            .map(cat => ({
                ...cat,
                artigos: cat.artigos.filter(art => {
                    const matchesSearch = art.titulo.toLowerCase().includes(searchTerm.toLowerCase()) ||
                                         art.slug.toLowerCase().includes(searchTerm.toLowerCase());

                    const matchesStatus = statusFilter === "all" 
                        ? true 
                        : statusFilter === "public" 
                            ? art.is_publico 
                            : !art.is_publico;

                    return matchesSearch && matchesStatus;
                })
            }))
            .filter(cat => cat.artigos.length > 0 || searchTerm || statusFilter !== "all");
    }, [categories, searchTerm, statusFilter]);

    const totalArticles = useMemo(() => {
        return categories?.reduce((acc, cat) => acc + cat.artigos.length, 0) || 0;
    }, [categories]);

    const publicArticles = useMemo(() => {
        return categories?.reduce((acc, cat) => 
            acc + cat.artigos.filter(a => a.is_publico).length, 0) || 0;
    }, [categories]);

    if (isLoading) {
        return (
            <div className="p-8 space-y-4">
                <Skeleton className="h-10 w-64" />
                <Skeleton className="h-96 w-full" />
            </div>
        );
    }

    return (
        <div className="p-6 md:p-8 space-y-6 md:space-y-8 w-full max-w-[1600px] mx-auto">
            {/* ─── Header ────────────────────────────────────────────────────── */}
            <PageHeader
                title="Gestão da Wiki"
                description="Crie e gerencie os artigos da base de conhecimento para os usuários."
                icon={<Book className="text-primary" size={22} />}
                actions={
                    <div className="flex gap-2">
                        <Button 
                            variant="outline" 
                            className="gap-2"
                            onClick={() => handleOpenCategoryModal()}
                        >
                            <LayoutGrid className="size-4" /> 
                            <span className="hidden sm:inline">Nova Categoria</span>
                        </Button>
                        <Button
                            onClick={() => handleOpenArticleModal()}
                            className="gap-2"
                        >
                            <BookPlus className="size-4" /> 
                            <span className="hidden sm:inline">Novo Artigo</span>
                        </Button>
                    </div>
                }
            />

            {/* ─── Stats & Filters ──────────────────────────────────────────── */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                <Card className="bg-surface shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground font-medium">Total de Artigos</p>
                                <p className="text-2xl font-bold">{totalArticles}</p>
                            </div>
                            <BookPlus className="size-5 text-primary" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-surface shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground font-medium">Artigos Públicos</p>
                                <p className="text-2xl font-bold text-green-600">{publicArticles}</p>
                            </div>
                            <Eye className="size-5 text-green-600" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-surface shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground font-medium">Artigos Privados</p>
                                <p className="text-2xl font-bold text-amber-600">{totalArticles - publicArticles}</p>
                            </div>
                            <EyeOff className="size-5 text-amber-600" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-surface shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground font-medium">Categorias</p>
                                <p className="text-2xl font-bold">{categories?.length || 0}</p>
                            </div>
                            <LayoutGrid className="size-5 text-primary" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* ─── Search & Filter Bar ──────────────────────────────────────── */}
            <Card className="bg-surface shadow-sm">
                <CardContent className="p-4">
                    <div className="flex flex-col md:flex-row gap-4 md:items-center md:justify-between">
                        <div className="relative w-full md:w-96">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                            <Input
                                placeholder="Buscar artigos por título ou slug..."
                                className="pl-10"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="flex items-center gap-2">
                                <Filter className="size-4 text-muted-foreground" />
                                <span className="text-sm font-medium">Status:</span>
                                <div className="flex gap-1">
                                    <Button
                                        size="sm"
                                        variant={statusFilter === "all" ? "default" : "ghost"}
                                        className="h-8 text-xs"
                                        onClick={() => setStatusFilter("all")}
                                    >
                                        Todos
                                    </Button>
                                    <Button
                                        size="sm"
                                        variant={statusFilter === "public" ? "default" : "ghost"}
                                        className="h-8 text-xs"
                                        onClick={() => setStatusFilter("public")}
                                    >
                                        <Eye className="size-3 mr-1" /> Públicos
                                    </Button>
                                    <Button
                                        size="sm"
                                        variant={statusFilter === "private" ? "default" : "ghost"}
                                        className="h-8 text-xs"
                                        onClick={() => setStatusFilter("private")}
                                    >
                                        <EyeOff className="size-3 mr-1" /> Privados
                                    </Button>
                                </div>
                            </div>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* ─── Categories & Articles List ───────────────────────────────── */}
            <div className="grid gap-6">
                {filteredCategories.map((cat) => (
                    <Card key={cat.id} className="border-l-4 border-l-primary overflow-hidden">
                        <CardHeader className="bg-muted/30 py-4">
                            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
                                <div className="flex items-center gap-3">
                                    <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
                                        <LayoutGrid className="size-5" />
                                    </div>
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <CardTitle className="text-base font-semibold">{cat.nome}</CardTitle>
                                            <Badge variant="secondary" className="text-xs">
                                                {cat.artigos.length} {cat.artigos.length === 1 ? 'artigo' : 'artigos'}
                                            </Badge>
                                        </div>
                                        <p className="text-xs text-muted-foreground mt-0.5">
                                            {cat.artigos.filter(a => a.is_publico).length} públicos • {cat.artigos.filter(a => !a.is_publico).length} privados
                                        </p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    <Button 
                                        size="sm" 
                                        variant="outline" 
                                        className="h-8 text-xs"
                                        onClick={() => handleOpenCategoryModal(cat)}
                                    >
                                        <Edit className="size-3.5 mr-1" /> Editar
                                    </Button>
                                    <Button
                                        size="sm"
                                        variant="ghost"
                                        className="h-8 text-xs text-primary"
                                        onClick={() => handleOpenArticleModal(null, cat.id)}
                                    >
                                        <Plus className="size-3.5 mr-1" /> Add Artigo
                                    </Button>
                                </div>
                            </div>
                        </CardHeader>
                        <CardContent className="p-0">
                            {cat.artigos.length === 0 ? (
                                <div className="p-8 text-center text-muted-foreground">
                                    <BookPlus className="size-8 mx-auto mb-2 opacity-20" />
                                    <p className="text-sm">Nenhum artigo nesta categoria</p>
                                </div>
                            ) : (
                                <div className="divide-y">
                                    {cat.artigos.map(art => (
                                        <div 
                                            key={art.id} 
                                            className="p-4 flex flex-col md:flex-row md:items-center justify-between gap-3 hover:bg-muted/30 transition-colors group"
                                        >
                                            <div className="flex items-start gap-4 flex-1">
                                                <div className="h-10 w-10 rounded-lg bg-primary/5 flex items-center justify-center text-primary shrink-0">
                                                    <Eye className="size-4" />
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <h4 className="text-sm font-semibold truncate">{art.titulo}</h4>
                                                        {art.is_publico ? (
                                                            <Badge variant="outline" className="text-[10px] h-5 bg-green-50 text-green-700 border-green-200">
                                                                <Eye className="size-2.5 mr-0.5" /> Público
                                                            </Badge>
                                                        ) : (
                                                            <Badge variant="outline" className="text-[10px] h-5 bg-amber-50 text-amber-700 border-amber-200">
                                                                <EyeOff className="size-2.5 mr-0.5" /> Privado
                                                            </Badge>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                                                        <span className="font-mono bg-muted/50 px-2 py-0.5 rounded">/{art.slug}</span>
                                                        <span className="flex items-center gap-1">
                                                            <Eye className="size-3" /> {art.visualizacoes} visualizações
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2 shrink-0">
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    className="h-8 w-8 p-0"
                                                    onClick={() => handleOpenArticleModal(art)}
                                                >
                                                    <Edit className="size-4" />
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    className="h-8 w-8 p-0 text-red-500 hover:text-red-600 hover:bg-red-50"
                                                    onClick={() => confirmDeleteArticle(art.id, art.titulo)}
                                                >
                                                    <Trash2 className="size-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                ))}

                {filteredCategories.length === 0 && (
                    <Card className="bg-surface">
                        <CardContent className="p-12 text-center">
                            <BookPlus className="size-12 mx-auto mb-4 opacity-20" />
                            <h3 className="text-lg font-semibold mb-2">Nenhum artigo encontrado</h3>
                            <p className="text-muted-foreground text-sm mb-4">
                                {searchTerm || statusFilter !== "all"
                                    ? "Tente ajustar os filtros de busca"
                                    : "Comece criando sua primeira categoria e artigo"}
                            </p>
                            <div className="flex gap-2 justify-center">
                                {searchTerm && (
                                    <Button variant="outline" size="sm" onClick={() => setSearchTerm("")}>
                                        <Undo2 className="size-3.5 mr-1" /> Limpar busca
                                    </Button>
                                )}
                                {statusFilter !== "all" && (
                                    <Button variant="outline" size="sm" onClick={() => setStatusFilter("all")}>
                                        <Filter className="size-3.5 mr-1" /> Limpar filtros
                                    </Button>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                )}
            </div>

            {/* ─── Article Editor Modal ─────────────────────────────────────── */}
            <Dialog 
                open={articleModalMode !== null} 
                onOpenChange={(open) => {
                    if (!open) {
                        setArticleModalMode(null);
                        setEditingArticle(null);
                    }
                }}
            >
                <DialogContent className="sm:max-w-[900px] max-h-[90vh] flex flex-col">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <BookPlus className="size-5 text-primary" />
                            {articleModalMode === 'edit' ? 'Editar Artigo' : 'Criar Novo Artigo'}
                        </DialogTitle>
