                                            </span>
                                        </CardDescription>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    {activeTicket?.status !== "CONCLUIDO" && (
                                        <Button
                                            variant="outline"
                                            size="sm"
