    FileText, 
    TrendingUp, 
    TrendingDown, 
    Target,
    Calculator,
    PieChart,
    ArrowUpRight,
    ArrowDownRight,
    Info,
    LayoutDashboard,
    Sparkles,
    CheckCircle2,
    AlertCircle,
    Lightbulb,
