                                                            title="Marcar como escolhido"
                                                        >
                                                            <Target size={14} />
                                                        </button>
                                                    )}
                                                    <button 
                                                        onClick={() => handleDeletarCenario(c.id)}
                                                        className="p-1.5 rounded-sm hover:bg-red-100 text-red-500 transition-all"
                                                    >
                                                        <Trash2 size={14} />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </CardContent>
                        </Card>
                    )}

