interface Pedido { id: string; data_pedido: string; status: string; observacoes: string | null; }
interface Fornecedor { id: string; nome_fantasia: string; cnpj_cpf: string | null; condicoes_pagamento: string | null; }

const statusColor: Record<string, string> = {
    RASCUNHO: "bg-gray-100 text-gray-600",
    AGUARDANDO_APROVACAO: "bg-yellow-100 text-yellow-800",
    APROVADO: "bg-blue-100 text-blue-800",
    RECEBIDO_PARCIAL: "bg-orange-100 text-orange-800",
    RECEBIDO: "bg-green-100 text-green-800",
    CANCELADO: "bg-red-100 text-red-700",
};

export default function PedidosCompraPage() {
    const qc = useQueryClient();
    const [showPedidoDialog, setShowPedidoDialog] = useState(false);
    const [showFornecedorDialog, setShowFornecedorDialog] = useState(false);
    const [selectedPedido, setSelectedPedido] = useState<Pedido | null>(null);

    const { data: pedidos = [], isLoading: loadingPed } = useQuery<Pedido[]>({
        queryKey: ["compras", "pedidos"],
        queryFn: () => apiFetch("/compras/pedidos"),
    });
    const { data: fornecedores = [], isLoading: loadingForn } = useQuery<Fornecedor[]>({
        queryKey: ["compras", "fornecedores"],
        queryFn: () => apiFetch("/compras/fornecedores"),
    });

    const pedidoMut = useMutation({
        mutationFn: (d: any) => apiFetch("/compras/pedidos", { method: "POST", body: JSON.stringify(d) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["compras", "pedidos"] }); setShowPedidoDialog(false); toast.success("Pedido criado."); },
        onError: (e: any) => toast.error(e.message || "Erro."),
    });
    const fornecedorMut = useMutation({
        mutationFn: (d: any) => apiFetch("/compras/fornecedores", { method: "POST", body: JSON.stringify(d) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["compras", "fornecedores"] }); setShowFornecedorDialog(false); toast.success("Fornecedor cadastrado."); },
        onError: (e: any) => toast.error(e.message || "Erro."),
    });
    const aprovarMut = useMutation({
        mutationFn: (id: string) => apiFetch(`/compras/pedidos/${id}/aprovar`, { method: "POST", body: JSON.stringify({}) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["compras", "pedidos"] }); toast.success("Pedido aprovado."); },
        onError: (e: any) => toast.error(e.message || "Erro."),
    });

    const pendentes = pedidos.filter(p => p.status === "AGUARDANDO_APROVACAO").length;
    const aprovados = pedidos.filter(p => p.status === "APROVADO").length;

    const pedidoCols: ColumnDef<Pedido>[] = [
        { id: "data_pedido", header: "Data", accessorKey: "data_pedido", cell: (_v, p) => new Date(p.data_pedido).toLocaleDateString("pt-BR") },
        {
            id: "status", header: "Status", accessorKey: "status", cell: (_v, p) =>
                <span className={`text-xs font-medium px-2 py-0.5 rounded ${statusColor[p.status] || "bg-muted"}`}>{p.status.replace(/_/g, " ")}</span>,
        },
        { id: "observacoes", header: "Obs.", accessorKey: "observacoes", cell: (_v, p) => p.observacoes || "—" },
        {
            id: "acoes", header: "", exportable: false, sortable: false, filterable: false, cell: (_v, p) => (
                <div className="flex items-center gap-0 justify-end">
                    {p.status === "AGUARDANDO_APROVACAO" && (
                        <Button size="sm" variant="ghost" onClick={() => aprovarMut.mutate(p.id)}>
                            <CheckCircle2 className="size-3.5 mr-1 text-green-600" />Aprovar
                        </Button>
                    )}
                    <Button size="sm" variant="ghost" onClick={() => setSelectedPedido(p)}>
                        <ChevronRight className="size-3.5" />
                    </Button>
                </div>
            ),
        },
    ];

    const fornecedorCols: ColumnDef<Fornecedor>[] = [
        { id: "nome_fantasia", header: "Fornecedor", accessorKey: "nome_fantasia" },
        { id: "cnpj_cpf", header: "CNPJ / CPF", accessorKey: "cnpj_cpf", cell: (_v, f) => f.cnpj_cpf || "—" },
        { id: "condicoes_pagamento", header: "Condições de Pagamento", accessorKey: "condicoes_pagamento", cell: (_v, f) => f.condicoes_pagamento || "—" },
    ];

    return (
        <div className="space-y-6 p-6">
            <PageHeader
                title="Pedidos de Compra"
                description="Gestão de compras, fornecedores e recebimentos"
                icon={<ShoppingCart className="text-primary" size={22} />}
                breadcrumbs={[{ label: "Operacional", href: "/dashboard/operacional" }, { label: "Pedidos de Compra" }]}
                actions={
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" className="rounded-sm" onClick={() => setShowFornecedorDialog(true)}>
                            <Users className="size-3.5 mr-2" /> Fornecedor
                        </Button>
                        <Button variant="outline" size="sm" className="rounded-sm" onClick={() => setShowPedidoDialog(true)}>
                            <Plus className="size-3.5 mr-2" /> Novo Pedido
                        </Button>
                    </div>
                }
            />

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                    { label: "Total de Pedidos", value: loadingPed ? null : pedidos.length, icon: ShoppingCart, bg: "bg-primary/10", color: "text-primary" },
                    { label: "Aguardando", value: loadingPed ? null : pendentes, warn: pendentes > 0, icon: AlertTriangle, bg: "bg-amber-100 dark:bg-amber-900/30", color: "text-amber-600" },
                    { label: "Aprovados", value: loadingPed ? null : aprovados, icon: CheckCircle2, bg: "bg-emerald-100 dark:bg-emerald-900/30", color: "text-emerald-600" },
                    { label: "Fornecedores", value: loadingForn ? null : fornecedores.length, icon: Users, bg: "bg-blue-100 dark:bg-blue-900/30", color: "text-blue-600" },
                ].map((k, i) => (
                    <Card key={i} className={cn("rounded-sm shadow-sm", k.warn && "border border-amber-400 bg-amber-50/10")}>
                        <CardContent className="p-5 flex items-start gap-4">
                            <div className={cn("size-10 rounded-sm flex items-center justify-center shrink-0", k.bg)}>
                                <k.icon className={cn("size-5", k.warn ? "text-amber-600" : k.color)} />
                            </div>
                            <div className="min-w-0 flex-1">
                                <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">{k.label}</p>
                                <p className={cn("text-2xl font-black tabular-nums tracking-tight mt-0.5", k.warn && "text-amber-600")}>
                                    {k.value === null ? <Skeleton className="h-7 w-8" /> : k.value}
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <Tabs defaultValue="pedidos" className="w-full">
                <TabsList className="bg-transparent p-0 gap-4 h-auto border-b rounded-none w-full justify-start">
                    <TabsTrigger value="pedidos" className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent shadow-none px-1 pb-2">
                        <ShoppingCart className="size-3.5 mr-2" />Pedidos {pendentes > 0 && <Badge variant="secondary" className="ml-1 text-[10px] h-4 px-1 rounded-sm">{pendentes}</Badge>}
                    </TabsTrigger>
                    <TabsTrigger value="fornecedores" className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent shadow-none px-1 pb-2">
                        <Users className="size-3.5 mr-2" />Fornecedores
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="pedidos" className="mt-4">
                    {loadingPed ? <Skeleton className="h-40 w-full rounded-sm" /> :
                        pedidos.length === 0
                            ? <div className="text-center py-12 text-sm text-muted-foreground rounded-sm border-2 border-dashed">Nenhum pedido. <button className="underline text-primary" onClick={() => setShowPedidoDialog(true)}>Criar pedido</button></div>
                            : <DataTable columns={pedidoCols} data={pedidos} searchable exportable />
                    }
                </TabsContent>

                <TabsContent value="fornecedores" className="mt-4">
                    {loadingForn ? <Skeleton className="h-40 w-full rounded-sm" /> :
                        fornecedores.length === 0
                            ? <div className="text-center py-12 text-sm text-muted-foreground rounded-sm border-2 border-dashed">Nenhum fornecedor cadastrado. <button className="underline text-primary" onClick={() => setShowFornecedorDialog(true)}>Cadastrar novo</button></div>
                            : <DataTable columns={fornecedorCols} data={fornecedores} searchable exportable />
                    }
                </TabsContent>
            </Tabs>

            {/* Dialog Novo Pedido */}
            <Dialog open={showPedidoDialog} onOpenChange={v => { if (!v) setShowPedidoDialog(false); }}>
                <PedidoForm onClose={() => setShowPedidoDialog(false)} onSubmit={pedidoMut.mutate} loading={pedidoMut.isPending} />
            </Dialog>

            {/* Dialog Fornecedor */}
            <Dialog open={showFornecedorDialog} onOpenChange={v => { if (!v) setShowFornecedorDialog(false); }}>
                <FornecedorForm onClose={() => setShowFornecedorDialog(false)} onSubmit={fornecedorMut.mutate} loading={fornecedorMut.isPending} />
            </Dialog>

            {/* Dialog Detalhe Pedido */}
            {selectedPedido && (
                <PedidoDetailDialog pedido={selectedPedido} onClose={() => setSelectedPedido(null)} />
            )}
        </div>
    );
}

function PedidoForm({ onClose, onSubmit, loading }: { onClose: () => void; onSubmit: (d: any) => void; loading: boolean }) {
    const { register, handleSubmit, reset } = useForm();
    return (
        <DialogContent className="max-w-md rounded-sm">
            <DialogHeader><DialogTitle className="font-bold text-primary">Novo Pedido de Compra</DialogTitle></DialogHeader>
            <form onSubmit={handleSubmit(d => { onSubmit(d); reset(); })} className="space-y-4 pt-4">
                <div className="space-y-2">
                    <Label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Observações</Label>
                    <Input {...register("observacoes")} className="h-8 text-xs rounded-sm" placeholder="Finalidade do pedido..." />
                </div>
                <DialogFooter className="gap-2">
                    <Button type="button" variant="outline" size="sm" className="rounded-sm" onClick={() => { onClose(); reset(); }}>Cancelar</Button>
                    <Button type="submit" size="sm" className="rounded-sm" disabled={loading}>{loading ? "Criando…" : "Criar Pedido"}</Button>
                </DialogFooter>
            </form>
        </DialogContent>
    );
}

function FornecedorForm({ onClose, onSubmit, loading }: { onClose: () => void; onSubmit: (d: any) => void; loading: boolean }) {
    const { register, handleSubmit, reset } = useForm();
    return (
        <DialogContent className="max-w-md rounded-sm text-xs">
            <DialogHeader><DialogTitle className="font-bold text-primary">Novo Fornecedor</DialogTitle></DialogHeader>
            <form onSubmit={handleSubmit(d => { onSubmit(d); reset(); })} className="space-y-4 pt-4">
                <div className="space-y-2"><Label className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Nome / Razão Social *</Label><Input {...register("nome_fantasia", { required: true })} className="h-8 text-xs rounded-sm" placeholder="Ex: Agroquímica Brasil LTDA" /></div>
                <div className="space-y-2"><Label className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">CNPJ / CPF</Label><Input {...register("cnpj_cpf")} className="h-8 text-xs rounded-sm" placeholder="00.000.000/0000-00" /></div>
                <div className="space-y-2"><Label className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Condições de Pagamento</Label><Input {...register("condicoes_pagamento")} className="h-8 text-xs rounded-sm" placeholder="Ex: 30/60/90 dias" /></div>
                <DialogFooter className="pt-4 gap-2">
                    <Button type="button" variant="outline" size="sm" className="rounded-sm" onClick={() => { onClose(); reset(); }}>Cancelar</Button>
                    <Button type="submit" size="sm" className="rounded-sm" disabled={loading}>{loading ? "Salvando…" : "Cadastrar"}</Button>
                </DialogFooter>
            </form>
        </DialogContent>
    );
}

function PedidoDetailDialog({ pedido, onClose }: { pedido: Pedido; onClose: () => void }) {
    const { data: itens = [], isLoading } = useQuery<any[]>({
        queryKey: ["compras", "pedido-itens", pedido.id],
        queryFn: () => apiFetch<any[]>(`/compras/pedidos/${pedido.id}/itens`),
    });

    return (
        <Dialog open onOpenChange={v => { if (!v) onClose(); }}>
            <DialogContent className="max-w-lg rounded-sm">
                <DialogHeader>
                    <DialogTitle className="font-bold text-primary italic border-b pb-2">
                        Pedido — {new Date(pedido.data_pedido).toLocaleDateString("pt-BR")}
                    </DialogTitle>
                </DialogHeader>
                <div className="space-y-4 mt-2">
                    <div className="flex items-center gap-3">
                        <Badge variant="outline" className={cn("text-[10px] font-bold uppercase tracking-wider rounded-sm", statusColor[pedido.status] || "bg-muted")}>
                            {pedido.status.replace(/_/g, " ")}
                        </Badge>
                        {pedido.observacoes && <span className="text-xs text-muted-foreground italic">"{pedido.observacoes}"</span>}
                    </div>
                    <div className="rounded-sm border bg-muted/20 p-4">
                        <p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground mb-3 border-b pb-1">Itens do Pedido</p>
                        {isLoading ? <Skeleton className="h-20 w-full" /> : (
                            <div className="space-y-2">
                                {(itens as any[]).map((item: any) => (
                                    <div key={item.id} className="flex justify-between items-center text-xs border-b border-dashed pb-1 last:border-0">
                                        <span className="font-medium">{item.nome_produto || item.produto_id}</span>
                                        <div className="text-right">
                                            <span className="font-mono text-primary font-bold">{item.quantidade_solicitada}</span>
                                            <span className="text-muted-foreground ml-1">× {item.preco_estimado_unitario.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</span>
                                        </div>
                                    </div>
                                ))}
                                {itens.length === 0 && <p className="text-xs text-muted-foreground italic">Nenhum item adicionado.</p>}
                            </div>
                        )}
                    </div>
                </div>
                <DialogFooter className="pt-2">
                    <Button variant="outline" size="sm" className="rounded-sm" onClick={onClose}>Fechar</Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

