"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useForm } from "react-hook-form";
import {
    Hammer, Plus, CheckCircle2, Wallet, Clock,
    AlertTriangle, ChevronRight, Building2, CalendarDays,
    BadgeCheck, BarChart3, Users,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { PageHeader } from "@/components/shared/page-header";
import { Badge } from "@/components/ui/badge";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import {
    Sheet, SheetContent, SheetHeader, SheetTitle,
} from "@/components/ui/sheet";
import { DataTable, type ColumnDef } from "@/components/ui/data-table";

// ── Types ─────────────────────────────────────────────────────────────────────

interface Colaborador {
    id: string;
    nome: string;
    cargo?: string;
    tipo_contrato: string;
}

interface Empreitada {
    id: string;
    colaborador_id: string;
    colaborador_nome?: string;
    descricao: string;
    unidade: string;
    quantidade: number;
    valor_unitario: number;
    valor_total: number;
    data_inicio: string;
    data_previsao_fim?: string;
    data_conclusao?: string;
    data_pagamento?: string;
    status: string;
    observacoes?: string;
}

interface NovaEmpreitadaForm {
    colaborador_id: string;
    descricao: string;
    unidade: string;
    quantidade: number;
    valor_unitario: number;
    data_inicio: string;
    data_previsao_fim: string;
    observacoes: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const fmt = (v: number) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v);

const dataBR = (s?: string) =>
    s ? new Date(s + "T00:00:00").toLocaleDateString("pt-BR") : "—";

const STATUS_CONFIG: Record<string, { label: string; className: string; icon: React.ReactNode }> = {
    ABERTA:    { label: "Em Andamento", className: "bg-blue-100 text-blue-700 border-none",   icon: <Clock size={10} /> },
    CONCLUIDA: { label: "Concluída",    className: "bg-amber-100 text-amber-700 border-none", icon: <CheckCircle2 size={10} /> },
    PAGA:      { label: "Paga",         className: "bg-green-100 text-green-700 border-none", icon: <BadgeCheck size={10} /> },
};

// ── Page ─────────────────────────────────────────────────────────────────────

export default function EmpreitadasPage() {
    const qc = useQueryClient();

    const [showNova, setShowNova] = useState(false);
    const [selected, setSelected] = useState<Empreitada | null>(null);
    const [filterStatus, setFilterStatus] = useState<string>("TODAS");

    // ── Queries ──
    const { data: empreitadas = [], isLoading } = useQuery<Empreitada[]>({
        queryKey: ["empreitadas"],
        queryFn: () => apiFetch("/rh/empreitadas"),
    });

    const { data: colaboradores = [] } = useQuery<Colaborador[]>({
        queryKey: ["colaboradores"],
        queryFn: () => apiFetch("/rh/colaboradores"),
    });

    // ── Mutations ──
    const form = useForm<NovaEmpreitadaForm>({
        defaultValues: {
            colaborador_id: "", descricao: "", unidade: "ha",
            quantidade: 1, valor_unitario: 0,
            data_inicio: new Date().toISOString().split("T")[0],
            data_previsao_fim: "", observacoes: "",
        },
    });

    const criarMutation = useMutation({
        mutationFn: (d: NovaEmpreitadaForm) =>
            apiFetch("/rh/empreitadas", {
                method: "POST",
                body: JSON.stringify({
                    ...d,
                    quantidade: Number(d.quantidade),
                    valor_unitario: Number(d.valor_unitario),
                    data_previsao_fim: d.data_previsao_fim || null,
                }),
            }),
        onSuccess: () => {
            qc.invalidateQueries({ queryKey: ["empreitadas"] });
            setShowNova(false);
            form.reset();
        },
    });

    const concluirMutation = useMutation({
        mutationFn: (id: string) =>
            apiFetch(`/rh/empreitadas/${id}/concluir`, { method: "PATCH" }),
        onSuccess: () => {
            qc.invalidateQueries({ queryKey: ["empreitadas"] });
            setSelected(prev => prev ? { ...prev, status: "CONCLUIDA" } : null);
        },
    });

    const pagarMutation = useMutation({
        mutationFn: (id: string) =>
            apiFetch(`/rh/empreitadas/${id}/pagar`, { method: "PATCH" }),
        onSuccess: () => {
            qc.invalidateQueries({ queryKey: ["empreitadas"] });
            setSelected(prev => prev ? { ...prev, status: "PAGA" } : null);
        },
    });

    // ── Derived ──
    const filtered = filterStatus === "TODAS"
        ? empreitadas
        : empreitadas.filter(e => e.status === filterStatus);

    const totAberta   = empreitadas.filter(e => e.status === "ABERTA").length;
    const totConcluida = empreitadas.filter(e => e.status === "CONCLUIDA").length;
    const totPaga     = empreitadas.filter(e => e.status === "PAGA").length;
    const valorPendente = empreitadas
        .filter(e => e.status !== "PAGA")
        .reduce((acc, e) => acc + e.valor_total, 0);
    const valorPago = empreitadas
        .filter(e => e.status === "PAGA")
        .reduce((acc, e) => acc + e.valor_total, 0);

    const hoje = new Date().toISOString().split("T")[0];
    const vencidas = empreitadas.filter(
        e => e.status === "ABERTA" && e.data_previsao_fim && e.data_previsao_fim < hoje
    ).length;

    const columns: ColumnDef<Empreitada>[] = [
        {
            id: "descricao",
            header: "Descrição",
            accessorKey: "descricao",
            cell: (value, row) => (
                <div>
                    <p className="text-sm font-semibold truncate max-w-[240px]">{value}</p>
                    <p className="text-xs text-muted-foreground">
                        {row.quantidade} {row.unidade} × {fmt(row.valor_unitario)}
                    </p>
                </div>
            ),
            sortable: true,
            filterable: true,
            filterPlaceholder: "Filtrar descrição...",
            exportFormat: (value, row) => `${value} (${row.quantidade} ${row.unidade} × ${fmt(row.valor_unitario)})`,
        },
        {
            id: "empreiteiro",
            header: "Empreiteiro",
            accessorKey: "colaborador_nome",
            cell: (value, row) => (
                <div className="flex items-center gap-1.5 text-sm">
                    <Users size={12} className="text-muted-foreground" />
                    {value ?? row.colaborador_id.slice(0, 8)}
                </div>
            ),
            sortable: true,
            filterable: true,
            filterPlaceholder: "Filtrar empreiteiro...",
            exportFormat: (value, row) => value ?? row.colaborador_id,
        },
        {
            id: "valor_total",
            header: "Valor Total",
            accessorKey: "valor_total",
            cell: (value) => (
                <span className="font-bold text-sm text-right block">{fmt(value)}</span>
            ),
            sortable: true,
            exportFormat: (value) => fmt(value),
        },
        {
            id: "prazo",
            header: "Prazo",
            accessorKey: "data_previsao_fim",
            cell: (value, row) => {
                const isVencida = row.status === "ABERTA" && value && value < hoje;
                return value ? (
                    <span className={`text-xs ${isVencida ? "text-red-600 font-semibold" : "text-muted-foreground"}`}>
                        {isVencida && <AlertTriangle size={10} className="inline mr-1" />}
                        {dataBR(value)}
                    </span>
                ) : (
                    <span className="text-xs text-muted-foreground">—</span>
                );
            },
            sortable: true,
            exportFormat: (value) => dataBR(value),
        },
        {
            id: "status",
            header: "Status",
            accessorKey: "status",
            cell: (value) => {
                const cfg = STATUS_CONFIG[value] ?? { label: value, className: "bg-muted", icon: null };
                return (
                    <Badge className={`text-[10px] h-5 px-2 gap-1 ${cfg.className}`}>
                        {cfg.icon} {cfg.label}
                    </Badge>
                );
            },
            sortable: true,
            filterable: true,
            filterPlaceholder: "Filtrar status...",
            exportFormat: (value) => STATUS_CONFIG[value]?.label ?? value,
        },
        {
            id: "acoes",
            header: "",
            exportable: false,
            sortable: false,
            filterable: false,
            cell: (_, row) => (
                <div className="flex items-center gap-0 justify-end">
                    <Button
                        size="icon"
                        variant="ghost"
                        className="size-7"
                        aria-label="Ver detalhes"
                        onClick={() => setSelected(row)}
                    >
                        <ChevronRight className="size-3.5" />
                    </Button>
                </div>
            ),
        },
    ];

    return (
        <div className="p-6 space-y-6 max-w-7xl mx-auto w-full">
            <PageHeader
                title="Diaristas & Empreitadas"
                description="Contratos de serviço por produção, empreiteiros e diaristas."
                icon={<Hammer className="text-primary" />}
                actions={
                    <Button size="sm" className="gap-1.5" onClick={() => setShowNova(true)}>
                        <Plus size={14} /> Nova Empreitada
                    </Button>
                }
            />

            {/* KPIs */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <Card className="border-none bg-blue-50 dark:bg-blue-950/20">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-blue-600 flex items-center gap-1">
                            <BarChart3 size={10} /> Em Andamento
                        </p>
                        <p className="text-2xl font-black text-blue-700">{totAberta}</p>
                        {vencidas > 0 && (
                            <p className="text-[10px] text-red-500 font-semibold flex items-center gap-1 mt-0.5">
                                <AlertTriangle size={9} /> {vencidas} vencida{vencidas > 1 ? "s" : ""}
                            </p>
                        )}
                    </CardContent>
                </Card>
                <Card className="border-none bg-amber-50 dark:bg-amber-950/20">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-amber-600">Concluídas</p>
                        <p className="text-2xl font-black text-amber-700">{totConcluida}</p>
                        <p className="text-[10px] text-muted-foreground mt-0.5">aguardando pagto.</p>
                    </CardContent>
                </Card>
                <Card className="border-none bg-green-50 dark:bg-green-950/20">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-green-600">Pagas</p>
                        <p className="text-2xl font-black text-green-700">{totPaga}</p>
                        <p className="text-[10px] text-muted-foreground mt-0.5">{fmt(valorPago)}</p>
                    </CardContent>
                </Card>
                <Card className="border-none bg-red-50 dark:bg-red-950/20">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-red-600">A Pagar</p>
                        <p className="text-xl font-black text-red-700 tabular-nums">{fmt(valorPendente)}</p>
                        <p className="text-[10px] text-muted-foreground mt-0.5">concluídas + abertas</p>
                    </CardContent>
                </Card>
            </div>

            {/* Filter tabs */}
            <div className="flex items-center gap-2 flex-wrap">
                {["TODAS", "ABERTA", "CONCLUIDA", "PAGA"].map(s => (
                    <button
                        key={s}
                        onClick={() => setFilterStatus(s)}
                        className={`text-xs px-3 py-1 rounded-full border transition-colors font-semibold ${
                            filterStatus === s
                                ? "bg-primary text-primary-foreground border-primary"
                                : "bg-background text-muted-foreground border-border hover:bg-muted"
                        }`}
                    >
                        {s === "TODAS" ? "Todas" : STATUS_CONFIG[s]?.label ?? s}
                        {s !== "TODAS" && (
                            <span className="ml-1.5 opacity-70">
                                ({empreitadas.filter(e => e.status === s).length})
                            </span>
                        )}
                    </button>
                ))}
            </div>

            {/* DataTable */}
            <DataTable
                data={filtered}
                columns={columns}
                searchable
                searchPlaceholder="Buscar empreitada ou empreiteiro..."
                exportable
                exportFileName="empreitadas"
                emptyMessage={
                    filterStatus === "TODAS"
                        ? 'Nenhuma empreitada. Clique em "Nova Empreitada" para começar.'
                        : `Nenhuma empreitada com status "${STATUS_CONFIG[filterStatus]?.label}".`
                }
            />

            {/* ── Sheet: Detalhes ──────────────────────────────────────────── */}
            <Sheet open={!!selected} onOpenChange={open => !open && setSelected(null)}>
                <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
                    {selected && (
                        <>
                            <SheetHeader className="mb-6">
                                <SheetTitle className="flex items-center gap-2">
                                    <Hammer size={16} className="text-primary" />
                                    Empreitada — Detalhes
                                </SheetTitle>
                            </SheetHeader>

                            <div className="space-y-4">
                                {/* Status banner */}
                                {(() => {
                                    const cfg = STATUS_CONFIG[selected.status];
                                    const isVencida = selected.status === "ABERTA" && selected.data_previsao_fim && selected.data_previsao_fim < hoje;
                                    return (
                                        <div className={`flex items-center gap-2 p-3 rounded-sm border text-sm font-semibold ${
                                            isVencida ? "border-red-300 bg-red-50 text-red-700" : `${cfg?.className} border-current/20`
                                        }`}>
                                            {isVencida ? <AlertTriangle size={14} /> : cfg?.icon}
                                            {isVencida ? "Prazo vencido — aguardando conclusão" : cfg?.label}
                                        </div>
                                    );
                                })()}

                                {/* Info grid */}
                                <div className="grid grid-cols-2 gap-3 text-sm">
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground">Descrição</p>
                                        <p className="font-semibold mt-0.5">{selected.descricao}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground">Empreiteiro</p>
                                        <p className="font-semibold mt-0.5 flex items-center gap-1">
                                            <Building2 size={12} className="text-muted-foreground" />
                                            {selected.colaborador_nome ?? "—"}
                                        </p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground">Quantidade</p>
                                        <p className="mt-0.5">{selected.quantidade} {selected.unidade}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground">Valor Unitário</p>
                                        <p className="mt-0.5">{fmt(selected.valor_unitario)}/{selected.unidade}</p>
                                    </div>
                                    <div className="col-span-2">
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground">Valor Total</p>
                                        <p className="text-2xl font-black mt-0.5">{fmt(selected.valor_total)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground flex items-center gap-1">
                                            <CalendarDays size={9} /> Início
                                        </p>
                                        <p className="mt-0.5">{dataBR(selected.data_inicio)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold uppercase text-muted-foreground flex items-center gap-1">
                                            <CalendarDays size={9} /> Previsão Fim
                                        </p>
                                        <p className="mt-0.5">{dataBR(selected.data_previsao_fim)}</p>
                                    </div>
                                    {selected.data_conclusao && (
                                        <div>
                                            <p className="text-[10px] font-bold uppercase text-muted-foreground">Concluída em</p>
                                            <p className="mt-0.5">{dataBR(selected.data_conclusao)}</p>
                                        </div>
                                    )}
                                    {selected.data_pagamento && (
                                        <div>
                                            <p className="text-[10px] font-bold uppercase text-muted-foreground">Paga em</p>
                                            <p className="mt-0.5 text-green-700 font-semibold">{dataBR(selected.data_pagamento)}</p>
                                        </div>
                                    )}
                                    {selected.observacoes && (
                                        <div className="col-span-2">
                                            <p className="text-[10px] font-bold uppercase text-muted-foreground">Observações</p>
                                            <p className="mt-0.5 text-sm">{selected.observacoes}</p>
                                        </div>
                                    )}
                                </div>

                                {/* Actions */}
                                {selected.status === "ABERTA" && (
                                    <Button
                                        className="w-full gap-2 mt-2"
                                        variant="outline"
                                        disabled={concluirMutation.isPending}
                                        onClick={() => concluirMutation.mutate(selected.id)}
                                    >
                                        <CheckCircle2 size={14} />
                                        {concluirMutation.isPending ? "Salvando…" : "Marcar como Concluída"}
                                    </Button>
                                )}
                                {selected.status === "CONCLUIDA" && (
                                    <Button
                                        className="w-full gap-2 mt-2 bg-green-600 hover:bg-green-700"
                                        disabled={pagarMutation.isPending}
                                        onClick={() => pagarMutation.mutate(selected.id)}
                                    >
                                        <Wallet size={14} />
                                        {pagarMutation.isPending ? "Registrando…" : "Registrar Pagamento"}
                                    </Button>
                                )}
                                {selected.status === "PAGA" && (
                                    <div className="flex items-center gap-2 p-3 rounded-sm bg-green-50 text-green-700 text-sm font-semibold">
                                        <BadgeCheck size={15} /> Empreitada concluída e paga.
                                    </div>
                                )}
                            </div>
                        </>
                    )}
                </SheetContent>
            </Sheet>

            {/* ── Dialog: Nova Empreitada ──────────────────────────────────── */}
            <Dialog open={showNova} onOpenChange={setShowNova}>
                <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Hammer size={16} /> Nova Empreitada
                        </DialogTitle>
                    </DialogHeader>
                    <form
                        onSubmit={form.handleSubmit(d => criarMutation.mutate(d))}
                        className="space-y-4"
                    >
                        <div>
                            <Label>Empreiteiro / Diarista</Label>
                            <select
                                {...form.register("colaborador_id", { required: true })}
                                className="w-full mt-1 rounded-sm border border-input bg-background px-3 py-2 text-sm"
                            >
                                <option value="">Selecione…</option>
                                {colaboradores.map(c => (
                                    <option key={c.id} value={c.id}>
                                        {c.nome} {c.cargo ? `— ${c.cargo}` : ""}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <Label>Descrição do Serviço</Label>
                            <Input
                                placeholder="Ex: Roçagem de pastagem, colheita manual…"
                                {...form.register("descricao", { required: true })}
                                className="mt-1"
                            />
                        </div>

                        <div className="grid grid-cols-3 gap-3">
                            <div>
                                <Label>Unidade</Label>
                                <Input
                                    placeholder="ha, sc, t, m²…"
                                    {...form.register("unidade", { required: true })}
                                    className="mt-1"
                                />
                            </div>
                            <div>
                                <Label>Quantidade</Label>
                                <Input
                                    type="number" step="0.01" min="0"
                                    {...form.register("quantidade", { required: true })}
                                    className="mt-1"
                                />
                            </div>
                            <div>
                                <Label>Valor/Unidade (R$)</Label>
                                <Input
                                    type="number" step="0.01" min="0"
                                    {...form.register("valor_unitario", { required: true })}
                                    className="mt-1"
                                />
                            </div>
                        </div>

                        {/* Preview do valor total */}
                        {(() => {
                            const qtd = Number(form.watch("quantidade")) || 0;
                            const vu = Number(form.watch("valor_unitario")) || 0;
                            const total = qtd * vu;
                            return total > 0 ? (
                                <div className="text-sm p-2 rounded-sm bg-muted/30 flex justify-between">
                                    <span className="text-muted-foreground">Valor total estimado:</span>
                                    <span className="font-black">{fmt(total)}</span>
                                </div>
                            ) : null;
                        })()}

                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <Label>Data Início</Label>
                                <Input
                                    type="date"
                                    {...form.register("data_inicio", { required: true })}
                                    className="mt-1"
                                />
                            </div>
                            <div>
                                <Label>Previsão de Término</Label>
                                <Input
                                    type="date"
                                    {...form.register("data_previsao_fim")}
                                    className="mt-1"
                                />
                            </div>
                        </div>

                        <div>
                            <Label>Observações</Label>
                            <Input
                                placeholder="Condições, local, detalhes…"
                                {...form.register("observacoes")}
                                className="mt-1"
                            />
                        </div>

                        <DialogFooter>
                            <Button type="button" variant="outline" onClick={() => setShowNova(false)}>
                                Cancelar
                            </Button>
                            <Button type="submit" disabled={criarMutation.isPending}>
                                {criarMutation.isPending ? "Criando…" : "Criar Empreitada"}
                            </Button>
                        </DialogFooter>
                    </form>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useForm } from "react-hook-form";
import {
    Users, Plus, Wallet, Clock, CheckCircle2,
    AlertTriangle, ChevronRight, UserCheck,
    Hammer, CalendarDays, BadgeCheck, X,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { PageHeader } from "@/components/shared/page-header";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";

// ── Types ─────────────────────────────────────────────────────────────────────

interface DashboardRH {
    total_colaboradores_ativos: number;
    total_diaristas: number;
    total_empreiteiros: number;
    gasto_diarias_mes: number;
    gasto_empreitadas_mes: number;
    total_pendente_diarias: number;
    total_pendente_empreitadas: number;
    empreitadas_abertas: number;
}

interface Colaborador {
    id: string;
    pessoa_id: string;
    // campos desnormalizados retornados pelo backend via join
    nome?: string;
    cpf?: string;
    cargo?: string;
    tipo_contrato: string;
    valor_diaria?: number;
    data_admissao?: string;
    ativo: boolean;
}

interface Pessoa {
    id: string;
    nome_exibicao: string;
    tipo: string;
}

interface Diaria {
    id: string;
    colaborador_id: string;
    data: string;
    horas_trabalhadas: number;
    atividade: string;
    valor_diaria: number;
    status: string;
    observacoes?: string;
}

interface Empreitada {
    id: string;
    colaborador_id: string;
    descricao: string;
    unidade: string;
    quantidade: number;
    valor_unitario: number;
    valor_total: number;
    data_inicio: string;
    data_fim?: string;
    status: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const fmt = (v: number) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v);

const tipoColor: Record<string, string> = {
    CLT:          "bg-blue-100 text-blue-700",
    DIARISTA:     "bg-amber-100 text-amber-700",
    EMPREITEIRO:  "bg-purple-100 text-purple-700",
    TERCEIRO:     "bg-slate-100 text-slate-700",
};

const statusEmpColor: Record<string, string> = {
    ABERTA:    "bg-blue-100 text-blue-700",
    CONCLUIDA: "bg-amber-100 text-amber-700",
    PAGA:      "bg-green-100 text-green-700",
    CANCELADA: "bg-red-100 text-red-700",
};

// ── Page ─────────────────────────────────────────────────────────────────────

export default function RHPage() {
    const qc = useQueryClient();


    const [showNovoColaborador, setShowNovoColaborador] = useState(false);
    const [showNovaDiaria, setShowNovaDiaria] = useState(false);
    const [showNovaEmpreitada, setShowNovaEmpreitada] = useState(false);
    const [selectedDiarias, setSelectedDiarias] = useState<Set<string>>(new Set());

    // ── Queries ──
    const { data: dash } = useQuery<DashboardRH>({
        queryKey: ["rh-dashboard"],
        queryFn: () => apiFetch("/rh/dashboard"),
    });

    const { data: colaboradores = [], isLoading: loadingCol } = useQuery<Colaborador[]>({
        queryKey: ["rh-colaboradores"],
        queryFn: () => apiFetch("/rh/colaboradores?ativo=true"),
    });

    const { data: diarias = [], isLoading: loadingDiarias } = useQuery<Diaria[]>({
        queryKey: ["rh-diarias"],
        queryFn: () => apiFetch("/rh/diarias"),
    });

    const { data: empreitadas = [], isLoading: loadingEmp } = useQuery<Empreitada[]>({
        queryKey: ["rh-empreitadas"],
        queryFn: () => apiFetch("/rh/empreitadas"),
    });

    // ── Pessoas (para selector no form de colaborador) ──
    const { data: pessoas = [] } = useQuery<Pessoa[]>({
        queryKey: ["pessoas-rh"],
        queryFn: () => apiFetch("/cadastros/pessoas"),
    });

    // ── Forms ──
    const colForm = useForm<{ pessoa_id: string; cargo?: string; tipo_contrato: string; valor_diaria?: number; data_admissao?: string }>({
        defaultValues: { pessoa_id: "", tipo_contrato: "DIARISTA", valor_diaria: 0 },
    });
    const diariaForm = useForm<Partial<Diaria> & { colaborador_id: string }>({
        defaultValues: { colaborador_id: "", data: "", horas_trabalhadas: 8, atividade: "GERAL", valor_diaria: 0 },
    });
    const empForm = useForm<Partial<Empreitada> & { colaborador_id: string }>({
        defaultValues: { colaborador_id: "", descricao: "", unidade: "HECTARE", quantidade: 0, valor_unitario: 0, data_inicio: "" },
    });

    // ── Mutations ──
    const criarColMut = useMutation({
        mutationFn: (d: any) => apiFetch("/rh/colaboradores", { method: "POST", body: JSON.stringify(d) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-colaboradores"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); setShowNovoColaborador(false); colForm.reset(); },
    });

    const criarDiariaMut = useMutation({
        mutationFn: (d: any) => apiFetch("/rh/diarias", { method: "POST", body: JSON.stringify({ ...d, valor_diaria: Number(d.valor_diaria), horas_trabalhadas: Number(d.horas_trabalhadas) }) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-diarias"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); setShowNovaDiaria(false); diariaForm.reset(); },
    });

    const pagarDiariasMut = useMutation({
        mutationFn: () => apiFetch("/rh/diarias/pagar-lote", { method: "POST", body: JSON.stringify({ ids: [...selectedDiarias] }) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-diarias"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); setSelectedDiarias(new Set()); },
    });

    const criarEmpMut = useMutation({
        mutationFn: (d: any) => apiFetch("/rh/empreitadas", { method: "POST", body: JSON.stringify({ ...d, quantidade: Number(d.quantidade), valor_unitario: Number(d.valor_unitario) }) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-empreitadas"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); setShowNovaEmpreitada(false); empForm.reset(); },
    });

    const concluirEmpMut = useMutation({
        mutationFn: (id: string) => apiFetch(`/rh/empreitadas/${id}/concluir`, { method: "PATCH", body: JSON.stringify({}) }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-empreitadas"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); },
    });

    const pagarEmpMut = useMutation({
        mutationFn: (id: string) => apiFetch(`/rh/empreitadas/${id}/pagar`, { method: "PATCH" }),
        onSuccess: () => { qc.invalidateQueries({ queryKey: ["rh-empreitadas"] }); qc.invalidateQueries({ queryKey: ["rh-dashboard"] }); },
    });

    // ── Derived ──
    const nomeColaborador = (id: string) => {
        const col = colaboradores.find(c => c.id === id);
        return col?.nome ?? pessoas.find(p => p.id === col?.pessoa_id)?.nome_exibicao ?? id.slice(0, 8);
    };

    const diariasPendentes = diarias.filter(d => d.status === "PENDENTE");
    const toggleDiaria = (id: string) => {
        const next = new Set(selectedDiarias);
        next.has(id) ? next.delete(id) : next.add(id);
        setSelectedDiarias(next);
    };
    const toggleAllPendentes = () => {
        if (selectedDiarias.size === diariasPendentes.length) {
            setSelectedDiarias(new Set());
        } else {
            setSelectedDiarias(new Set(diariasPendentes.map(d => d.id)));
        }
    };

    return (
        <div className="p-6 space-y-6 max-w-7xl mx-auto w-full">
            <PageHeader
                title="Recursos Humanos"
                description="Colaboradores, lançamentos de diárias e empreitadas."
                icon={<Users className="text-primary" />}
                actions={
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" className="gap-1.5" onClick={() => setShowNovoColaborador(true)}>
                            <UserCheck size={14} /> Colaborador
                        </Button>
                        <Button variant="outline" size="sm" className="gap-1.5" onClick={() => setShowNovaDiaria(true)}>
                            <CalendarDays size={14} /> Diária
                        </Button>
                        <Button size="sm" className="gap-1.5" onClick={() => setShowNovaEmpreitada(true)}>
                            <Hammer size={14} /> Empreitada
                        </Button>
                    </div>
                }
            />

            {/* KPIs */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <Card className="border-none bg-blue-50">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-blue-600">Colaboradores</p>
                        <p className="text-2xl font-black text-blue-700">{dash?.total_colaboradores_ativos ?? "—"}</p>
                        <p className="text-[10px] text-muted-foreground mt-1">
                            {dash?.total_diaristas ?? 0} diaristas · {dash?.total_empreiteiros ?? 0} empreiteiros
                        </p>
                    </CardContent>
                </Card>
                <Card className="border-none bg-amber-50">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-amber-600">Diárias (mês)</p>
                        <p className="text-xl font-black text-amber-700">{fmt(dash?.gasto_diarias_mes ?? 0)}</p>
                        <p className="text-[10px] text-red-500 font-semibold mt-1">
                            pendente: {fmt(dash?.total_pendente_diarias ?? 0)}
                        </p>
                    </CardContent>
                </Card>
                <Card className="border-none bg-purple-50">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-purple-600">Empreitadas (mês)</p>
                        <p className="text-xl font-black text-purple-700">{fmt(dash?.gasto_empreitadas_mes ?? 0)}</p>
                        <p className="text-[10px] text-muted-foreground mt-1">{dash?.empreitadas_abertas ?? 0} em aberto</p>
                    </CardContent>
                </Card>
                <Card className="border-none bg-red-50">
                    <CardContent className="p-4">
                        <p className="text-[10px] font-bold uppercase text-red-600">Total a Pagar</p>
                        <p className="text-xl font-black text-red-700">
                            {fmt((dash?.total_pendente_diarias ?? 0) + (dash?.total_pendente_empreitadas ?? 0))}
                        </p>
                        <p className="text-[10px] text-muted-foreground mt-1">diárias + empreitadas</p>
                    </CardContent>
                </Card>
            </div>

            {/* Tabs */}
            <Tabs defaultValue="colaboradores">
                <TabsList className="bg-muted/50 p-1">
                    <TabsTrigger value="colaboradores" className="gap-1.5"><Users size={13} /> Colaboradores</TabsTrigger>
                    <TabsTrigger value="diarias" className="gap-1.5"><CalendarDays size={13} /> Diárias</TabsTrigger>
                    <TabsTrigger value="empreitadas" className="gap-1.5"><Hammer size={13} /> Empreitadas</TabsTrigger>
                </TabsList>

                {/* ── Colaboradores ── */}
                <TabsContent value="colaboradores" className="mt-4">
                    <Card>
                        <CardContent className="p-0">
                            {loadingCol ? (
                                <div className="p-4 space-y-3">{[1,2,3].map(i=><Skeleton key={i} className="h-14 w-full"/>)}</div>
                            ) : colaboradores.length === 0 ? (
                                <div className="text-center py-12 text-muted-foreground">
                                    <Users className="mx-auto size-10 opacity-30 mb-3"/>
                                    <p className="font-bold">Nenhum colaborador cadastrado</p>
                                </div>
                            ) : (
                                <div className="divide-y divide-border/50">
                                    {colaboradores.map(c => (
                                        <div key={c.id} className="flex items-center justify-between p-4 hover:bg-muted/20">
                                            <div className="flex items-center gap-3">
                                                <div className="size-9 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold text-sm shrink-0">
                                                    {(c.nome ?? pessoas.find(p => p.id === c.pessoa_id)?.nome_exibicao ?? "?").charAt(0).toUpperCase()}
                                                </div>
                                                <div>
                                                    <p className="font-bold text-sm">
                                                        {c.nome ?? pessoas.find(p => p.id === c.pessoa_id)?.nome_exibicao ?? c.pessoa_id.slice(0, 8)}
                                                    </p>
                                                    <div className="flex items-center gap-2 mt-0.5 text-xs text-muted-foreground">
                                                        {c.cargo && <span>{c.cargo}</span>}
                                                        {c.data_admissao && <span>· desde {new Date(c.data_admissao).toLocaleDateString("pt-BR")}</span>}
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                {c.valor_diaria && (
                                                    <div className="hidden md:block text-right">
                                                        <p className="text-[10px] text-muted-foreground">Diária</p>
                                                        <p className="text-sm font-bold">{fmt(c.valor_diaria)}</p>
                                                    </div>
                                                )}
                                                <Badge className={`text-[10px] h-5 px-2 border-none ${tipoColor[c.tipo_contrato] ?? "bg-muted"}`}>
                                                    {c.tipo_contrato}
                                                </Badge>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </TabsContent>

                {/* ── Diárias ── */}
                <TabsContent value="diarias" className="mt-4">
                    <Card>
                        <CardHeader className="pb-3">
                            <div className="flex items-center justify-between">
                                <div>
                                    <CardTitle className="text-base">Lançamentos de Diárias</CardTitle>
                                    <CardDescription>{diariasPendentes.length} pendente(s) de pagamento</CardDescription>
                                </div>
                                {selectedDiarias.size > 0 && (
                                    <Button size="sm" className="gap-1.5 bg-green-600 hover:bg-green-700"
                                        onClick={() => pagarDiariasMut.mutate()}
                                        disabled={pagarDiariasMut.isPending}>
                                        <BadgeCheck size={14} /> Pagar {selectedDiarias.size} selecionada(s)
                                    </Button>
                                )}
                            </div>
                        </CardHeader>
                        <CardContent className="p-0">
                            {loadingDiarias ? (
                                <div className="p-4 space-y-3">{[1,2,3].map(i=><Skeleton key={i} className="h-12 w-full"/>)}</div>
                            ) : diarias.length === 0 ? (
                                <div className="text-center py-12 text-muted-foreground">
                                    <CalendarDays className="mx-auto size-10 opacity-30 mb-3"/>
                                    <p className="font-bold">Nenhuma diária lançada</p>
                                </div>
                            ) : (
                                <div className="divide-y divide-border/50">
                                    {/* header select all */}
                                    {diariasPendentes.length > 0 && (
                                        <div className="flex items-center gap-3 px-4 py-2 bg-muted/30">
                                            <Checkbox
                                                checked={selectedDiarias.size === diariasPendentes.length && diariasPendentes.length > 0}
                                                onCheckedChange={toggleAllPendentes}
                                            />
                                            <span className="text-xs text-muted-foreground">Selecionar todas as pendentes</span>
                                        </div>
                                    )}
                                    {diarias.map(d => (
                                        <div key={d.id} className={`flex items-center justify-between p-4 hover:bg-muted/20 ${selectedDiarias.has(d.id) ? "bg-green-50" : ""}`}>
                                            <div className="flex items-center gap-3">
                                                {d.status === "PENDENTE" ? (
                                                    <Checkbox
                                                        checked={selectedDiarias.has(d.id)}
                                                        onCheckedChange={() => toggleDiaria(d.id)}
                                                    />
                                                ) : (
                                                    <CheckCircle2 className="size-4 text-green-500 shrink-0" />
                                                )}
                                                <div>
                                                    <p className="font-bold text-sm">{nomeColaborador(d.colaborador_id)}</p>
                                                    <div className="flex items-center gap-2 mt-0.5 text-xs text-muted-foreground">
                                                        <span>{new Date(d.data).toLocaleDateString("pt-BR")}</span>
                                                        <span>· {d.atividade}</span>
                                                        <span>· {d.horas_trabalhadas}h</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <p className="font-black text-sm">{fmt(d.valor_diaria)}</p>
                                                <Badge className={d.status === "PAGO"
                                                    ? "bg-green-100 text-green-700 border-none text-[10px] h-5 px-2"
                                                    : "bg-amber-100 text-amber-700 border-none text-[10px] h-5 px-2"}>
                                                    {d.status}
                                                </Badge>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </TabsContent>

                {/* ── Empreitadas ── */}
                <TabsContent value="empreitadas" className="mt-4">
                    <Card>
                        <CardContent className="p-0">
                            {loadingEmp ? (
                                <div className="p-4 space-y-3">{[1,2,3].map(i=><Skeleton key={i} className="h-16 w-full"/>)}</div>
                            ) : empreitadas.length === 0 ? (
                                <div className="text-center py-12 text-muted-foreground">
                                    <Hammer className="mx-auto size-10 opacity-30 mb-3"/>
                                    <p className="font-bold">Nenhuma empreitada registrada</p>
                                </div>
                            ) : (
                                <div className="divide-y divide-border/50">
                                    {empreitadas.map(e => (
                                        <div key={e.id} className="flex items-center justify-between p-4 hover:bg-muted/20 gap-4">
                                            <div className="flex items-center gap-3 min-w-0">
                                                <div className={`size-9 rounded-sm flex items-center justify-center shrink-0 ${e.status === "PAGA" ? "bg-green-100 text-green-700" : e.status === "ABERTA" ? "bg-blue-100 text-blue-700" : "bg-amber-100 text-amber-700"}`}>
                                                    <Hammer size={16} />
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="font-bold text-sm truncate">{e.descricao}</p>
                                                    <div className="flex items-center gap-2 mt-0.5 text-xs text-muted-foreground flex-wrap">
                                                        <span>{nomeColaborador(e.colaborador_id)}</span>
                                                        <span>· {e.quantidade} {e.unidade}</span>
                                                        <span>· {new Date(e.data_inicio).toLocaleDateString("pt-BR")}</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-3 shrink-0">
                                                <div className="text-right hidden md:block">
                                                    <p className="text-[10px] text-muted-foreground">{fmt(e.valor_unitario)}/{e.unidade}</p>
                                                    <p className="font-black text-sm">{fmt(e.valor_total)}</p>
                                                </div>
                                                <Badge className={`text-[10px] h-5 px-2 border-none ${statusEmpColor[e.status] ?? "bg-muted"}`}>
                                                    {e.status}
                                                </Badge>
                                                {e.status === "ABERTA" && (
                                                    <Button size="sm" variant="outline" className="text-xs gap-1"
                                                        onClick={() => concluirEmpMut.mutate(e.id)}
                                                        disabled={concluirEmpMut.isPending}>
                                                        Concluir
                                                    </Button>
                                                )}
                                                {e.status === "CONCLUIDA" && (
                                                    <Button size="sm" className="text-xs gap-1 bg-green-600 hover:bg-green-700"
                                                        onClick={() => pagarEmpMut.mutate(e.id)}
                                                        disabled={pagarEmpMut.isPending}>
                                                        <BadgeCheck size={12} /> Pagar
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </TabsContent>
            </Tabs>

            {/* ── Dialog: Novo Colaborador ── */}
            <Dialog open={showNovoColaborador} onOpenChange={setShowNovoColaborador}>
                <DialogContent className="sm:max-w-md">
                    <DialogHeader><DialogTitle>Cadastrar Colaborador</DialogTitle></DialogHeader>
                    <form onSubmit={colForm.handleSubmit(d => criarColMut.mutate(d))} className="space-y-4">
                        <div className="grid grid-cols-2 gap-3">
                            <div className="col-span-2">
                                <Label>Pessoa *</Label>
                                <select {...colForm.register("pessoa_id", { required: true })} className="w-full mt-1 rounded-sm border border-input bg-background px-3 py-2 text-sm">
                                    <option value="">Selecione uma pessoa…</option>
                                    {pessoas.map(p => <option key={p.id} value={p.id}>{p.nome_exibicao}</option>)}
