            {/* Histórico de Faturas */}
            <Card className="border-none shadow-sm bg-surface">
                <CardHeader>
                    <CardTitle className="text-xl flex items-center gap-2">
                        <Receipt className="text-muted-foreground" /> Histórico de Faturas
                    </CardTitle>
                    <CardDescription>Consulte e pague suas faturas pendentes.</CardDescription>
                </CardHeader>
                <CardContent>
