                                    <TableCell className="font-medium">{inv.plano_nome}</TableCell>
                                    <TableCell>{formatCurrency(inv.valor)}</TableCell>
                                    <TableCell>{format(new Date(inv.data_vencimento), "dd/MM/yyyy")}</TableCell>
                                    <TableCell>
