}

"use client";

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toast } from "sonner";
import { Plus, Trash2, Lock } from "lucide-react";
import { apiFetch } from "@/lib/api";

const TIPOS = [
  { value: "despesa", label: "Despesas" },
  { value: "receita", label: "Receitas" },
  { value: "operacao", label: "Operações" },
  { value: "produto", label: "Produtos" },
  { value: "insumo", label: "Insumos" },
];

interface Categoria {
  id: string;
  tipo: string;
  nome: string;
  slug: string;
  parent_id: string | null;
  is_system: boolean;
  is_active: boolean;
  ordem: number;
  cor_hex: string | null;
  icone: string | null;
}

interface NovaCategoriaForm {
  nome: string;
  parent_id: string;
  cor_hex: string;
}

export function CategoriasManager() {
  const queryClient = useQueryClient();
  const [tipoAtivo, setTipoAtivo] = useState("despesa");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [novaCategoria, setNovaCategoria] = useState<NovaCategoriaForm>({
    nome: "",
    parent_id: "",
    cor_hex: "",
  });

  const { data: categorias = [], isLoading } = useQuery<Categoria[]>({
    queryKey: ["categorias", tipoAtivo],
    queryFn: () => apiFetch(`/api/v1/config/categorias/${tipoAtivo}?apenas_ativas=false`),
  });

  const criarMutation = useMutation({
    mutationFn: (data: Record<string, unknown>) =>
      apiFetch("/api/v1/config/categorias", {
        method: "POST",
        body: JSON.stringify({ tipo: tipoAtivo, ...data }),
      }),
    onSuccess: () => {
      toast.success("Categoria criada");
      queryClient.invalidateQueries({ queryKey: ["categorias", tipoAtivo] });
      setDialogOpen(false);
      setNovaCategoria({ nome: "", parent_id: "", cor_hex: "" });
    },
    onError: (e: Error) => toast.error(e.message || "Erro ao criar categoria"),
  });

  const removerMutation = useMutation({
    mutationFn: (id: string) =>
      apiFetch(`/api/v1/config/categorias/${id}`, { method: "DELETE" }),
    onSuccess: () => {
      toast.success("Categoria inativada");
      queryClient.invalidateQueries({ queryKey: ["categorias", tipoAtivo] });
    },
    onError: (e: Error) => toast.error(e.message || "Erro ao remover categoria"),
  });

  // Separar raízes e filhos
  const raizes = categorias.filter((c) => !c.parent_id);
  const filhos = (parentId: string) => categorias.filter((c) => c.parent_id === parentId);

  return (
    <div className="space-y-4">
      {/* Seletor de tipo */}
      <div className="flex gap-2 flex-wrap">
        {TIPOS.map((t) => (
          <button
            key={t.value}
            onClick={() => setTipoAtivo(t.value)}
            className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${
              tipoAtivo === t.value
                ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground hover:bg-muted/80"
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>

      {/* Lista de categorias */}
      <div className="border rounded-lg divide-y">
        {isLoading ? (
          <div className="p-4 animate-pulse h-32 bg-muted" />
        ) : raizes.length === 0 ? (
          <div className="p-8 text-center text-muted-foreground text-sm">
            Nenhuma categoria cadastrada. Clique em "Nova Categoria" para começar.
          </div>
        ) : (
          raizes.map((cat) => (
            <div key={cat.id}>
              <CategoriaRow
                categoria={cat}
                onRemover={() => removerMutation.mutate(cat.id)}
              />
              {filhos(cat.id).map((filho) => (
                <CategoriaRow
                  key={filho.id}
                  categoria={filho}
                  nivel={1}
                  onRemover={() => removerMutation.mutate(filho.id)}
                />
              ))}
            </div>
          ))
        )}
      </div>

      {/* Botão nova categoria */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogTrigger asChild>
          <Button variant="outline" size="sm">
            <Plus className="w-4 h-4 mr-1" />
            Nova Categoria
          </Button>
        </DialogTrigger>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Nova Categoria de {TIPOS.find((t) => t.value === tipoAtivo)?.label}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-1.5">
              <Label>Nome</Label>
              <Input
                value={novaCategoria.nome}
                onChange={(e) => setNovaCategoria((f) => ({ ...f, nome: e.target.value }))}
                placeholder="Ex: Energia Elétrica"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Categoria Pai (opcional)</Label>
              <Select
                value={novaCategoria.parent_id || "none"}
                onValueChange={(v) => setNovaCategoria((f) => ({ ...f, parent_id: v === "none" ? "" : v }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Categoria raiz" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">— Categoria raiz —</SelectItem>
                  {raizes
                    .filter((c) => c.is_active)
                    .map((c) => (
                      <SelectItem key={c.id} value={c.id}>
                        {c.nome}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Cor (opcional)</Label>
              <div className="flex gap-2 items-center">
                <Input
                  type="color"
                  value={novaCategoria.cor_hex || "#6366f1"}
                  onChange={(e) => setNovaCategoria((f) => ({ ...f, cor_hex: e.target.value }))}
                  className="w-12 h-9 p-1 cursor-pointer"
                />
                <Input
                  value={novaCategoria.cor_hex}
                  onChange={(e) => setNovaCategoria((f) => ({ ...f, cor_hex: e.target.value }))}
                  placeholder="#6366f1"
                  className="font-mono"
                />
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setDialogOpen(false)}>
                Cancelar
              </Button>
              <Button
                onClick={() =>
                  criarMutation.mutate({
                    nome: novaCategoria.nome,
                    parent_id: novaCategoria.parent_id || null,
                    cor_hex: novaCategoria.cor_hex || null,
                  })
                }
                disabled={!novaCategoria.nome || criarMutation.isPending}
              >
                {criarMutation.isPending ? "Criando..." : "Criar"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function CategoriaRow({
  categoria,
  nivel = 0,
  onRemover,
}: {
  categoria: Categoria;
  nivel?: number;
  onRemover: () => void;
}) {
  return (
    <div
      className={`flex items-center justify-between p-3 ${nivel > 0 ? "pl-8 bg-muted/30" : ""} ${!categoria.is_active ? "opacity-50" : ""}`}
    >
      <div className="flex items-center gap-2">
        {categoria.cor_hex && (
          <span
            className="w-3 h-3 rounded-full flex-shrink-0"
            style={{ backgroundColor: categoria.cor_hex }}
          />
        )}
        <span className="text-sm">{categoria.nome}</span>
        {categoria.is_system && (
          <Badge variant="secondary" className="text-xs gap-1">
            <Lock className="w-2.5 h-2.5" />
            Sistema
          </Badge>
        )}
        {!categoria.is_active && (
          <Badge variant="outline" className="text-xs text-muted-foreground">
            Inativa
          </Badge>
        )}
      </div>
      {!categoria.is_system && categoria.is_active && (
        <Button
          variant="ghost"
          size="icon"
          className="h-7 w-7 text-muted-foreground hover:text-destructive"
          onClick={onRemover}
        >
          <Trash2 className="w-3.5 h-3.5" />
        </Button>
      )}
    </div>
  );
}

"use client";

import React from "react";
import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Zap, AlertTriangle, TrendingDown, TrendingUp,
    FileText, ArrowRight, BrainCircuit,
    LayoutDashboard
} from "lucide-react";
import Link from "next/link";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { useAppStore } from "@/lib/stores/app-store";
import {
    useIAFeedback,
    useIAUserProfile,
    useIAExplanation,
    useIAFriction,
    useIAProgresso,
} from "@/hooks";
import { IAUpgradeCTA } from "./ia-upgrade-cta";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { Info } from "lucide-react";

interface IAEssentialData {
    prioridade: string;
    tipo: string;
    cor: string;
    titulo: string;
    resumo: string;
    detalhe: string;
    impacto_financeiro: string;
    impacto_valor_num?: number;
    rota: string;
    acao_label: string;
}

interface IAEssentialCardProps {
    safraId: string | null;
    onExpand?: () => void;
}

export function IAEssentialCard({ safraId, onExpand }: IAEssentialCardProps) {
    const { data, isLoading } = useQuery<IAEssentialData>({
        queryKey: ["ia-essencial", safraId],
        queryFn: () => apiFetch(`/ia/essencial${safraId ? `?safra_id=${safraId}` : ""}`),
        enabled: true,
        refetchInterval: 60 * 1000,
    });

    const { data: profileData } = useIAUserProfile();
    const { data: explanationData } = useIAExplanation();
    const { data: frictionData } = useIAFriction(!isLoading && !!data);
    const { data: progressoData } = useIAProgresso();

    const profile = profileData?.perfil || "NEUTRO";
    const friction = frictionData?.friccao || "BAIXA";
    const nudge = frictionData?.nudge;
    const forceSimplify = frictionData?.acao === "simplificar_ui";

    React.useEffect(() => {
        if (nudge) {
            import("@/lib/ia/ux-telemetry").then(({ trackIAUXEvento }) => {
                trackIAUXEvento({
                    evento: "nudge_visualized",
                    modo: "ESSENCIAL",
                    metadados: {
                        nudge,
                        nivel_friccao: friction
                    }
                });
            });
        }
    }, [nudge, friction]);

    const { modoEssencial } = useAppStore();
    const { showFeedback } = useIAFeedback();

    const timer = React.useRef<{ startTime: number; getElapsedTime: () => number } | null>(null);

    React.useEffect(() => {
        if (!isLoading && data) {
            import("@/lib/ia/ux-telemetry").then(({ trackIAUXEvento }) => {
                const t = { 
                    startTime: performance.now(),
                    getElapsedTime: () => Math.round(performance.now() - t.startTime)
                };
                timer.current = t;

                trackIAUXEvento({
                    evento: "essential_view_loaded",
                    modo: "ESSENCIAL",
                    metadados: {
                        tipo_ia: data.tipo,
                        prioridade: data.prioridade,
                        perfil_detectado: profile
                    }
                });
            });
        }
    }, [isLoading, data, profile]);

    const handleActionClick = () => {
        const timeToDecision = timer.current?.getElapsedTime() || 0;

        import("@/lib/ia/ux-telemetry").then(({ trackIAUXEvento }) => {
            trackIAUXEvento({
                evento: "essential_cta_clicked",
                modo: "ESSENCIAL",
                metadados: {
                    tipo_ia: data?.tipo,
                    time_to_action_ms: timeToDecision,
                    perfil_detectado: profile
                }
            });

            showFeedback({
                impacto_valor: data?.impacto_valor_num,
                tempo_decisao_ms: timeToDecision,
                tipo_ia: data?.tipo,
                origem: "ESSENTIAL_CARD_CTA"
            });
        });
    };

    const handleExpandClick = () => {
        import("@/lib/ia/ux-telemetry").then(({ trackIAUXEvento }) => {
            trackIAUXEvento({
                evento: "advanced_mode_opened",
                modo: "ESSENCIAL",
                metadados: {
                    tipo_ia: data?.tipo,
                    perfil_detectado: profile
                }
            });
        });
        onExpand?.();
    };

    if (isLoading) {
        return (
            <div className="space-y-4">
                <Skeleton className="h-[140px] w-full rounded-sm" />
                <div className="flex justify-end">
                    <Skeleton className="h-8 w-32 rounded-sm" />
                </div>
            </div>
        );
    }

    if (!data) return null;

    const isOk = data.prioridade === "NORMAL" && data.tipo === "STATUS";
    const isConfiante = profile === "CONFIANTE";
    const isAnalitico = profile === "ANALÍTICO";
    const isInseguro = profile === "INSEGURO";

    const getIcon = () => {
        if (isOk) return <BrainCircuit className="text-white" />;
        switch (data.tipo) {
            case "PLANO_ACAO": return <Zap className="text-white" />;
            case "PREDICAO_RISCO": return <TrendingDown className="text-white" />;
            case "ALERTA": return <AlertTriangle className="text-white" />;
            default: return <FileText className="text-white" />;
        }
    };

    const getBgColor = () => {
        if (isOk) return "bg-slate-700";
        switch (data.cor) {
            case "red": return "bg-red-500";
            case "amber": return "bg-amber-500";
            case "emerald": return "bg-emerald-500";
            case "blue": return "bg-blue-500";
            default: return "bg-primary";
        }
    };

    const getBorderColor = () => {
        if (isOk) return "border-slate-200 dark:border-slate-800";
        switch (data.cor) {
            case "red": return "border-red-200 dark:border-red-900/30";
            case "amber": return "border-amber-200 dark:border-amber-900/30";
            case "emerald": return "border-emerald-200 dark:border-emerald-900/30";
            case "blue": return "border-blue-200 dark:border-blue-900/30";
            default: return "border-primary/20";
        }
    };

    return (
        <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-700">
            <Card className={cn(
                "overflow-hidden border-2 shadow-xl transition-all duration-500 relative", 
                getBorderColor(),
                (isConfiante || forceSimplify) ? "max-h-[220px]" : "max-h-[600px]",
                friction === "ALTA" ? "ring-2 ring-amber-500/30" : ""
            )}>
                {nudge && (
                    <div className="absolute top-0 right-0 z-10 animate-in slide-in-from-right-2 duration-500">
                        <div className="bg-amber-500 text-white text-[9px] font-black uppercase px-3 py-1 rounded-bl-sm shadow-sm flex items-center gap-2">
                            <BrainCircuit size={10} className="animate-pulse" />
                            {nudge}
                        </div>
                    </div>
                )}
                <CardContent className="p-0">
                    <div className="flex flex-col md:flex-row">
                        <div className={cn("md:w-20 flex items-center justify-center p-6 md:p-0 transition-colors duration-500", getBgColor())}>
                            {getIcon()}
                        </div>
                        <div className="flex-1 p-6 space-y-4">
                            <div className="flex items-center justify-between gap-4">
                                <div className="flex items-center gap-2">
                                    <Badge variant="outline" className={cn(
                                        "text-[10px] uppercase font-black tracking-wider rounded-sm px-2 py-0.5",
                                        isOk ? "border-slate-300 text-slate-600" : ""
                                    )}>
                                        IA: {data.prioridade}
                                    </Badge>
                                    {profile !== "NEUTRO" && (
                                        <TooltipProvider delay={300}>
                                            <Tooltip>
                                                <TooltipTrigger asChild>
                                                    <Badge variant="outline" className="text-[10px] py-0 h-5 border-emerald-200 bg-emerald-50 text-emerald-700 cursor-help flex items-center gap-1 group">
                                                        Adaptado ao seu perfil
                                                        <Info className="w-3 h-3 text-emerald-500 group-hover:text-emerald-700 transition-colors" />
                                                    </Badge>
                                                </TooltipTrigger>
                                                <TooltipContent side="top" className="max-w-[280px] p-4 bg-white border-emerald-100 shadow-2xl rounded-sm">
                                                    <div className="space-y-2">
                                                        <div className="flex items-center gap-2 border-b border-emerald-50 pb-2">
                                                            <div className="size-2 rounded-full bg-emerald-500 animate-pulse" />
                                                            <p className="font-black text-[11px] text-emerald-900 uppercase tracking-tight">
                                                                {explanationData?.titulo || `Modo ${profile}`}
                                                            </p>
                                                        </div>
                                                        <p className="text-xs text-muted-foreground leading-relaxed">
                                                            {explanationData?.explicacao || "A IA está adaptando a densidade da informação com base no seu ritmo de decisão."}
                                                        </p>
                                                        <div className="pt-1 flex flex-wrap gap-2">
                                                            {explanationData?.metricas_usuario && (
                                                                <>
                                                                    <span className="text-[9px] font-bold px-1.5 py-0.5 bg-muted rounded-sm text-muted-foreground">
                                                                        Tempo: {explanationData.metricas_usuario.tempo_medio}
                                                                    </span>
                                                                    <span className="text-[9px] font-bold px-1.5 py-0.5 bg-muted rounded-sm text-muted-foreground">
                                                                        Execução: {explanationData.metricas_usuario.taxa_execucao}
                                                                    </span>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                </TooltipContent>
                                            </Tooltip>
                                        </TooltipProvider>
                                    )}
                                </div>
                                {!isOk && (
                                    <span className="text-[10px] font-black text-muted-foreground uppercase flex items-center gap-1.5 tracking-widest">
                                        <BrainCircuit size={14} className="text-primary animate-pulse" />
                                        {isConfiante ? "Sintonia Fina" : "Copiloto em Tempo Real"}
                                    </span>
                                )}
                            </div>

                            <div className="space-y-2">
                                <h3 className="text-xl font-black uppercase tracking-tight leading-tight text-foreground">
                                    {data.titulo}
                                </h3>
                                <p className="text-base font-bold text-foreground/90">
                                    {data.resumo}
                                </p>
                            </div>

                            {/* Detalhes adaptativos baseados no perfil e fricção */}
                            {!isOk && !isConfiante && !forceSimplify && (
                                <div className="p-4 bg-muted/40 rounded-sm border border-border/40 backdrop-blur-sm space-y-3">
                                    <p className="text-sm font-medium text-muted-foreground leading-relaxed italic">
                                        "{data.detalhe}"
                                    </p>

                                    {isAnalitico && profileData?.metadados && (
                                        <div className="flex items-center gap-2 text-[10px] font-bold text-blue-600 uppercase tracking-tighter">
                                            <Zap className="h-3 w-3 fill-current" />
                                            Baseado em {profileData.metadados.taxa_execucao.toFixed(0)}% de acerto histórico no seu perfil
                                        </div>
                                    )}

                                    {isInseguro && (
                                        <div className="flex items-center gap-2 p-2 bg-emerald-500/10 rounded-sm border border-emerald-500/20">
                                            <BrainCircuit className="h-4 w-4 text-emerald-600" />
                                            <p className="text-[10px] font-black text-emerald-700 uppercase tracking-tight">
                                                Decisão assistida: Nossa IA valida 127 pontos de controle antes de sugerir esta ação.
                                            </p>
                                        </div>
                                    )}

                                    <div className="mt-3 flex items-center gap-3">
                                        <div className="size-1.5 rounded-full bg-border" />
                                        <span className="text-[11px] font-black uppercase text-muted-foreground tracking-wider">Impacto:</span>
                                        <span className={cn(
                                            "text-sm font-black tracking-tight",
                                            data.cor === 'red' ? 'text-red-600' : 'text-emerald-600'
                                        )}>
                                            {data.impacto_financeiro}
                                        </span>
                                    </div>
                                </div>
                            )}

                            {(isConfiante || forceSimplify) && (
                                <div className="flex items-center justify-between p-2 bg-emerald-500/5 rounded-sm border border-emerald-500/10">
                                    <span className="text-[10px] font-black uppercase text-emerald-600 tracking-widest">
                                        {forceSimplify ? "Impacto Resumido" : "Impacto Estimado"}
                                    </span>
                                    <span className="text-sm font-black text-emerald-600">{data.impacto_financeiro}</span>
                                </div>
                            )}

                            <div className="flex items-center justify-between pt-2">
                                {isOk ? (
                                    <p className="text-xs font-bold text-muted-foreground italic">
                                        Tudo sob controle. Nenhuma ação pendente no momento.
                                    </p>
                                ) : (
                                    <div />
                                )}
                                <Button asChild size="sm" variant="outline" className={cn(
                                    "font-black uppercase text-[10px] rounded-sm h-8 px-6 shadow-sm transition-all active:scale-95",
                                    "border-primary/30 text-primary"
                                )}>
                                    <Link href={data.rota} onClick={handleActionClick}>
                                        {data.acao_label}
                                        <ArrowRight size={14} className="ml-1.5" />
                                    </Link>
                                </Button>
                            </div>
                        </div>
                    </div>
                </CardContent>
            </Card>

            <IAUpgradeCTA contexto="acao" compact />

            {progressoData?.mensagem_destaque && (
                <div className="flex items-center gap-2 rounded-sm border border-emerald-500/20 bg-emerald-500/5 px-3 py-2 animate-in fade-in duration-500">
                    <TrendingUp size={12} className="text-emerald-600 shrink-0" />
                    <p className="text-[10px] font-semibold text-emerald-700 leading-snug">
                        {progressoData.mensagem_destaque}
                    </p>
                </div>
            )}

            <div className="flex justify-center">
                <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleExpandClick}
                    className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground hover:text-primary hover:bg-transparent transition-all group"
                >
                    Ver detalhes completos
                    <LayoutDashboard size={14} className="ml-2 opacity-0 group-hover:opacity-100 transition-all -translate-x-2 group-hover:translate-x-0" />
                </Button>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useState } from "react";
import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { AlertTriangle, TrendingDown, TrendingUp, Zap, ArrowRight, ShieldAlert } from "lucide-react";
import { Button } from "@/components/ui/button";

interface IAEstresseData {
  nivel_risco: string;
  descricao: string;
  pior_cenario: {
    cenario: string;
    receita: number;
    custo: number;
    resultado: number;
    margem_resultante: number;
    variacao_resultado: number;
  } | null;
  todos_cenarios: any[];
  acao_recomendada: string;
  probabilidade: string;
}

export function IAEstresseCard() {
  const { activeFazendaId } = useAppStore();
  const [data, setData] = useState<IAEstresseData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true);
        const response = await apiFetch<IAEstresseData>(`/ia/financeiro/simulacao-estresse`);
        setData(response);
      } catch (error) {
        console.error("Erro ao carregar simulação de estresse:", error);
      } finally {
        setLoading(false);
      }
    }

    if (activeFazendaId) {
      loadData();
    }
  }, [activeFazendaId]);

  if (loading) {
    return <Skeleton className="h-[280px] w-full rounded-sm" />;
  }

  if (!data || !data.pior_cenario) {
    return null;
  }

  const isCritico = data.nivel_risco === "CRITICO";
  const isAlto = data.nivel_risco === "ALTO";

  return (
    <Card className={`border-l-4 ${isCritico ? 'border-l-red-600 bg-red-50/30' : isAlto ? 'border-l-orange-500 bg-orange-50/30' : 'border-l-blue-500'} shadow-sm animate-in fade-in slide-in-from-right-4 duration-500`}>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShieldAlert className={`h-5 w-5 ${isCritico ? 'text-red-600' : isAlto ? 'text-orange-500' : 'text-blue-500'}`} />
            <CardTitle className="text-sm font-bold uppercase tracking-wider">Simulação de Estresse</CardTitle>
          </div>
          <Badge variant={isCritico ? "destructive" : isAlto ? "warning" : "default"} className="rounded-sm text-[10px]">
            {data.nivel_risco}
          </Badge>
        </div>
        <CardDescription className="text-xs font-medium mt-1">
          Pior cenário projetado pela IA (Step 206)
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="p-3 bg-white/60 dark:bg-slate-900/60 rounded-sm border border-slate-100 dark:border-slate-800">
          <p className="text-xs text-slate-700 dark:text-slate-300 leading-relaxed italic">
            "{data.descricao}"
          </p>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1">
            <span className="text-[10px] text-slate-500 uppercase font-semibold">Margem Crítica</span>
            <div className={`text-lg font-bold ${data.pior_cenario.margem_resultante < 0 ? 'text-red-600' : 'text-slate-900 dark:text-slate-100'}`}>
              {data.pior_cenario.margem_resultante}%
            </div>
          </div>
          <div className="space-y-1">
            <span className="text-[10px] text-slate-500 uppercase font-semibold">Resultado Crítico</span>
            <div className={`text-lg font-bold ${data.pior_cenario.resultado < 0 ? 'text-red-600' : 'text-slate-900 dark:text-slate-100'}`}>
              R$ {data.pior_cenario.resultado.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </div>
          </div>
        </div>

        <div className="space-y-2 pt-1">
          <div className="flex items-center gap-2 text-[11px] font-bold text-slate-900 dark:text-slate-100 uppercase tracking-tighter">
            <Zap className="h-3 w-3 text-yellow-500 fill-yellow-500" />
            Ação Recomendada
          </div>
          <p className="text-xs text-slate-600 dark:text-slate-400">
            {data.acao_recomendada}
          </p>
        </div>

        <Button 
          variant="outline" 
          size="sm" 
          className="w-full h-8 text-[11px] font-bold uppercase gap-2 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all active:scale-95"
        >
          Simular Correção
          <ArrowRight className="h-3 w-3" />
        </Button>

        <div className="text-[9px] text-slate-400 flex justify-between items-center pt-1 border-t border-slate-100 dark:border-slate-800 mt-2">
          <span>Probabilidade: {data.probabilidade}</span>
          <span className="opacity-60">Copiloto IA — Simulação Extrema</span>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ClipboardList, Zap, ShieldCheck, ArrowRight, TrendingUp, TrendingDown, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { useIAFeedback, useIATimer } from "@/hooks";

interface IAActionItem {
  id: string;
  tipo: string;
  descricao: string;
  impacto_estimado: string;
  impacto_valor: number;
  prioridade: number;
  acao_sugerida: string;
  parametros_json: any;
}

interface IAAutopilotActionExecutada {
  descricao: string;
  tipo: string;
  impacto: string;
}

interface IAPlanoAcaoData {
  nivel_risco: string;
  resumo: string;
  acoes: IAActionItem[];
  data_geracao: string;
  acoes_executadas_automaticamente?: IAAutopilotActionExecutada[];
}

const fmt = (v: number) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v);

export function IAPlanoAcaoCard({ safraId }: { safraId?: string }) {
  const { activeFazendaId } = useAppStore();
  const router = useRouter();
  const { showFeedback } = useIAFeedback();
  const { getElapsedTime } = useIATimer();

  const { data, isLoading } = useQuery<IAPlanoAcaoData>({
    queryKey: ["ia-plano-acao", safraId, activeFazendaId],
    queryFn: () => apiFetch(`/ia/financeiro/plano-acao?safra_id=${safraId}`),
    enabled: !!safraId,
  });

  const mutation = useMutation({
    mutationFn: (acao: IAActionItem) => 
      apiFetch("/ia/acoes-assistidas/registrar", {
        method: "POST",
        body: JSON.stringify({
          origem: "PLANO_ACAO",
          origem_id: acao.id,
          tipo_acao: acao.acao_sugerida,
          parametros_json: acao.parametros_json
        })
      }),
    onSuccess: (res: any, variables: IAActionItem) => {
      const tempo_decisao = getElapsedTime();

      showFeedback({
        impacto_valor: variables.impacto_valor,
        tempo_decisao_ms: tempo_decisao,
        tipo_ia: variables.tipo,
        origem: "PLANO_ACAO_INDIVIDUAL"
      });

      const params = new URLSearchParams();
      params.set("action_id", res.id); // ID da ação assistida registrada
      params.set("auto_simular", "true");

      if (variables.parametros_json) {
        Object.entries(variables.parametros_json).forEach(([key, value]) => {
          params.set(key, String(value));
        });
      }

      router.push(`/dashboard/financeiro/dre?${params.toString()}`);
    },
    onError: () => {
      toast.error("Erro ao preparar execução assistida.");
    }
  });

  const batchMutation = useMutation({
    mutationFn: (acoes: IAActionItem[]) => 
      apiFetch("/ia/acoes-assistidas/registrar", {
        method: "POST",
        body: JSON.stringify({
          origem: "PLANO_ACAO",
          tipo_acao: "BATCH",
          parametros_json: {
            acoes_ids: acoes.map(a => a.id),
            agregado: acoes.reduce((acc, a) => ({ ...acc, ...a.parametros_json }), {})
          }
        })
      }),
    onSuccess: (res: any, acoes: IAActionItem[]) => {
      const tempo_decisao = getElapsedTime();
      const impactoTotal = acoes.reduce((acc, a) => acc + (a.impacto_valor || 0), 0);

      showFeedback({
        impacto_valor: impactoTotal,
        tempo_decisao_ms: tempo_decisao,
        tipo_ia: "BATCH_PLANO_ACAO",
        origem: "PLANO_ACAO_BATCH"
      });

      const params = new URLSearchParams();
      params.set("action_id", res.id);
      params.set("auto_simular", "true");
      params.set("is_batch", "true");

      // Agregar todos os parâmetros
      const agregado = acoes.reduce((acc, a) => ({ ...acc, ...a.parametros_json }), {});
      Object.entries(agregado).forEach(([key, value]) => {
        params.set(key, String(value));
      });

      router.push(`/dashboard/financeiro/dre?${params.toString()}`);
    }
  });

  if (isLoading) {
    return <Skeleton className="h-[400px] w-full rounded-sm" />;
  }

  if (!data || !data.acoes) {
    return (
      <Card className="border-dashed bg-muted/30">
        <CardContent className="p-12 flex flex-col items-center text-center">
          <Sparkles className="size-12 text-muted-foreground/20 mb-4" />
          <h3 className="text-lg font-bold text-muted-foreground">Plano de Ação Indisponível</h3>
          <p className="text-sm text-muted-foreground mt-2 max-w-sm">
            Não foi possível gerar um plano estratégico. Certifique-se de que existem lançamentos financeiros e uma safra ativa selecionada.
          </p>
        </CardContent>
      </Card>
    );
  }

  const isCritico = data.nivel_risco === "CRITICO";
  const isAlto = data.nivel_risco === "ALTO";
  const impactoTotal = data.acoes.reduce((acc, a) => acc + (a.impacto_valor || 0), 0);

  return (
    <Card className="border-l-4 border-l-emerald-500 shadow-md animate-in fade-in slide-in-from-bottom-4 duration-700 bg-emerald-50/5 dark:bg-emerald-950/5">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-1.5 bg-emerald-100 dark:bg-emerald-900/30 rounded-sm">
              <ClipboardList className="h-4 w-4 text-emerald-600" />
            </div>
            <CardTitle className="text-sm font-black uppercase tracking-widest">Plano de Recuperação IA</CardTitle>
          </div>
          <Badge variant={isCritico ? "destructive" : isAlto ? "warning" : "secondary"} className="rounded-sm text-[9px] font-black h-5 uppercase">
            {data.nivel_risco}
          </Badge>
        </div>
        <CardDescription className="text-[11px] font-bold text-muted-foreground mt-1 uppercase tracking-tighter">
          Estratégia personalizada (Step 209)
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="p-3 bg-emerald-100/30 dark:bg-emerald-900/10 rounded-sm border border-emerald-100 dark:border-emerald-800/30">
          <p className="text-xs text-slate-700 dark:text-slate-300 font-medium leading-relaxed italic">
            "{data.resumo}"
          </p>
          <div className="mt-2 pt-2 border-t border-emerald-500/10 flex justify-between items-center">
            <span className="text-[10px] font-black text-emerald-700 dark:text-emerald-400 uppercase tracking-widest">Impacto Total</span>
            <span className="text-sm font-black text-emerald-700 dark:text-emerald-400">{fmt(impactoTotal)}</span>
          </div>
        </div>

        {data.acoes.length > 1 && (
          <Button 
            onClick={() => batchMutation.mutate(data.acoes)}
            disabled={batchMutation.isPending || mutation.isPending}
            variant="outline"
            size="sm"
            className="w-full border-emerald-600/30 text-emerald-700 dark:text-emerald-400 font-black uppercase text-[10px] gap-2 h-9 rounded-sm"
          >
            {batchMutation.isPending ? "Processando Plano..." : "Executar Plano Completo"}
            <Zap className="h-3 w-3 text-emerald-600 animate-pulse" />
          </Button>
        )}

        <div className="space-y-3">
          <h4 className="text-[10px] font-black text-muted-foreground uppercase tracking-widest px-1">Ações Detalhadas</h4>

          {data.acoes.map((acao, index) => (
            <div 
              key={acao.id} 
              className={`p-3 rounded-sm border transition-all duration-300 ${
                acao.prioridade === 1 
                  ? 'border-emerald-200 bg-white dark:bg-slate-900 shadow-sm ring-1 ring-emerald-500/10' 
                  : 'border-border/40 bg-muted/20'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <div className="flex items-center gap-2">
                  <span className={`flex h-5 w-5 items-center justify-center rounded-full text-[10px] font-black ${
                    acao.prioridade === 1 ? 'bg-emerald-600 text-white' : 'bg-muted text-muted-foreground'
                  }`}>
                    {index + 1}
                  </span>
                  <Badge variant="outline" className="text-[9px] h-4 px-1.5 uppercase font-black border-emerald-500/20 text-emerald-600 dark:text-emerald-400">
                    {acao.tipo.replace('_', ' ')}
                  </Badge>
                </div>
                <div className="flex items-center gap-1">
                   {acao.tipo.includes('RECEITA') ? <TrendingUp className="h-3 w-3 text-emerald-500" /> : <TrendingDown className="h-3 w-3 text-red-500" />}
                   <span className="text-[11px] font-black text-slate-900 dark:text-slate-100">
                     {acao.impacto_estimado}
                   </span>
                </div>
              </div>

              <p className="text-xs text-muted-foreground font-medium mb-3 leading-snug">
                {acao.descricao}
              </p>

              <Button 
                onClick={() => mutation.mutate(acao)}
                disabled={mutation.isPending || batchMutation.isPending}
                variant="outline" 
                size="sm" 
                className={`w-full h-8 text-[10px] font-black uppercase gap-2 transition-all active:scale-95 border-emerald-600/20 text-emerald-600`}
              >
                {mutation.isPending ? "Processando..." : "Executar Ação Individual"}
                <ArrowRight className="h-3 w-3" />
              </Button>
            </div>
          ))}
        </div>

        {data.acoes_executadas_automaticamente && data.acoes_executadas_automaticamente.length > 0 && (
          <div className="space-y-2 mt-2 p-2 bg-blue-50/30 dark:bg-blue-950/10 border border-blue-100/50 dark:border-blue-900/20 rounded-sm">
            <h4 className="text-[9px] font-black text-blue-700 dark:text-blue-400 uppercase tracking-widest flex items-center gap-2">
              <Zap className="h-3 w-3 fill-blue-500 animate-pulse" />
              Autopilot: Otimização em Segundo Plano
            </h4>
            <div className="space-y-1.5">
              {data.acoes_executadas_automaticamente.map((auto, i) => (
                <div key={i} className="flex items-center justify-between gap-2">
                  <p className="text-[10px] text-slate-600 dark:text-slate-400 font-medium leading-tight">{auto.descricao}</p>
                  <span className="text-[9px] font-black text-blue-600 shrink-0">{auto.impacto}</span>
                </div>
              ))}
            </div>
            <p className="text-[8px] text-blue-500/60 font-bold italic pt-1 border-t border-blue-500/10">
              Essas ações foram simuladas automaticamente com base no seu nível de autonomia.
            </p>
          </div>
        )}

        <div className="text-[9px] text-muted-foreground flex justify-between items-center pt-2 border-t border-border mt-2">
          <div className="flex items-center gap-1 font-bold">
            <ShieldCheck className="h-3 w-3 text-emerald-500" />
            <span>Copiloto IA Ativo</span>
          </div>
          <span className="opacity-60">Gerado em {new Date(data.data_geracao).toLocaleDateString()}</span>
        </div>
      </CardContent>
    </Card>
  );
}

