"use client";

import { useTheme } from "@/components/theme-provider";
import { Button } from "@/components/ui/button";
import { Sun, Moon } from "lucide-react";
import { useEffect, useState } from "react";

/**
 * Botão premium de alternância de tema para a landing page.
 * Utiliza o hook useTheme do ThemeProvider.
 */
export function ThemeToggle() {
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <Button variant="outline" size="sm" className="size-8 rounded-sm p-0" aria-label="Carregando tema">
        <Sun className="size-4 shrink-0 opacity-40" />
      </Button>
    );
  }

  const isDark = theme === "dark";

  return (
    <Button
      variant="outline"
      size="sm"
      className="size-8 rounded-sm p-0 text-primary border-primary/20 hover:border-primary/45"
      onClick={() => setTheme(isDark ? "light" : "dark")}
      aria-label="Alternar tema escuro/claro"
    >
      {isDark ? (
        <Sun className="size-4 shrink-0 transition-all duration-300" />
      ) : (
        <Moon className="size-4 shrink-0 transition-all duration-300" />
      )}
    </Button>
  );
}

"use client";

import React, { useCallback, useDeferredValue, useMemo, useState } from "react";
import { useAppStore } from "@/lib/stores/app-store";
import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import {
    Sidebar,
    SidebarContent,
    SidebarGroup,
    SidebarGroupContent,
    SidebarGroupLabel,
    SidebarHeader,
    SidebarMenu,
    SidebarMenuButton,
    SidebarMenuItem,
    SidebarMenuSub,
    SidebarMenuSubItem,
    SidebarMenuSubButton,
} from "@/components/ui/sidebar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    ChevronRight, Settings2, Clock, Sprout,
    LayoutDashboard, Users, Shield, FolderTree,
    UserCircle, Book, Mail, MessageSquare, Landmark, Lock, AlertCircle, CreditCard, BrainCircuit,
    Search, X,
} from "lucide-react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { ModuleGate } from "../shared/module-gate";
import { cn } from "@/lib/utils";
import { resolveAssetUrl } from "@/lib/runtime-config";
import { hasBackofficePermission, hasTenantPermission } from "@/lib/permissions";
import type { BackofficeRole, PlanTierId, TenantCustomPermissions, TenantRole, User } from "@/types/global";
import { tierAtLeast } from "@/lib/constants/planos";
import {
    CORE_CADASTROS,
    MODULOS_OPERACIONAIS,
    BACKOFFICE_SECTIONS,
} from "@/lib/sidebar-config";

type ModuleKey = "A1" | "P1" | "F1" | "O1" | "RH" | "AM1" | "CADASTROS" | "";

type SearchableItem = {
    href: string;
    icon: React.ElementType;
    label: string;
    tip?: string;
    group: string;
    section?: string;
    permission?: string;
    minimumTier?: PlanTierId;
    moduleId?: string;
    alertBadge?: boolean;
    activeClassName?: string;
};

function normalizeSearchValue(value: string) {
    return value
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .trim();
}

function itemMatchesSearch(item: SearchableItem, query: string) {
    const haystack = normalizeSearchValue([
        item.label,
        item.tip,
        item.group,
        item.section,
        item.href,
    ].filter(Boolean).join(" "));
    return haystack.includes(query);
}

function getModuleFromPath(pathname: string): ModuleKey {
    if (pathname.startsWith("/agricola") || pathname.startsWith("/dashboard/agricola")) return "A1";
    if (pathname.startsWith("/dashboard/pecuaria")) return "P1";
    if (pathname.startsWith("/dashboard/financeiro")) return "F1";
    if (pathname.startsWith("/operacional") || pathname.startsWith("/dashboard/operacional")) return "O1";
    if (pathname.startsWith("/dashboard/rh")) return "RH";
    if (pathname.startsWith("/dashboard/ambiental")) return "AM1";
    if (pathname.startsWith("/cadastros")) return "CADASTROS";
    return "";
}

// Get active section within a module based on pathname
function getActiveSection(moduleKey: string, pathname: string): string {
    const moduleGroup = MODULOS_OPERACIONAIS.find(m => m.key === moduleKey);
    if (!moduleGroup) return "";

    for (const section of moduleGroup.sections) {
        if (section.items.some(item => pathname.startsWith(item.href))) {
            return section.key;
        }
    }
    return "";
}

function getActiveBackofficeSection(pathname: string): string | null {
    for (const section of BACKOFFICE_SECTIONS) {
        if (section.items.some((item) => pathname.startsWith(item.href))) {
            return section.key;
        }
    }
    return null;
}

// Active button style per module
const activeMenuClass =
    "relative data-[active=true]:bg-primary/5 data-[active=true]:text-primary data-[active=true]:font-semibold before:absolute before:left-0 before:top-1 before:bottom-1 before:w-[2px] before:bg-primary before:rounded-full before:opacity-0 data-[active=true]:before:opacity-100 transition-all";

const moduleActive: Record<string, string> = {
    A1: activeMenuClass,
    P1: activeMenuClass,
    F1: activeMenuClass,
    O1: activeMenuClass,
    RH: activeMenuClass,
    AM1: activeMenuClass,
};

const backofficeActive = activeMenuClass;

// Get active style for a section header based on the module key
function getSectionActiveStyle(moduleKey: string) {
    const activeClass = moduleActive[moduleKey] || "data-[active=true]:bg-primary/5 data-[active=true]:text-primary";
    return cn(
        "w-full px-1.5 py-0.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
        activeClass
    );
}

function BackofficeNav({
    pathname,
    user,
    openBackofficeSection,
    setOpenBackofficeSection,
}: {
    pathname: string;
    user: any;
    openBackofficeSection: string | null;
    setOpenBackofficeSection: (key: string | null) => void;
}) {
    const role = user?.role as BackofficeRole | undefined;
    const isSuperuser = user?.is_superuser;

    // Só mostra se o usuário tem role de backoffice ou é superuser
    if (!role && !isSuperuser) return null;

    const canSee = (permission?: string) => {
        if (!permission) return true;
        if (isSuperuser) return true;
        return hasBackofficePermission(role, permission);
    };

    // Filtra seções: só mostra se pelo menos 1 item for visível
    const visibleSections = BACKOFFICE_SECTIONS.map((section) => ({
        ...section,
        items: section.items.filter((item) => canSee(item.permission)),
    })).filter((section) => section.items.length > 0);

    if (visibleSections.length === 0) return null;

    // Determina qual seção deve estar aberta
    const activeSectionKey = getActiveBackofficeSection(pathname);

    // Se navegou para um item de uma seção, auto-abra essa seção se não estiver já aberta
    const currentOpenSection = openBackofficeSection || activeSectionKey;

    return (
        <SidebarGroup>
            <SidebarGroupLabel>Administração SaaS</SidebarGroupLabel>
            <SidebarGroupContent>
                <SidebarMenu>
                    {visibleSections.map((section) => {
                        const sectionActive = section.items.some((item) => pathname.startsWith(item.href));

                        // Se a seção tem apenas 1 item, renderiza direto (sem Collapsible)
                        if (section.items.length === 1) {
                            const item = section.items[0];
                            const Icon = item.icon;
                            return (
                                <SidebarMenuItem key={item.href}>
                                    <SidebarMenuButton
                                        render={<Link href={item.href} />}
                                        isActive={pathname === item.href}
                                        tooltip={item.tip}
                                        className={backofficeActive}
                                    >
                                        <Icon className="size-3.5 flex-shrink-0 text-primary" />
                                        <span className="truncate">{item.label}</span>
                                    </SidebarMenuButton>
                                </SidebarMenuItem>
                            );
                        }

                        // Seção com múltiplos itens
                        const SectionIcon = section.icon;
                        const isOpen = currentOpenSection === section.key;
                        return (
                            <SidebarMenuItem key={section.key}>
                                <SidebarMenuButton
                                    onClick={() => setOpenBackofficeSection(isOpen ? null : section.key)}
                                    isActive={sectionActive}
                                    tooltip={section.label}
                                    className={backofficeActive}
                                >
                                    <SectionIcon className="size-3.5 text-primary" />
                                    <span className="font-semibold">{section.label}</span>
                                    <ChevronRight className={cn("ml-auto size-3.5 transition-transform duration-200", isOpen && "rotate-90")} />
                                </SidebarMenuButton>
                                {isOpen && (
                                    <SidebarMenuSub>
                                        {section.items.map(({ href, icon: Icon, label }) => (
                                            <SidebarMenuSubItem key={href}>
                                                <SidebarMenuSubButton isActive={pathname === href} render={<Link href={href} />}>
                                                    <Icon className="size-3.5 text-primary" />
                                                    {label}
                                                </SidebarMenuSubButton>
                                            </SidebarMenuSubItem>
                                        ))}
                                    </SidebarMenuSub>
                                )}
                            </SidebarMenuItem>
                        );
                    })}
                </SidebarMenu>
            </SidebarGroupContent>
        </SidebarGroup>
    );
}

function canSeeTenantItem(
    user: User | null,
    permission?: string
) {
    if (!permission) return true;
    if (!user?.tenant_role && !user?.custom_permissions && !user?.is_superuser) return false;
    if (user?.is_superuser) return true;
    return hasTenantPermission(
        user?.tenant_role as TenantRole | undefined,
        permission,
        user?.custom_permissions as TenantCustomPermissions | undefined
    );
}

export function AppSidebar() {
    const pathname = usePathname();
    const tenant = useAppStore((state) => state.tenant);
    const user = useAppStore((state) => state.user);
    const activePlanTier = useAppStore((state) => state.activePlanTier());
    const [openModule, setOpenModule] = useState<ModuleKey>(() => getModuleFromPath(pathname));
    const [openSection, setOpenSection] = useState<Record<string, string>>(() => {
        const initialModule = getModuleFromPath(pathname);
        return initialModule ? { [initialModule]: getActiveSection(initialModule, pathname) } : {};
    });
    const [openBackofficeSection, setOpenBackofficeSection] = useState<string | null>(() => null);
    const [searchQuery, setSearchQuery] = useState("");
    const deferredSearchQuery = useDeferredValue(searchQuery);

    // Query de alertas de caderno desatualizado
    const { data: cadernoAlertas = [] } = useQuery<Array<{ safra_id: string; mensagem: string }>>({
        queryKey: ["caderno-alertas"],
        queryFn: async () => {
            try {
                return await apiFetch("/caderno/alertas", { suppressErrorLog: true });
            } catch (error: any) {
                // Módulo não contratado (402) ou outros erros esperados - retornar vazio silenciosamente
                return [];
            }
        },
        retry: false,
        refetchInterval: 5 * 60 * 1000, // Verifica a cada 5 min
    });
    const hasCadernoAlerta = cadernoAlertas.length > 0;
    const accessItems = [
        { href: "/dashboard/settings/team", icon: Users, label: "Equipe", tip: "Equipe", permission: "tenant:users:view" },
        { href: "/dashboard/settings/roles", icon: Shield, label: "Perfis e Permissões", tip: "Perfis", permission: "tenant:permissions:view" },
        { href: "/dashboard/settings/seguranca", icon: Lock, label: "Segurança", tip: "Segurança", permission: "tenant:settings:view" },
        { href: "/dashboard/settings/sessoes", icon: Clock, label: "Sessões Ativas", tip: "Sessões", permission: "tenant:settings:view" },
    ].filter((item) => canSeeTenantItem(user, item.permission));
    const settingsItems = [
        { href: "/dashboard/settings/account", icon: UserCircle, label: "Meu Perfil", tip: "Meu Perfil" },
        { href: "/dashboard/settings/tenant", icon: Landmark, label: "Meu Produtor", tip: "Dados do Produtor", permission: "tenant:settings:view" },
        { href: "/dashboard/settings/billing", icon: CreditCard, label: "Assinatura e Pagamentos", tip: "Assinatura", permission: "tenant:billing:view" },
        { href: "/dashboard/settings/ia", icon: BrainCircuit, label: "Uso de IA", tip: "Inteligência Artificial", permission: "tenant:billing:view" },
        { href: "/dashboard/settings/kb", icon: Book, label: "Base de Conhecimento", tip: "Wiki" },
        { href: "/dashboard/settings/smtp", icon: Mail, label: "Configuração de E-mail", tip: "E-mail", permission: "tenant:settings:view" },
        { href: "/dashboard/settings/support", icon: MessageSquare, label: "Ajuda e Suporte", tip: "Suporte" },
    ].filter((item) => canSeeTenantItem(user, item.permission));
    const activeModule = getModuleFromPath(pathname);
    const [collapsedModules, setCollapsedModules] = useState<ModuleKey[]>([]);
    const resolvedOpenModule = collapsedModules.includes(activeModule) ? openModule : openModule || activeModule;
    const activeBackofficeSection = getActiveBackofficeSection(pathname);
    const resolvedBackofficeSection = openBackofficeSection || activeBackofficeSection;
    const normalizedSearchQuery = normalizeSearchValue(deferredSearchQuery);
    const isSearching = normalizedSearchQuery.length > 0;

    const toggleModule = (key: ModuleKey) => {
        setCollapsedModules((prev) => prev.filter((item) => item !== key));
        setOpenModule(key);
    };

    React.useEffect(() => {
        setOpenModule(activeModule);
        setCollapsedModules((prev) => prev.filter((item) => item === activeModule));
    }, [activeModule]);

    const toggleSection = (moduleKey: string, sectionKey: string) => {
        setOpenSection(prev => ({
            [moduleKey]: prev[moduleKey] === sectionKey ? "" : sectionKey
        }));
    };

    const tenantLogoSrc = (() => {
        return resolveAssetUrl(tenant?.branding?.logoUrl);
    })();

    const canSeeBackofficeItem = useCallback((permission?: string) => {
        if (!user?.role && !user?.is_superuser) return false;
        if (!permission) return true;
        if (user?.is_superuser) return true;
        return hasBackofficePermission(user?.role as BackofficeRole | undefined, permission);
    }, [user?.is_superuser, user?.role]);

    const searchGroups = useMemo(() => {
        const coreItems: SearchableItem[] = CORE_CADASTROS.flatMap((section) =>
            section.items
                .filter((item) => !item.minimumTier || tierAtLeast(activePlanTier, item.minimumTier))
                .map((item) => ({
                    ...item,
                    group: "Cadastros",
                    section: section.label,
                }))
        );

        const moduleGroups = MODULOS_OPERACIONAIS.map((moduleGroup) => ({
            moduleId: moduleGroup.moduleId,
            key: moduleGroup.key,
            label: moduleGroup.label,
            items: moduleGroup.sections.flatMap((section) =>
                section.items
                    .filter((item) => !item.minimumTier || tierAtLeast(activePlanTier, item.minimumTier))
                    .filter((item) => canSeeTenantItem(user, item.permission))
                    .map((item) => ({
                        ...item,
                        group: moduleGroup.label,
                        section: section.label,
                        moduleId: moduleGroup.moduleId,
                        activeClassName: moduleActive[moduleGroup.key as keyof typeof moduleActive],
                    }))
            ),
        }));

        const backofficeItems: SearchableItem[] = BACKOFFICE_SECTIONS.flatMap((section) =>
            section.items
                .filter((item) => canSeeBackofficeItem(item.permission))
                .map((item) => ({
                    ...item,
                    group: "Administração SaaS",
                    section: section.label,
                    activeClassName: backofficeActive,
                }))
        );

        return {
            coreItems,
            moduleGroups,
            backofficeItems,
            accessItems: accessItems.map((item) => ({
                ...item,
                group: "Gestão de Acessos",
            })) satisfies SearchableItem[],
            settingsItems: settingsItems.map((item) => ({
                ...item,
                group: "Configurações",
            })) satisfies SearchableItem[],
        };
    }, [activePlanTier, accessItems, canSeeBackofficeItem, settingsItems, user]);

    const filteredSearchGroups = useMemo(() => {
        if (!normalizedSearchQuery) {
            return {
                coreItems: [],
                moduleGroups: [],
                backofficeItems: [],
                accessItems: [],
                settingsItems: [],
                total: 0,
            };
        }

        const coreItems = searchGroups.coreItems.filter((item) => itemMatchesSearch(item, normalizedSearchQuery));
        const moduleGroups = searchGroups.moduleGroups
            .map((group) => ({
                ...group,
                items: group.items.filter((item) => itemMatchesSearch(item, normalizedSearchQuery)),
            }))
            .filter((group) => group.items.length > 0);
        const backofficeItems = searchGroups.backofficeItems.filter((item) => itemMatchesSearch(item, normalizedSearchQuery));
        const accessSearchItems = searchGroups.accessItems.filter((item) => itemMatchesSearch(item, normalizedSearchQuery));
        const settingsSearchItems = searchGroups.settingsItems.filter((item) => itemMatchesSearch(item, normalizedSearchQuery));

        return {
            coreItems,
            moduleGroups,
            backofficeItems,
            accessItems: accessSearchItems,
            settingsItems: settingsSearchItems,
            total:
                coreItems.length +
                moduleGroups.reduce((sum, group) => sum + group.items.length, 0) +
                backofficeItems.length +
                accessSearchItems.length +
                settingsSearchItems.length,
        };
    }, [normalizedSearchQuery, searchGroups]);

    const renderSearchItems = (items: SearchableItem[]) => items.map((item) => {
        const Icon = item.icon;
        return (
            <SidebarMenuItem key={`${item.group}-${item.href}`}>
                <SidebarMenuButton
                    render={<Link href={item.href} onClick={() => setSearchQuery("")} />}
                    isActive={pathname === item.href}
                    tooltip={item.tip ?? item.label}
                    className={cn(
                        "h-auto py-2",
                        item.activeClassName || "relative data-[active=true]:bg-primary/5 data-[active=true]:text-primary data-[active=true]:font-bold before:absolute before:left-0 before:top-1 before:bottom-1 before:w-[2px] before:bg-primary before:rounded-full before:opacity-0 data-[active=true]:before:opacity-100 transition-all"
                    )}
                >
                    <Icon className="size-3.5 shrink-0 text-primary" />
                    <span className="flex min-w-0 flex-col gap-0.5">
                        <span className="truncate">{item.label}</span>
                        <span className="truncate text-[10px] font-normal text-muted-foreground">
                            {item.group}{item.section ? ` > ${item.section}` : ""}
                        </span>
                    </span>
                    {item.alertBadge && hasCadernoAlerta && (
                        <Badge variant="destructive" className="ml-auto">
                            <AlertCircle className="size-3" />
                        </Badge>
                    )}
                </SidebarMenuButton>
            </SidebarMenuItem>
        );
    });

    return (
        <Sidebar collapsible="icon">
            <SidebarHeader className="border-b border-border/50 h-14 flex items-center justify-center p-0 overflow-hidden">
                <Link href="/dashboard" className="flex items-center justify-center w-full h-full outline-none">
                    {/* Collapsed */}
                    <div className="hidden group-data-[collapsible=icon]:flex w-full items-center justify-center">
                        <div className="flex size-8 items-center justify-center rounded-sm bg-primary text-primary-foreground shadow-sm">
                            <Sprout className="size-3.5" />
                        </div>
                    </div>
                    {/* Expanded */}
                    <div className="group-data-[collapsible=icon]:hidden flex items-center gap-2.5 px-3 w-full">
                        <div className="flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-md bg-primary/5 text-primary shadow-sm ring-1 ring-border/60">
                            {tenantLogoSrc ? (
                                <img
                                    src={tenantLogoSrc}
                                    alt={tenant?.nome ?? "Logo"}
                                    className="h-full w-full object-contain p-1.5"
                                />
                            ) : (
                                <div className="flex size-9 shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground shadow-sm">
                                    <Sprout className="size-3.5" />
                                </div>
                            )}
                        </div>
                        <span className="font-black text-primary text-lg truncate">
                            {tenant?.nome ?? "AgroSaaS"}
                        </span>
                    </div>
                </Link>
            </SidebarHeader>

            {tenant && (
                <div className="group-data-[collapsible=icon]:hidden border-b border-border/50 px-3 py-2">
                    <div className="flex items-center gap-1.5">
                        <div className="relative min-w-0 flex-1">
                            <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                            <Input
                                value={searchQuery}
                                onChange={(event) => setSearchQuery(event.target.value)}
                                placeholder="Pesquisar menu..."
                                aria-label="Pesquisar itens do menu"
                                className="h-8 rounded-sm bg-sidebar-accent/40 pl-8 text-xs"
                            />
                        </div>
                        {searchQuery && (
                            <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="size-8 shrink-0"
                                aria-label="Limpar pesquisa do menu"
                                onClick={() => setSearchQuery("")}
                            >
                                <X data-icon="icon" />
                            </Button>
                        )}
                    </div>
                </div>
            )}

            <SidebarContent>
                {isSearching ? (
                    <SidebarGroup>
                        <SidebarGroupLabel>
                            {filteredSearchGroups.total === 1
                                ? "1 item encontrado"
                                : `${filteredSearchGroups.total} itens encontrados`}
                        </SidebarGroupLabel>
                        <SidebarGroupContent>
                            {filteredSearchGroups.total === 0 ? (
                                <div className="px-2 py-6 text-center text-xs text-muted-foreground">
                                    Nenhum item encontrado para &quot;{deferredSearchQuery}&quot;.
                                </div>
                            ) : (
                                <SidebarMenu>
                                    {filteredSearchGroups.coreItems.length > 0 && (
                                        <>
                                            <SidebarMenuSubItem>
                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                    Cadastros
                                                </div>
                                            </SidebarMenuSubItem>
                                            {renderSearchItems(filteredSearchGroups.coreItems)}
                                        </>
                                    )}

                                    {filteredSearchGroups.moduleGroups.map((moduleGroup) => (
                                        <ModuleGate key={moduleGroup.key} moduleId={moduleGroup.moduleId}>
                                            <SidebarMenuSubItem>
                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                    {moduleGroup.label}
                                                </div>
                                            </SidebarMenuSubItem>
                                            {renderSearchItems(moduleGroup.items)}
                                        </ModuleGate>
                                    ))}

                                    {filteredSearchGroups.backofficeItems.length > 0 && (
                                        <>
                                            <SidebarMenuSubItem>
                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                    Administração SaaS
                                                </div>
                                            </SidebarMenuSubItem>
                                            {renderSearchItems(filteredSearchGroups.backofficeItems)}
                                        </>
                                    )}

                                    {filteredSearchGroups.accessItems.length > 0 && (
                                        <>
                                            <SidebarMenuSubItem>
                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                    Gestão de Acessos
                                                </div>
                                            </SidebarMenuSubItem>
                                            {renderSearchItems(filteredSearchGroups.accessItems)}
                                        </>
                                    )}

                                    {filteredSearchGroups.settingsItems.length > 0 && (
                                        <>
                                            <SidebarMenuSubItem>
                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                    Configurações
                                                </div>
                                            </SidebarMenuSubItem>
                                            {renderSearchItems(filteredSearchGroups.settingsItems)}
                                        </>
                                    )}
                                </SidebarMenu>
                            )}
                        </SidebarGroupContent>
                    </SidebarGroup>
                ) : (
                    <>
                        {/* ── Geral ─────────────────────────────────── */}
                        {tenant && (
                            <SidebarGroup>
                                <SidebarGroupLabel>Geral</SidebarGroupLabel>
                                <SidebarGroupContent>
                                    <SidebarMenu>
                                        <SidebarMenuItem>
                                            <SidebarMenuButton
                                                render={<Link href="/dashboard" />}
                                                isActive={pathname === "/dashboard"}
                                                tooltip="Dashboard"
                                                className="relative data-[active=true]:bg-primary/5 data-[active=true]:text-primary data-[active=true]:font-bold before:absolute before:left-0 before:top-1 before:bottom-1 before:w-[2px] before:bg-primary before:rounded-full before:opacity-0 data-[active=true]:before:opacity-100 transition-all"
                                            >
                                                <LayoutDashboard className="size-3.5 flex-shrink-0 text-primary" />
                                                <span className="truncate">Dashboard</span>
                                            </SidebarMenuButton>
                                        </SidebarMenuItem>
                                    </SidebarMenu>
                                </SidebarGroupContent>
                            </SidebarGroup>
                        )}

                        {/* ── Módulos ───────────────────────────────── */}
                        {tenant && (
                            <SidebarGroup>
                                <SidebarGroupLabel>Módulos</SidebarGroupLabel>
                                <SidebarGroupContent>
                                    <SidebarMenu>

                                        {/* CORE — Cadastros e Tabelas Compartilhadas (SEMPRE VISÍVEL) */}
                                        <SidebarMenuItem>
                                            <SidebarMenuButton
                                                onClick={() => setOpenModule(resolvedOpenModule === "CADASTROS" ? "" : "CADASTROS")}
                                                isActive={pathname.startsWith("/cadastros")}
                                                tooltip="Cadastros.."
                                            >
                                                {CORE_CADASTROS[0]?.icon && (() => {
                                                    const Icon = CORE_CADASTROS[0].icon;
                                                    return <Icon className="size-3.5 text-primary" />;
                                                })()}
                                                <span className="font-semibold">Cadastros</span>
                                                <ChevronRight className={cn("ml-auto size-3.5 transition-transform duration-200", resolvedOpenModule === "CADASTROS" && "rotate-90")} />
                                            </SidebarMenuButton>
                                            {resolvedOpenModule === "CADASTROS" && (
                                                <SidebarMenuSub>
                                                    {CORE_CADASTROS.map((section) => (
                                                        <React.Fragment key={section.key}>
                                                            {/* Seção de label */}
                                                            <SidebarMenuSubItem>
                                                                <div className="px-2 py-1.5 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/60">
                                                                    {section.label}
                                                                </div>
                                                            </SidebarMenuSubItem>

                                                            {/* Items dessa seção */}
                                                            {section.items
                                                                .filter((item) => !item.minimumTier || tierAtLeast(activePlanTier, item.minimumTier))
                                                                .map((item) => (
                                                                    <SidebarMenuSubItem key={item.href}>
                                                                        <SidebarMenuSubButton isActive={pathname === item.href} render={<Link href={item.href} />}>
                                                                            <item.icon className="size-3.5 flex-shrink-0 text-primary" />
                                                                            <span>{item.label}</span>
                                                                        </SidebarMenuSubButton>
                                                                    </SidebarMenuSubItem>
                                                                ))}
                                                        </React.Fragment>
                                                    ))}
                                                </SidebarMenuSub>
                                            )}
                                        </SidebarMenuItem>

                                        {/* Módulos Operacionais — renderizados do sidebar-config */}
                                        {MODULOS_OPERACIONAIS.map((moduleGroup) => (
                                            <ModuleGate key={moduleGroup.key} moduleId={moduleGroup.moduleId}>
                                                <SidebarMenuItem>
                                                <SidebarMenuButton
                                                        onClick={() => {
                                                            const key = moduleGroup.key as ModuleKey;
                                                            if (resolvedOpenModule === key) {
                                                                setOpenModule("");
                                                                setCollapsedModules((prev) => prev.includes(key) ? prev : [...prev, key]);
                                                                return;
                                                            }
                                                            toggleModule(key);
                                                        }}
                                                        isActive={moduleGroup.sections.some((section) =>
                                                            section.items.some((item) => pathname.startsWith(item.href))
                                                        )}
                                                        tooltip={moduleGroup.label}
                                                        className={cn(moduleActive[moduleGroup.key as keyof typeof moduleActive] || "data-[active=true]:bg-primary/10 data-[active=true]:text-primary")}
                                                    >
                                                        <moduleGroup.icon className="size-3.5 text-primary" />
                                                        <span className="font-semibold">{moduleGroup.label}</span>
                                                        <ChevronRight className={cn("ml-auto size-3.5 transition-transform duration-200", resolvedOpenModule === (moduleGroup.key as ModuleKey) && "rotate-90")} />
                                                    </SidebarMenuButton>

                                                    {resolvedOpenModule === (moduleGroup.key as ModuleKey) && (
                                                        <SidebarMenuSub>
                                                            {moduleGroup.sections.map((section) => {
                                                                const visibleItems = section.items.filter(
                                                                    (item) => !item.minimumTier || tierAtLeast(activePlanTier, item.minimumTier)
                                                                );
                                                                if (visibleItems.length === 0) {
                                                                    return null;
                                                                }
                                                                const resolvedOpenSection =
                                                                    openSection[moduleGroup.key] ||
                                                                    (activeModule === moduleGroup.key ? getActiveSection(moduleGroup.key, pathname) : "");
                                                                const isSectionOpen = resolvedOpenSection === section.key;

                                                                return (
                                                                    <SidebarMenuSubItem key={section.key}>
                                                                        <button
                                                                            type="button"
                                                                            onClick={() => toggleSection(moduleGroup.key, section.key)}
                                                                            className={cn(
                                                                                "flex w-full items-center gap-2 px-1.5 py-1 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
                                                                                getSectionActiveStyle(moduleGroup.key),
                                                                                section.items.some((item) => pathname.startsWith(item.href)) && "text-primary"
                                                                            )}
                                                                        >
                                                                            <span className="truncate">{section.label}</span>
                                                                            <ChevronRight className={cn("ml-auto size-2.5 flex-shrink-0 transition-transform duration-200", isSectionOpen && "rotate-90")} />
                                                                        </button>

                                                                        {isSectionOpen && (
                                                                            <SidebarMenuSub className="ml-1.5">
                                                                                {visibleItems.map((item) => (
                                                                                    <SidebarMenuSubItem key={item.href}>
                                                                                        <SidebarMenuSubButton isActive={pathname === item.href} render={<Link href={item.href} />}>
                                                                                            <item.icon className="size-2.5 flex-shrink-0 text-primary" />
                                                                                            <span className="truncate">{item.label}</span>
                                                                                            {(item as any).alertBadge && hasCadernoAlerta && (
                                                                                                <Badge variant="destructive" className="ml-auto">
                                                                                                    <AlertCircle className="size-3" />
                                                                                                </Badge>
                                                                                            )}
                                                                                        </SidebarMenuSubButton>
                                                                                    </SidebarMenuSubItem>
                                                                                ))}
                                                                            </SidebarMenuSub>
                                                                        )}
                                                                    </SidebarMenuSubItem>
                                                                );
                                                            })}
                                                        </SidebarMenuSub>
                                                    )}
                                                </SidebarMenuItem>
                                            </ModuleGate>
                                        ))}


                                    </SidebarMenu>
                                </SidebarGroupContent>
                            </SidebarGroup>
                        )}

                        {/* ── Administração SaaS (6 seções agrupadas por domínio) ── */}
                        <BackofficeNav
                            pathname={pathname}
                            user={user}
                            openBackofficeSection={resolvedBackofficeSection}
                            setOpenBackofficeSection={setOpenBackofficeSection}
                        />

                        {/* ── Gestão de Acessos ─────────────────────── */}
                        {tenant && accessItems.length > 0 && (
                            <SidebarGroup>
                                <SidebarGroupLabel>Gestão de Acessos</SidebarGroupLabel>
                                <SidebarGroupContent>
                                    <SidebarMenu>
                                        {accessItems.map(({ href, icon: Icon, label, tip }) => (
                                            <SidebarMenuItem key={href}>
                                                <SidebarMenuButton
                                                    isActive={pathname === href}
                                                    tooltip={tip}
                                                    className="relative data-[active=true]:bg-primary/5 data-[active=true]:text-primary data-[active=true]:font-bold before:absolute before:left-0 before:top-1 before:bottom-1 before:w-[2px] before:bg-primary before:rounded-full before:opacity-0 data-[active=true]:before:opacity-100 transition-all"
                                                    render={<Link href={href} />}
                                                >
                                                    <Icon className="size-3.5 shrink-0 text-primary" />
                                                    <span className="truncate">{label}</span>
                                                </SidebarMenuButton>
                                            </SidebarMenuItem>
                                        ))}
                                    </SidebarMenu>
                                </SidebarGroupContent>
                            </SidebarGroup>
                        )}

                        {/* ── Configurações ─────────────────────────── */}
                        {tenant && settingsItems.length > 0 && <SidebarGroup>
                            <SidebarGroupLabel>Configurações</SidebarGroupLabel>
                            <SidebarGroupContent>
                                <SidebarMenu>
                                    {settingsItems.map(({ href, icon: Icon, label, tip }) => (
                                        <SidebarMenuItem key={href}>
                                            <SidebarMenuButton
                                                isActive={pathname === href}
                                                tooltip={tip}
                                                className="relative data-[active=true]:bg-primary/5 data-[active=true]:text-primary data-[active=true]:font-bold before:absolute before:left-0 before:top-1 before:bottom-1 before:w-[2px] before:bg-primary before:rounded-full before:opacity-0 data-[active=true]:before:opacity-100 transition-all font-medium text-sidebar-foreground/80"
                                                render={<Link href={href} />}
                                            >
                                                <Icon className="size-3.5 shrink-0 text-primary" />
                                                <span className="truncate">{label}</span>
                                            </SidebarMenuButton>
                                        </SidebarMenuItem>
                                    ))}
                                </SidebarMenu>
                            </SidebarGroupContent>
                        </SidebarGroup>}
                    </>
                )}
            </SidebarContent>
        </Sidebar>
    );
}

"use client";

import { useAppStore } from "@/lib/stores/app-store";
import { apiFetch } from "@/lib/api";
import { Building2, Trees, Zap, Check, ChevronDown } from "lucide-react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { setContextCookies } from "@/app/actions/auth";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { useEffect } from "react";
import type { UnidadeProdutiva } from "@/types/global";
import { resolveAssetUrl } from "@/lib/runtime-config";

export function ContextSelector() {
    const queryClient = useQueryClient();
    const { 
        grupos, 
        activeGrupoId, 
        activeFazendaId, 
        isVisaoGrupo, 
        setActiveFazenda, 
        setActiveGrupo, 
        tenant,
        tenantContexts,
        loadTenantContexts,
        switchTenantContext,
        unidadesProdutivasAutorizadas,
        token,
        _hasHydrated,
    } = useAppStore();

    // Carrega tenants/contextos ao montar componente
    useEffect(() => {
        if (tenantContexts.length === 0) {
            loadTenantContexts();
        }
    }, [tenantContexts.length, loadTenantContexts]);

    const grupoAtivo = grupos.find(g => g.id === activeGrupoId) ?? grupos[0];
    const multiGrupo = grupos.length > 1;
    const multiContexto = tenantContexts.length > 1;
    const fazendasDoGrupoAtivo = grupoAtivo?.fazendas ?? [];
    const activeFazendaValida = fazendasDoGrupoAtivo.some((f) => f.id === activeFazendaId);
    const fallbackFazendaId = fazendasDoGrupoAtivo[0]?.id ?? null;
    const effectiveFazendaId = activeFazendaValida ? activeFazendaId : fallbackFazendaId;
    const fazendaAtivaStore = unidadesProdutivasAutorizadas.find((f) => f.id === activeFazendaId);
    const fazendaFallbackStore = unidadesProdutivasAutorizadas.find((f) => f.id === fallbackFazendaId);

    useEffect(() => {
        if (!tenant || !grupoAtivo || isVisaoGrupo) return;
        if (activeFazendaValida) return;
        if (fallbackFazendaId) {
            setActiveFazenda(fallbackFazendaId, false);
            void setContextCookies(tenant.id, fallbackFazendaId).then(() => {
                queryClient.clear();
                window.location.reload();
            });
        }
    }, [
        tenant,
        grupoAtivo,
        isVisaoGrupo,
        activeFazendaValida,
        fallbackFazendaId,
        setActiveFazenda,
        queryClient,
    ]);

    const { data: fazendaAtivaDetalhe } = useQuery<UnidadeProdutiva | null>({
        queryKey: ["contexto-ativo-fazenda", effectiveFazendaId],
        queryFn: async () => {
            if (!effectiveFazendaId) return null;
            if (!token) return fazendaAtivaStore ?? fazendaFallbackStore ?? null;
            try {
                return await apiFetch<UnidadeProdutiva>(`/unidades-produtivas/${effectiveFazendaId}`, { suppressErrorLog: true });
            } catch {
                return fazendaAtivaStore ?? fazendaFallbackStore ?? null;
            }
        },
        enabled: _hasHydrated && !!effectiveFazendaId && activeFazendaValida,
        retry: false,
        staleTime: 60_000,
    });

    const fazendaAtiva = fazendaAtivaDetalhe ?? fazendaAtivaStore ?? fazendaFallbackStore ?? null;
    const fazendaLogoSrc = (() => {
        return resolveAssetUrl(fazendaAtiva?.logo_url);
    })();

    // Valor do select: "TODOS" | "grupo:{id}" | "{unidade_produtiva_id}"
    const selectValue = isVisaoGrupo
        ? "TODOS"
        : (effectiveFazendaId || "");

    const refreshContextData = async (fazendaId: string | null) => {
        if (!tenant) return;
        await setContextCookies(tenant.id, fazendaId);
        queryClient.clear();
        window.location.reload();
    };

    const handleChange = (val: string) => {
        if (val === "TODOS") {
            setActiveFazenda(activeFazendaId || "", true);
            void refreshContextData(null);
        } else if (val.startsWith("grupo:")) {
            const grupoId = val.replace("grupo:", "");
            const nextFazendaId = grupos.find((g) => g.id === grupoId)?.fazendas[0]?.id ?? null;
            setActiveGrupo(grupoId);
            void refreshContextData(nextFazendaId);
        } else {
            const isAuthorized = grupos.some((grupo) => grupo.fazendas.some((fazenda) => fazenda.id === val));
            if (!isAuthorized) return;
            setActiveFazenda(val, false);
            void refreshContextData(val);
        }
    };

    const handleSwitchAssinatura = async (tenantId: string) => {
        if (tenantId === activeGrupoId) return;
        await switchTenantContext(tenantId);
    };

    if (!tenant || grupos.length === 0) return null;

    // Se há múltiplos contextos, mostrar dropdown de tenants
    if (multiContexto) {
        const contextoAtivo = tenantContexts.find(a => a.tenant_id === activeGrupoId);

        return (
            <div className="flex items-center gap-2">
                <DropdownMenu>
                    <DropdownMenuTrigger className="flex items-center gap-2 px-3 py-2 rounded-sm border border-border bg-white hover:bg-muted/50 transition-colors outline-none shadow-sm dark:bg-neutral-950">
                        <div className="flex h-7 w-7 items-center justify-center rounded-sm bg-green-100 text-green-700 dark:bg-green-500/10 dark:text-green-500">
                            {fazendaLogoSrc && !isVisaoGrupo ? (
                                <img src={fazendaLogoSrc} alt={fazendaAtiva?.nome ?? "Propriedade"} className="h-full w-full rounded-sm object-cover" />
                            ) : (
                                <Building2 size={16} />
                            )}
                        </div>
                        <div className="flex flex-col items-start">
                            <span className="text-[10px] uppercase font-bold text-neutral-500 tracking-wider">Tenant</span>
                            <span className="text-xs font-medium text-neutral-800 dark:text-neutral-200 truncate max-w-[150px]">
                                {contextoAtivo?.tenant_nome || "Selecionar"}
                            </span>
                        </div>
                        <ChevronDown size={12} className="text-muted-foreground" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-80">
                        <DropdownMenuLabel className="text-[10px] uppercase text-muted-foreground">
                            Meus Tenants
                        </DropdownMenuLabel>
                        <DropdownMenuSeparator />
                        {tenantContexts.map((contexto) => {
                            const isAtiva = contextoAtivo?.tenant_id === contexto.tenant_id;
                            return (
                                <DropdownMenuItem
                                    key={contexto.tenant_id}
                                    onClick={() => handleSwitchAssinatura(contexto.tenant_id)}
                                    className={`flex flex-col items-start gap-1 p-3 cursor-pointer ${
                                        isAtiva ? 'bg-primary/5' : ''
                                    }`}
                                    disabled={isAtiva}
                                >
                                    <div className="flex items-center justify-between w-full">
                                        <div className="flex items-center gap-2">
                                            <Trees size={14} className="text-muted-foreground" />
                                            <span className="text-sm font-medium">{contexto.tenant_nome}</span>
                                        </div>
                                        {isAtiva && <Check size={14} className="text-primary" />}
                                    </div>
                                    <div className="flex items-center gap-2 w-full">
                                        <Badge
                                            variant={contexto.is_ativa ? "default" : "secondary"}
                                        >
                                            {contexto.plano_nome}
                                        </Badge>
                                        <span className="text-[10px] text-muted-foreground">
                                            {contexto.total_fazendas} fazenda(s)
                                        </span>
                                        {contexto.plano_tier !== "BASICO" && (
                                            <Zap size={10} className="text-amber-500" />
                                        )}
                                    </div>
                                </DropdownMenuItem>
                            );
                        })}
                    </DropdownMenuContent>
                </DropdownMenu>

                {/* Seletor de fazendas do grupo ativo */}
                <select
                    className="bg-white dark:bg-neutral-950 border border-neutral-200/60 dark:border-neutral-800 rounded-sm px-3 py-2 text-sm shadow-sm outline-none cursor-pointer appearance-none truncate max-w-[200px] hover:border-neutral-300 dark:hover:border-neutral-700"
                    value={selectValue}
                    onChange={(e) => handleChange(e.target.value)}
                >
                    {multiGrupo && (
                        <option value="TODOS" className="font-bold bg-neutral-100 dark:bg-neutral-900">
                            🌐 Visão Consolidada
                        </option>
                    )}

                    {grupos.filter(g => g.id === activeGrupoId).map((grupo) => (
                        <optgroup key={grupo.id} label={grupo.nome} className="font-semibold text-neutral-500">
                            {grupo.fazendas.length === 0 && (
                                <option disabled value={`grupo:${grupo.id}`} className="italic text-neutral-400">
                                    (sem fazendas cadastradas)
                                </option>
                            )}
                            {grupo.fazendas.map((faz) => (
                                <option key={faz.id} value={faz.id} className="text-neutral-800 dark:text-neutral-200 bg-white dark:bg-neutral-950 font-medium">
                                    {faz.nome}
                                </option>
                            ))}
                        </optgroup>
                    ))}
                </select>
            </div>
        );
    }

    // Se há apenas um contexto, manter o seletor original
    return (
        <div className="flex items-center gap-3 relative group rounded-sm border border-neutral-200/60 bg-white px-3 py-2 text-sm shadow-[0_2px_8px_-4px_rgba(0,0,0,0.04)] transition-colors hover:border-neutral-300 dark:border-neutral-800 dark:bg-neutral-950 dark:hover:border-neutral-700 cursor-pointer">
            <div className="flex h-7 w-7 items-center justify-center rounded-sm bg-green-100 text-green-700 dark:bg-green-500/10 dark:text-green-500">
                {!isVisaoGrupo && fazendaLogoSrc ? (
                    <img src={fazendaLogoSrc} alt={fazendaAtiva?.nome ?? "Propriedade"} className="h-full w-full rounded-sm object-cover" />
                ) : isVisaoGrupo ? (
                    <Building2 size={16} />
                ) : (
                    <Trees size={16} />
                )}
            </div>

            <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-neutral-500 tracking-wider">Contexto Ativo</span>
                <select
                    className="bg-transparent border-none outline-none font-medium text-neutral-800 dark:text-neutral-200 py-0 pl-0 pr-8 cursor-pointer appearance-none truncate max-w-[150px] lg:max-w-[200px]"
                    value={selectValue}
                    onChange={(e) => handleChange(e.target.value)}
                >
                    {multiGrupo && (
                        <option value="TODOS" className="font-bold bg-neutral-100 dark:bg-neutral-900">
                            🌐 Visão Consolidada
                        </option>
                    )}

                    {grupos.map((grupo) => (
                        <optgroup key={grupo.id} label={grupo.nome} className="font-semibold text-neutral-500">
                            {grupo.fazendas.length === 0 && (
                                <option disabled value={`grupo:${grupo.id}`} className="italic text-neutral-400">
                                    (sem fazendas cadastradas)
                                </option>
                            )}
                            {grupo.fazendas.map((faz) => (
                                <option key={faz.id} value={faz.id} className="text-neutral-800 dark:text-neutral-200 bg-white dark:bg-neutral-950 font-medium">
                                    {faz.nome}
                                </option>
                            ))}
                        </optgroup>
                    ))}
                </select>
            </div>
        </div>
    );
}

