"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { Bell, BellRing, CheckCheck, CloudRain, Satellite, Clock, Users, Beef, ShieldAlert, Loader2, ClipboardList, TriangleAlert, Lightbulb } from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useAppStore } from "@/lib/stores/app-store";
import { getWsBaseUrl } from "@/lib/runtime-config";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Separator } from "@/components/ui/separator";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";

// ── Types ─────────────────────────────────────────────────────────────────────

interface Notificacao {
    id: string;
    tipo: string;
    titulo: string;
    mensagem: string;
    nivel: string;
    lida: boolean;
    origem: string | null;
    origem_id: string | null;
    meta: Record<string, unknown>;
    created_at: string;
    read_at: string | null;
}

// ── Config per tipo ───────────────────────────────────────────────────────────

const TIPO_CONFIG: Record<string, { label: string; color: string; bg: string; icon: React.ComponentType<{ className?: string }> }> = {
    PREVISAO_CHUVA:       { label: "Clima",      color: "text-blue-600",   bg: "bg-blue-100 dark:bg-blue-950/40",   icon: CloudRain },
    NDVI_BAIXO:           { label: "NDVI",       color: "text-orange-600", bg: "bg-orange-100 dark:bg-orange-950/40", icon: Satellite },
    VENCIMENTO_APLICACAO: { label: "Carência",   color: "text-red-600",    bg: "bg-red-100 dark:bg-red-950/40",     icon: Clock },
    DIARIA_PENDENTE:      { label: "RH",         color: "text-yellow-600", bg: "bg-yellow-100 dark:bg-yellow-950/40", icon: Users },
    EMPREITADA_VENCENDO:  { label: "Empreitada", color: "text-purple-600", bg: "bg-purple-100 dark:bg-purple-950/40", icon: Beef },
    MANEJO_PENDENTE:      { label: "Pecuária",   color: "text-green-600",  bg: "bg-green-100 dark:bg-green-950/40", icon: ShieldAlert },
    // Financeiro
    PLANO_ACAO:           { label: "Ação",       color: "text-primary",    bg: "bg-primary/10",                     icon: ClipboardList },
    ALERTA_FINANCEIRO:    { label: "Financeiro", color: "text-destructive", bg: "bg-destructive/10",               icon: TriangleAlert },
    RECOMENDACAO:         { label: "Dica",       color: "text-amber-600",  bg: "bg-amber-100 dark:bg-amber-950/40", icon: Lightbulb },
    WORKFLOW_OPERACIONAL: { label: "Workflow",   color: "text-rose-600",   bg: "bg-rose-100 dark:bg-rose-950/40", icon: TriangleAlert },
};

const DEFAULT_CONFIG = { label: "Alerta", color: "text-muted-foreground", bg: "bg-muted", icon: Bell };

function getTipoConfig(tipo: string) {
    return TIPO_CONFIG[tipo] ?? DEFAULT_CONFIG;
}

// ── Component ─────────────────────────────────────────────────────────────────

export function NotificationBell() {
    const { token, tenant } = useAppStore();
    const queryClient = useQueryClient();
    const [open, setOpen] = useState(false);
    const [wsNaoLidas, setWsNaoLidas] = useState<number | null>(null);
    const wsRef = useRef<WebSocket | null>(null);

    // ── REST queries ─────────────────────────────────────────────────────────
    const { data: notificacoes = [], isLoading } = useQuery<Notificacao[]>({
        queryKey: ["notificacoes"],
        queryFn: () => apiFetch<Notificacao[]>("/notificacoes/?limit=30"),
        enabled: open,
        staleTime: 30_000,
    });

    const marcarLidasMutation = useMutation({
        mutationFn: (ids?: string[]) =>
            apiFetch("/notificacoes/marcar-lidas", { method: "POST", body: JSON.stringify({ ids: ids ?? null }) }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["notificacoes"] });
            setWsNaoLidas(0);
        },
    });

    const demoMutation = useMutation({
        mutationFn: () => apiFetch("/notificacoes/demo", { method: "POST" }),
    });

    // ── WebSocket ─────────────────────────────────────────────────────────────
    const connectWs = useCallback(() => {
        if (!token || !tenant || wsRef.current?.readyState === WebSocket.OPEN) return;

        const wsUrl = `${process.env.NEXT_PUBLIC_WS_URL ?? getWsBaseUrl().replace(/\/api\/v1$/, "")}/api/v1/notificacoes/ws?token=${token}`;
        const ws = new WebSocket(wsUrl);
        wsRef.current = ws;

        ws.onmessage = (event) => {
            try {
                const data = JSON.parse(event.data);
                if (data.tipo === "ping") return;
                if (data.tipo === "init" || data.tipo === "contagem_atualizada") {
                    setWsNaoLidas(data.nao_lidas ?? 0);
                } else if (data.tipo === "nova_notificacao") {
                    setWsNaoLidas(prev => (prev ?? 0) + 1);
                    // Invalidate list if sheet is open
                    queryClient.invalidateQueries({ queryKey: ["notificacoes"] });
                }
            } catch (_) {}
        };

        ws.onclose = (event) => {
            // Não reconectar em falhas de autenticação (1008) ou fechamento limpo (1000)
            if (event.code === 1008 || event.code === 1000) return;
            setTimeout(connectWs, 5000);
        };

        ws.onerror = () => {
            ws.close();
        };
    }, [token, queryClient]);

    useEffect(() => {
        connectWs();
        return () => {
            wsRef.current?.close();
        };
    }, [connectWs]);

    // Mark as read when opening sheet
    const handleOpenChange = useCallback((next: boolean) => {
        setOpen(next);
    }, []);

    const handleMarcarTodas = useCallback(() => {
        marcarLidasMutation.mutate(undefined);
    }, [marcarLidasMutation]);

    const handleMarcarUma = useCallback((id: string, lida: boolean) => {
        if (lida) return;
        marcarLidasMutation.mutate([id]);
    }, [marcarLidasMutation]);

    const naoLidas = wsNaoLidas ?? notificacoes.filter(n => !n.lida).length;

    // ── Render ────────────────────────────────────────────────────────────────
    return (
        <>
            <Button
                variant="ghost"
                size="icon-sm"
                onClick={() => setOpen(true)}
                className="relative text-primary"
                aria-label="Notificações"
            >
                {naoLidas > 0 ? (
                    <BellRing className="size-4.5 animate-pulse text-primary" strokeWidth={2.5} />
                ) : (
                    <Bell className="size-4.5" strokeWidth={2} />
                )}
                {naoLidas > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 min-w-4 items-center justify-center rounded-full border border-sidebar bg-primary px-1 text-[9px] font-bold leading-none text-sidebar shadow-sm ring-2 ring-sidebar">
                        {naoLidas > 9 ? "9+" : naoLidas}
                    </span>
                )}
            </Button>

            <Sheet open={open} onOpenChange={handleOpenChange}>
                <SheetContent className="w-[400px] flex flex-col p-0">
                    <SheetHeader className="px-4 pt-4 pb-3 border-b flex-shrink-0">
                        <div className="flex items-center justify-between">
                            <SheetTitle className="flex items-center gap-2 text-base">
                                <Bell className="size-4" />
                                Notificações
                                {naoLidas > 0 && (
                                    <Badge variant="destructive">
                                        {naoLidas}
                                    </Badge>
                                )}
                            </SheetTitle>
                            <div className="flex items-center gap-2">
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-7 text-xs"
                                    onClick={handleMarcarTodas}
                                    disabled={marcarLidasMutation.isPending || naoLidas === 0}
                                >
                                    <CheckCheck className="size-3.5 mr-1" />
                                    Marcar lidas
                                </Button>
                            </div>
                        </div>
                    </SheetHeader>

                    <div className="flex-1 overflow-y-auto">
                        {isLoading ? (
                            <div className="flex items-center justify-center py-12">
                                <Loader2 className="size-6 animate-spin text-muted-foreground" />
                            </div>
                        ) : notificacoes.length === 0 ? (
                            <div className="flex flex-col items-center justify-center py-16 text-center px-6">
                                <Bell className="size-10 text-muted-foreground/40 mb-3" />
                                <p className="font-medium text-sm">Sem notificações</p>
                                <p className="text-xs text-muted-foreground mt-1">Você está em dia com tudo!</p>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    className="mt-4 text-xs"
                                    onClick={() => demoMutation.mutate()}
                                    disabled={demoMutation.isPending}
                                >
                                    {demoMutation.isPending ? (
                                        <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" />
                                    ) : null}
                                    Gerar alertas de demonstração
                                </Button>
                            </div>
                        ) : (
                            <div className="divide-y divide-border/50">
                                {notificacoes.map((n) => {
                                    const cfg = getTipoConfig(n.tipo);
                                    const Icon = cfg.icon;
                                    const timeAgo = formatDistanceToNow(new Date(n.created_at), {
                                        addSuffix: true,
                                        locale: ptBR,
                                    });

                                    return (
                                        <button
                                            key={n.id}
                                            className={`w-full text-left px-4 py-3 flex gap-3 transition-colors hover:bg-muted/50 ${!n.lida ? "bg-muted/20" : ""}`}
                                            onClick={() => handleMarcarUma(n.id, n.lida)}
                                        >
                                            {/* Icon bubble */}
                                            <div className={`mt-0.5 flex-shrink-0 flex size-8 items-center justify-center rounded-full ${cfg.bg}`}>
                                                <Icon className={`size-4 ${cfg.color}`} />
                                            </div>

                                            {/* Content */}
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-start justify-between gap-2">
                                                    <span className={`text-sm font-medium leading-tight ${!n.lida ? "text-foreground" : "text-muted-foreground"}`}>
                                                        {n.titulo}
                                                    </span>
                                                    {!n.lida && (
                                                        <div className="size-2 rounded-full bg-primary shrink-0 mt-1.5" />
                                                    )}
                                                </div>
                                                <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2 leading-relaxed">
                                                    {n.mensagem}
                                                </p>
                                                <div className="flex items-center gap-2 mt-1.5">
                                                    <Badge
                                                        variant="outline"
                                                        className={`${cfg.color} border-current`}
                                                    >
                                                        {cfg.label}
                                                    </Badge>
                                                    <span className="text-[10px] text-muted-foreground">{timeAgo}</span>
                                                </div>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {notificacoes.length > 0 && (
                        <div className="border-t px-4 py-3 flex-shrink-0">
                            <Button
                                variant="ghost"
                                size="sm"
                                className="w-full text-xs text-muted-foreground"
                                onClick={() => demoMutation.mutate()}
                                disabled={demoMutation.isPending}
                            >
                                {demoMutation.isPending ? <Loader2 className="h-3 w-3 mr-1 animate-spin" /> : null}
                                + Gerar alertas de demonstração
                            </Button>
                        </div>
                    )}
                </SheetContent>
            </Sheet>
        </>
    );
}

"use client";

import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { Upload } from "lucide-react";
import { useState } from "react";

interface FormFieldProps {
  label: string;
  error?: string;
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}

export function FormField({ label, error, required, children, className }: FormFieldProps) {
  return (
    <div className={cn("space-y-2", className)}>
      <Label>
        {label}
        {required && <span className="text-destructive ml-1">*</span>}
      </Label>
      {children}
      {error && <p className="text-sm text-destructive mt-1">{error}</p>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Máscaras
// ---------------------------------------------------------------------------

function applyCNPJCPFMask(value: string): string {
  const digits = value.replace(/\D/g, "");
  if (digits.length <= 11) {
    // CPF: 000.000.000-00
    return digits
      .replace(/(\d{3})(\d)/, "$1.$2")
      .replace(/(\d{3})(\d)/, "$1.$2")
      .replace(/(\d{3})(\d{1,2})$/, "$1-$2");
  }
  // CNPJ: 00.000.000/0000-00
  return digits
    .replace(/(\d{2})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1/$2")
    .replace(/(\d{4})(\d{1,2})$/, "$1-$2");
}

function applyTelefoneMask(value: string): string {
  const digits = value.replace(/\D/g, "");
  if (digits.length <= 10) {
    // Fixo: (00) 0000-0000
    return digits
      .replace(/(\d{2})(\d)/, "($1) $2")
      .replace(/(\d{4})(\d)/, "$1-$2")
      .replace(/(-\d{4})\d+?$/, "$1");
  }
  // Celular: (00) 00000-0000
  return digits
    .replace(/(\d{2})(\d)/, "($1) $2")
    .replace(/(\d{5})(\d)/, "$1-$2")
    .replace(/(-\d{4})\d+?$/, "$1");
}

function applyIEMask(value: string): string {
  const digits = value.replace(/\D/g, "");
  // IE genérica: agrupa em blocos de 3
  return digits
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d{1,3})$/, "$1-$2");
}

// ---------------------------------------------------------------------------
// Helpers de descrição
// ---------------------------------------------------------------------------

const REGIMES_DESCRICAO: Record<string, string> = {
  SIMPLES_NACIONAL: "Simples Nacional",
  LUCRO_PRESUMIDO: "Lucro Presumido",
  LUCRO_REAL: "Lucro Real",
  PRODUTOR_RURAL: "Produtor Rural",
};

// ---------------------------------------------------------------------------
// Componentes de Input com Máscara
// ---------------------------------------------------------------------------

interface MaskedInputProps {
  value: string;
  onChange: (value: string) => void;
  mask: (value: string) => string;
  placeholder?: string;
  maxLength?: number;
  className?: string;
}

export function MaskedInput({ value, onChange, mask, placeholder, maxLength, className }: MaskedInputProps) {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value;
    const masked = mask(raw);
    onChange(masked);
  };

  return (
    <Input
      value={value}
      onChange={handleChange}
      placeholder={placeholder}
      maxLength={maxLength}
      className={className}
    />
  );
}

// ---------------------------------------------------------------------------
// ColorPicker
// ---------------------------------------------------------------------------

interface ColorPickerProps {
  value: string;
  onChange: (value: string) => void;
}

export function ColorPicker({ value, onChange }: ColorPickerProps) {
  return (
    <div className="flex items-center gap-2">
      {/* Color picker nativo */}
      <div className="relative w-10 h-10 rounded-md border border-input overflow-hidden flex-shrink-0">
        <input
          type="color"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute inset-0 w-[150%] h-[150%] -translate-x-[25%] -translate-y-[25%] cursor-pointer"
        />
      </div>

      {/* Input de texto com a cor */}
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder="#3B82F6"
        className="h-7 w-full min-w-0 rounded-sm border border-input bg-transparent px-2 py-1 text-sm font-mono transition-all outline-none placeholder:text-muted-foreground"
        maxLength={7}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// IconUploader
// ---------------------------------------------------------------------------

interface IconUploaderProps {
  value: string;
  onChange: (value: string) => void;
}

export function IconUploader({ value, onChange }: IconUploaderProps) {
  const [preview, setPreview] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Lê como base64 para preview imediato
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreview(reader.result as string);
    };
    reader.readAsDataURL(file);

    // Salva apenas nome do arquivo (dentro do limite de 50 chars)
    const name = `upload_${Date.now()}.${file.name.split('.').pop()}`;
    onChange(name);
  };

  const handleRemove = () => {
    setPreview(null);
    onChange("");
  };

  return (
    <div className="flex items-center gap-2">
      {/* Preview */}
      <div className="w-10 h-10 rounded-md border border-input flex-shrink-0 overflow-hidden bg-muted flex items-center justify-center">
        {preview ? (
          <img src={preview} alt="Preview" className="w-full h-full object-cover" />
        ) : value ? (
          <span className="text-xs text-muted-foreground">📷</span>
        ) : (
          <span className="text-muted-foreground text-xs">—</span>
        )}
      </div>

      {/* Botão upload */}
      <label className="cursor-pointer flex-1">
        <div className="h-7 w-full rounded-sm border border-input bg-transparent px-2 py-1 text-sm transition-all flex items-center gap-2 hover:bg-muted/50">
          <Upload className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
          <span className="text-sm text-muted-foreground">
            {value ? "Trocar imagem" : "Carregar imagem"}
          </span>
        </div>
        <input
          type="file"
          accept="image/*"
          onChange={handleFileChange}
          className="hidden"
        />
      </label>

      {value && (
        <button
          type="button"
          onClick={handleRemove}
          className="h-7 px-2 text-xs text-destructive hover:bg-destructive/10 rounded-sm border border-transparent hover:border-destructive/20 transition-all flex-shrink-0"
        >
          Remover
        </button>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// PropriedadeFormFields
// ---------------------------------------------------------------------------

interface PropriedadeFormFieldsProps {
  form: Record<string, any>;
  errors: Record<string, string>;
  onChange: (field: string, value: any) => void;
}

export function PropriedadeFormFields({ form, errors, onChange }: PropriedadeFormFieldsProps) {
  const REGIMES_TRIBUTARIOS = [
    { value: "SIMPLES_NACIONAL", label: "Simples Nacional" },
    { value: "LUCRO_PRESUMIDO", label: "Lucro Presumido" },
    { value: "LUCRO_REAL", label: "Lucro Real" },
    { value: "PRODUTOR_RURAL", label: "Produtor Rural" },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {/* Seção: Informações Básicas */}
      <div className="col-span-full space-y-1">
        <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">
          Informações Básicas
        </h3>
        <div className="border-b" />
      </div>

      <FormField label="Nome" error={errors.nome} required className="col-span-2">
        <Input
          value={form.nome}
          onChange={(e) => onChange("nome", e.target.value)}
          placeholder="Nome da propriedade"
          className={errors.nome ? "border-destructive" : ""}
        />
      </FormField>

      <FormField label="Nome Fantasia" error={errors.nome_fantasia}>
        <Input
          value={form.nome_fantasia || ""}
          onChange={(e) => onChange("nome_fantasia", e.target.value)}
          placeholder="Nome fantasia (opcional)"
        />
      </FormField>

      <FormField label="CNPJ/CPF" error={errors.cpf_cnpj}>
        <MaskedInput
          value={form.cpf_cnpj || ""}
          onChange={(v) => onChange("cpf_cnpj", v)}
          mask={applyCNPJCPFMask}
          placeholder="000.000.000-00 ou 00.000.000/0000-00"
          maxLength={18}
        />
      </FormField>

      {/* Seção: Fiscal e Tributário */}
      <FormField label="Inscrição Estadual" error={errors.inscricao_estadual}>
        <MaskedInput
          value={form.inscricao_estadual || ""}
          onChange={(v) => onChange("inscricao_estadual", v)}
          mask={applyIEMask}
          placeholder="000.000.000.000"
          maxLength={20}
        />
      </FormField>

      <div className="flex items-end gap-2">
        <FormField label="Regime Tributário" error={errors.regime_tributario} className="flex-1">
          <Select
            value={form.regime_tributario || ""}
            onValueChange={(value) => onChange("regime_tributario", value)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Selecione o regime" />
            </SelectTrigger>
            <SelectContent>
              {REGIMES_TRIBUTARIOS.map((regime) => (
                <SelectItem key={regime.value} value={regime.value}>
                  {regime.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </FormField>

        <div className="pb-2">
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={form.ie_isento}
              onChange={(e) => onChange("ie_isento", e.target.checked)}
              className="h-4 w-4 rounded border-gray-300"
            />
            <span className="text-sm">IE Isento</span>
          </label>
        </div>
      </div>

      {/* Seção: Contato */}

      <FormField label="Email" error={errors.email}>
        <Input
          type="email"
          value={form.email || ""}
          onChange={(e) => onChange("email", e.target.value)}
          placeholder="contato@fazenda.com"
          className={errors.email ? "border-destructive" : ""}
        />
      </FormField>

      <FormField label="Telefone" error={errors.telefone}>
        <MaskedInput
          value={form.telefone || ""}
          onChange={(v) => onChange("telefone", v)}
          mask={applyTelefoneMask}
          placeholder="(11) 99999-9999"
          maxLength={15}
        />
      </FormField>

      {/* Seção: Visual */}
      <div className="col-span-full space-y-1 mt-2">
        <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">
          Aparência
        </h3>
        <div className="border-b" />
      </div>

      <FormField label="Cor">
        <ColorPicker
          value={form.cor || "#3B82F6"}
          onChange={(value) => onChange("cor", value)}
        />
      </FormField>

      <FormField label="Ícone" error={errors.icone}>
        <IconUploader
          value={form.icone || ""}
          onChange={(value) => onChange("icone", value)}
        />
      </FormField>

      <FormField label="Ordem" error={errors.ordem}>
        <Input
          type="number"
          value={form.ordem || 0}
          onChange={(e) => onChange("ordem", parseInt(e.target.value) || 0)}
          min={0}
        />
      </FormField>

      {/* Seção: Observações */}
      <div className="col-span-full space-y-1 mt-2">
        <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">
          Observações
        </h3>
        <div className="border-b" />
      </div>

      <FormField label="Observações" className="col-span-2">
        <Textarea
          value={form.observacoes || ""}
          onChange={(e) => onChange("observacoes", e.target.value)}
          placeholder="Observações adicionais sobre a propriedade..."
          rows={4}
        />
      </FormField>
    </div>
  );
}

