"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod/v4";
import { createFazendaSchema, type CreateFazendaInput, type UpdateFazendaInput } from "@farm/zod-schemas";

type CreateFazendaFormInput = z.input<typeof createFazendaSchema>;
import { apiFetch } from "@/lib/api";
import { toast } from "sonner";
import { useAppStore } from "@/lib/stores/app-store";
import { Loader2, Landmark, MapPin } from "lucide-react";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { UnidadeProdutiva } from "@/types/global";

const TIPO_LABEL: Record<string, string> = {
    fazenda: "Fazenda",
    sitio: "Sítio",
    chacara: "Chácara",
    arrendamento: "Arrendamento",
    parceria: "Parceria",
};

interface PropriedadeDialogProps {
    open: boolean;
    onOpenChange: (v: boolean) => void;
    fazenda?: UnidadeProdutiva;
    grupos?: { id: string; nome: string }[];
    isPending: boolean;
    onSubmit: (data: CreateFazendaInput | UpdateFazendaInput) => void;
}

export function PropriedadeDialog({
    open, onOpenChange, fazenda, grupos = [], isPending, onSubmit,
}: PropriedadeDialogProps) {
    const isEdit = !!fazenda;
    const token = useAppStore((s) => s.token);

    // Coordenadas separadas (UI) -> combinadas em coordenadas_sede (submit)
    const [lat, setLat] = useState("");
    const [lng, setLng] = useState("");

    const { register, handleSubmit, setValue, watch, reset, formState: { errors } } = useForm<CreateFazendaFormInput, unknown, CreateFazendaInput>({
        resolver: zodResolver(createFazendaSchema),
        defaultValues: fazenda
            ? {
                grupo_id: grupos.length === 1 ? grupos[0].id : "",
                nome: fazenda.nome,
                tipo_propriedade: (fazenda.tipo_propriedade as CreateFazendaInput["tipo_propriedade"]) ?? "fazenda",
                cpf_cnpj: fazenda.cpf_cnpj ?? "",
                area_total_ha: fazenda.area_total_ha ?? 0,
                ativo: fazenda.ativo ?? true,
                cep: fazenda.cep ?? "",
                logradouro: fazenda.logradouro ?? "",
                bairro: fazenda.bairro ?? "",
                municipio: fazenda.municipio ?? "",
                uf: fazenda.uf ?? "",
                codigo_car: fazenda.codigo_car ?? "",
                inscricao_estadual: "",
                coordenadas_sede: "",
                ibge_municipio_codigo: "",
                ccir: "",
                sigef_codigo: "",
            }
            : {
                grupo_id: grupos.length === 1 ? grupos[0].id : "",
                nome: "",
                tipo_propriedade: "fazenda",
                cpf_cnpj: "",
                area_total_ha: 0,
                ativo: true,
                cep: "",
                logradouro: "",
                bairro: "",
                municipio: "",
                uf: "",
                codigo_car: "",
                inscricao_estadual: "",
                coordenadas_sede: "",
                ibge_municipio_codigo: "",
                ccir: "",
                sigef_codigo: "",
            },
    });

    useEffect(() => {
        if (open) {
            const baseValues = {
                grupo_id: grupos.length === 1 ? grupos[0].id : "",
                nome: fazenda?.nome ?? "",
                tipo_propriedade: (fazenda?.tipo_propriedade as CreateFazendaInput["tipo_propriedade"]) ?? "fazenda",
                cpf_cnpj: fazenda?.cpf_cnpj ?? "",
                area_total_ha: fazenda?.area_total_ha ?? 0,
                ativo: fazenda?.ativo ?? true,
                cep: fazenda?.cep ?? "",
                logradouro: fazenda?.logradouro ?? "",
                bairro: fazenda?.bairro ?? "",
                municipio: fazenda?.municipio ?? "",
                uf: fazenda?.uf ?? "",
                codigo_car: fazenda?.codigo_car ?? "",
                inscricao_estadual: "",
                coordenadas_sede: "",
                ibge_municipio_codigo: "",
                ccir: "",
                sigef_codigo: "",
            };
            reset(baseValues);

            // Parse coordenadas existentes
            if (fazenda?.coordenadas_sede) {
                const parts = fazenda.coordenadas_sede.split(",");
                if (parts.length === 2) {
                    setLat(parts[0].trim());
                    setLng(parts[1].trim());
                } else {
                    setLat("");
                    setLng("");
                }
            } else {
                setLat("");
                setLng("");
            }
        }
    }, [open, fazenda, grupos, reset]);

    async function buscarCep() {
        const cepVal = watch("cep")?.replace(/\D/g, "");
        if (!cepVal || cepVal.length < 8) {
            toast.error("CEP inválido");
            return;
        }
        try {
            const dados = await apiFetch<any>(
                `/integracoes/regulatorias/cep/${cepVal}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            if (dados.logradouro) setValue("logradouro", dados.logradouro);
            if (dados.bairro) setValue("bairro", dados.bairro);
            if (dados.municipio) setValue("municipio", dados.municipio);
            if (dados.uf) setValue("uf", dados.uf);
            if (dados.ibge_municipio_codigo) setValue("ibge_municipio_codigo", dados.ibge_municipio_codigo);
            toast.success("Endereço preenchido automaticamente.");
        } catch {
            toast.error("CEP não encontrado.");
        }
    }

    function handleFormSubmit(data: CreateFazendaInput | UpdateFazendaInput) {
        // Combina lat + lng em coordenadas_sede
        const coords = lat.trim() && lng.trim() ? `${lat.trim()}, ${lng.trim()}` : "";
        onSubmit({ ...data, coordenadas_sede: coords });
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <div className="flex items-center gap-2">
                        <Landmark className="size-5 text-primary" />
                        <div>
                            <DialogTitle>{isEdit ? "Editar Propriedade" : "Nova Propriedade"}</DialogTitle>
                            <DialogDescription className="text-xs mt-0.5">
                                {isEdit ? "Atualize os dados da propriedade." : "Cadastre uma nova propriedade rural."}
                            </DialogDescription>
                        </div>
                    </div>
                </DialogHeader>

                <form onSubmit={handleSubmit(handleFormSubmit)} className="space-y-4">
                    {/* Nome */}
                    <div className="space-y-1.5">
                        <Label htmlFor="nome">Nome da Propriedade *</Label>
                        <Input
                            id="nome"
                            placeholder="Ex: Fazenda Santa Maria"
                            {...register("nome")}
                            disabled={isPending}
                        />
                        {errors.nome && <p className="text-xs text-destructive">{errors.nome.message}</p>}
                    </div>

                    {/* Tipo + Área */}
                    <div className="grid grid-cols-2 gap-3">
                        <div className="space-y-1.5">
                            <Label htmlFor="tipo">Tipo *</Label>
                            <Select
                                value={watch("tipo_propriedade") ?? "fazenda"}
                                onValueChange={(v) => setValue("tipo_propriedade", v as CreateFazendaInput["tipo_propriedade"])}
                                disabled={isPending}
                            >
                                <SelectTrigger id="tipo">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {Object.entries(TIPO_LABEL).map(([value, label]) => (
                                        <SelectItem key={value} value={value}>{label}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-1.5">
                            <Label htmlFor="area">Área (ha)</Label>
                            <Input
                                id="area"
                                type="number"
                                step="0.01"
                                placeholder="0.00"
                                {...register("area_total_ha", { valueAsNumber: true })}
                                disabled={isPending}
                                className="tabular-nums"
                            />
                        </div>
                    </div>

                    {/* CEP + Localização */}
                    <div className="space-y-1.5">
                        <Label htmlFor="cep">CEP</Label>
                        <div className="flex gap-2">
                            <Input
                                id="cep"
                                placeholder="00000-000"
                                {...register("cep")}
                                disabled={isPending}
                                className="flex-1"
                            />
                            <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                onClick={buscarCep}
                                disabled={isPending}
                                className="whitespace-nowrap"
                            >
                                Buscar
                            </Button>
                        </div>
                    </div>

                    {/* Cidade + UF */}
                    <div className="grid grid-cols-3 gap-3">
                        <div className="col-span-2 space-y-1.5">
                            <Label htmlFor="municipio">Município</Label>
                            <Input
                                id="municipio"
                                placeholder="São Paulo"
                                {...register("municipio")}
                                disabled={isPending}
                            />
                        </div>
                        <div className="space-y-1.5">
                            <Label htmlFor="uf">UF</Label>
                            <Input
                                id="uf"
                                placeholder="SP"
                                maxLength={2}
                                {...register("uf")}
                                disabled={isPending}
                                className="uppercase"
                            />
                        </div>
                    </div>

                    {/* CAR */}
                    <div className="space-y-1.5">
                        <Label htmlFor="codigo_car">CAR</Label>
                        <Input
                            id="codigo_car"
                            placeholder="Código CAR (opcional)"
                            {...register("codigo_car")}
                            disabled={isPending}
                        />
                    </div>

                    {/* Coordenadas */}
                    <div className="space-y-1.5">
                        <div className="flex items-center gap-1.5">
                            <MapPin className="size-3.5 text-muted-foreground" />
                            <Label>Coordenadas da Sede</Label>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1.5">
                                <Label htmlFor="lat" className="text-[10px] text-muted-foreground">Latitude</Label>
                                <Input
                                    id="lat"
                                    placeholder="-23.5505"
                                    value={lat}
                                    onChange={(e) => setLat(e.target.value)}
                                    disabled={isPending}
                                />
                            </div>
                            <div className="space-y-1.5">
                                <Label htmlFor="lng" className="text-[10px] text-muted-foreground">Longitude</Label>
                                <Input
                                    id="lng"
                                    placeholder="-46.6333"
                                    value={lng}
                                    onChange={(e) => setLng(e.target.value)}
                                    disabled={isPending}
                                />
                            </div>
                        </div>
                        <p className="text-[10px] text-muted-foreground">
                            Formato decimal (ex: -23.5505, -46.6333). Opcional.
                        </p>
                    </div>

                    {/* Grupo - só mostrar se houver opções */}
                    {grupos.length > 1 && (
                        <div className="space-y-1.5">
                            <Label htmlFor="grupo">Grupo de Fazendas *</Label>
                            <Select
                                value={watch("grupo_id") ?? ""}
                                onValueChange={(v) => setValue("grupo_id", v)}
                                disabled={isPending}
                            >
                                <SelectTrigger id="grupo">
                                    <SelectValue placeholder="Selecione..." />
                                </SelectTrigger>
                                <SelectContent>
                                    {grupos.map((g) => (
                                        <SelectItem key={g.id} value={g.id}>{g.nome}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    )}

                    {/* Buttons */}
                    <div className="flex gap-2 justify-end pt-4 border-t">
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => onOpenChange(false)}
                            disabled={isPending}
                        >
                            Cancelar
                        </Button>
                        <Button
                            type="submit"
                            disabled={isPending}
                        >
                            {isPending && <Loader2 className="animate-spin" />}
                            {isPending ? "Salvando..." : isEdit ? "Salvar" : "Cadastrar"}
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
}

