"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { toast } from "sonner";
import { useAppStore } from "@/lib/stores/app-store";
import { Loader2, Shield } from "lucide-react";
import {
    Sheet, SheetContent, SheetDescription, SheetFooter, SheetHeader, SheetTitle,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { VigenciaBadge } from "./vigencia-badge";
import { Skeleton } from "@/components/ui/skeleton";
import type { UnidadeProdutiva, FazendaAccess } from "@/types/global";

interface AcessoDrawerProps {
    open: boolean;
    onOpenChange: (v: boolean) => void;
    usuarioId: string;
    usuarioNome: string;
    tenantId?: string;
}

interface AcessoItem {
    unidade_produtiva_id: string;
    fazenda_nome: string;
    tem_acesso: boolean;
    perfil_unidade_produtiva_id: string | null;
    vigencia_inicio: string | null;
    vigencia_fim: string | null;
}

export function AcessoDrawer({ open, onOpenChange, usuarioId, usuarioNome }: AcessoDrawerProps) {
    const queryClient = useQueryClient();
    const token = useAppStore((s) => s.token);
    const tenantId = useAppStore((s) => s.tenant?.id);
    const hasHydrated = useAppStore((s) => s._hasHydrated);

    const { data: fazendas = [], isLoading: loadingFazendas } = useQuery<UnidadeProdutiva[]>({
        queryKey: ["unidades-produtivas"],
        queryFn: () => apiFetch("/unidades-produtivas"),
        enabled: open && hasHydrated && !!token && !!tenantId,
    });

    const { data: acessosAtuais = [], isLoading: loadingAcessos } = useQuery<FazendaAccess[]>({
        queryKey: ["usuario-acessos", usuarioId],
        queryFn: () => apiFetch(`/team/members/${usuarioId}/fazendas`),
        enabled: open && hasHydrated && !!token && !!usuarioId,
    });

    const [itens, setItens] = useState<AcessoItem[]>([]);

    useEffect(() => {
        if (fazendas.length > 0) {
            setItens(fazendas.map((f) => {
                const acesso = acessosAtuais.find((a) => a.id === f.id);
                return {
                    unidade_produtiva_id: f.id,
                    fazenda_nome: f.nome,
                    tem_acesso: !!acesso,
                    perfil_unidade_produtiva_id: null,
                    vigencia_inicio: acesso?.vigencia_inicio ?? null,
                    vigencia_fim: acesso?.vigencia_fim ?? null,
                };
            }));
        }
    }, [fazendas, acessosAtuais]);

    const saveMutation = useMutation({
        mutationFn: async () => {
            const comAcesso = itens.filter((i) => i.tem_acesso);
            await apiFetch(`/team/members/${usuarioId}/fazendas`, {
                method: "PUT",
                body: JSON.stringify({
                    fazendas: comAcesso.map((i) => ({
                        unidade_produtiva_id: i.unidade_produtiva_id,
                        vigencia_inicio: i.vigencia_inicio || null,
                        vigencia_fim: i.vigencia_fim || null,
                    })),
                }),
            });
        },
        onSuccess: () => {
            toast.success("Acessos atualizados com sucesso!");
            queryClient.invalidateQueries({ queryKey: ["team-members"] });
            queryClient.invalidateQueries({ queryKey: ["usuario-acessos", usuarioId] });
            onOpenChange(false);
        },
        onError: (err: Error) => toast.error(err.message || "Erro ao salvar acessos"),
    });

    const isLoading = loadingFazendas || loadingAcessos;

    function toggle(unidade_produtiva_id: string) {
        setItens((prev) => prev.map((i) =>
            i.unidade_produtiva_id === unidade_produtiva_id ? { ...i, tem_acesso: !i.tem_acesso } : i
        ));
    }

    function setVigencia(unidade_produtiva_id: string, field: "vigencia_inicio" | "vigencia_fim", value: string) {
        setItens((prev) => prev.map((i) =>
            i.unidade_produtiva_id === unidade_produtiva_id ? { ...i, [field]: value || null } : i
        ));
    }

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
                <SheetHeader>
                    <SheetTitle className="flex items-center gap-2">
                        <Shield className="size-4" /> Gerenciar Acessos
                    </SheetTitle>
                    <SheetDescription>
                        Defina quais propriedades <strong>{usuarioNome}</strong> pode acessar e por quanto tempo.
                    </SheetDescription>
                </SheetHeader>

                <div className="space-y-3 py-4">
                    {isLoading ? (
                        Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-16 rounded-lg" />)
                    ) : fazendas.length === 0 ? (
                        <p className="text-sm text-muted-foreground text-center py-6">Nenhuma propriedade cadastrada.</p>
                    ) : (
                        itens.map((item) => (
                            <div key={item.unidade_produtiva_id} className="border rounded-lg p-3 space-y-3">
                                <div className="flex items-center gap-3">
                                    <Checkbox
                                        id={`acesso-${item.unidade_produtiva_id}`}
                                        checked={item.tem_acesso}
                                        onCheckedChange={() => toggle(item.unidade_produtiva_id)}
                                    />
                                    <Label htmlFor={`acesso-${item.unidade_produtiva_id}`} className="font-medium cursor-pointer flex-1">
                                        {item.fazenda_nome}
                                    </Label>
                                    {item.tem_acesso && (item.vigencia_inicio || item.vigencia_fim) && (
                                        <VigenciaBadge
                                            vigencia_inicio={item.vigencia_inicio}
                                            vigencia_fim={item.vigencia_fim}
                                        />
                                    )}
                                </div>

                                {item.tem_acesso && (
                                    <div className="grid grid-cols-2 gap-2 pl-7">
                                        <div className="space-y-1">
                                            <Label className="text-xs text-muted-foreground">Início da vigência</Label>
                                            <Input
                                                type="date"
                                                value={item.vigencia_inicio ?? ""}
                                                onChange={(e) => setVigencia(item.unidade_produtiva_id, "vigencia_inicio", e.target.value)}
                                                className="h-8 text-xs"
                                            />
                                        </div>
                                        <div className="space-y-1">
                                            <Label className="text-xs text-muted-foreground">Fim da vigência</Label>
                                            <Input
                                                type="date"
                                                value={item.vigencia_fim ?? ""}
                                                onChange={(e) => setVigencia(item.unidade_produtiva_id, "vigencia_fim", e.target.value)}
                                                className="h-8 text-xs"
                                            />
                                        </div>
                                        <p className="col-span-2 text-[10px] text-muted-foreground">
                                            Deixe em branco para acesso permanente.
                                        </p>
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>

                <SheetFooter className="pt-4 border-t">
                    <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saveMutation.isPending}>
                        Cancelar
                    </Button>
                    <Button onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending || isLoading}>
                        {saveMutation.isPending ? <><Loader2 className="size-4 animate-spin mr-2" />Salvando...</> : "Salvar acessos"}
                    </Button>
                </SheetFooter>
            </SheetContent>
        </Sheet>
    );
}

"use client";

import { useState } from "react";
import { FolderTree, Map, Sprout, Trees, Droplets, Building2, Fence, ShieldCheck, Layers, LayoutGrid, Plus, Edit, Trash2, Warehouse, ChevronRight, ChevronDown, Wheat } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { AREA_HIERARQUIA } from "@farm/zod-schemas";
import type { AreaRuralTree } from "@farm/zod-schemas";

// Ícones por tipo de área
const AREA_ICONS: Record<string, React.ReactNode> = {
  AREA_RURAL:       <FolderTree className="w-4 h-4" />,
  GLEBA:            <Map className="w-4 h-4" />,
  TALHAO:           <Sprout className="w-4 h-4" />,
  AREA_AMBIENTAL:   <ShieldCheck className="w-4 h-4" />,
  AREA_OPERACIONAL: <LayoutGrid className="w-4 h-4" />,
  PIQUETE:          <Fence className="w-4 h-4" />,
  ZONA_MANEJO:      <Layers className="w-4 h-4" />,
  SUBTALHAO:        <Sprout className="w-4 h-4" />,
  APP:              <Droplets className="w-4 h-4" />,
  RESERVA_LEGAL:    <Trees className="w-4 h-4" />,
  INFRAESTRUTURA:   <Building2 className="w-4 h-4" />,
  SEDE:             <Building2 className="w-4 h-4" />,
  ARMAZEM:          <Warehouse className="w-4 h-4" />,
  CURRAL:           <Fence className="w-4 h-4" />,
  OUTROS:           <FolderTree className="w-4 h-4" />,
};

// Cores por tipo de área (camada territorial=verde, ambiental=azul, infra=cinza)
const AREA_COLORS: Record<string, string> = {
  AREA_RURAL:       "bg-green-600",
  GLEBA:            "bg-purple-500",
  TALHAO:           "bg-emerald-500",
  AREA_AMBIENTAL:   "bg-blue-400",
  AREA_OPERACIONAL: "bg-teal-500",
  PIQUETE:          "bg-cyan-500",
  ZONA_MANEJO:      "bg-teal-600",
  SUBTALHAO:        "bg-emerald-600",
  APP:              "bg-blue-500",
  RESERVA_LEGAL:    "bg-green-700",
  INFRAESTRUTURA:   "bg-slate-500",
  SEDE:             "bg-slate-600",
  ARMAZEM:          "bg-amber-600",
  CURRAL:           "bg-orange-600",
  OUTROS:           "bg-gray-500",
};

// Labels por tipo
const AREA_LABELS: Record<string, string> = {
  AREA_RURAL:       "Área Rural",
  GLEBA:            "Gleba",
  TALHAO:           "Talhão",
  AREA_AMBIENTAL:   "Área Ambiental",
  AREA_OPERACIONAL: "Área Operacional",
  PIQUETE:          "Piquete",
  ZONA_MANEJO:      "Zona de Manejo",
  SUBTALHAO:        "Subtalhão",
  APP:              "APP",
  RESERVA_LEGAL:    "Reserva Legal",
  INFRAESTRUTURA:   "Infraestrutura",
  SEDE:             "Sede",
  ARMAZEM:          "Armazém",
  CURRAL:           "Curral",
  OUTROS:           "Outros",
};

// Folhas não aceitam filhos
function isFolha(tipo: string): boolean {
  return (AREA_HIERARQUIA[tipo]?.length ?? 1) === 0;
}

interface AreaTreeItemProps {
  area: AreaRuralTree;
  level?: number;
  onSelect?: (area: AreaRuralTree) => void;
  onAdd?: (parentId: string, parentType: string) => void;
  onEdit?: (area: AreaRuralTree) => void;
  onDelete?: (area: AreaRuralTree) => void;
  selectedId?: string | null;
}

export function AreaTreeItem({
  area,
  level = 0,
  onSelect,
  onAdd,
  onEdit,
  onDelete,
  selectedId,
}: AreaTreeItemProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const hasChildren = area.filhos && area.filhos.length > 0;
  const isSelected = selectedId === area.id;

  const handleToggle = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (hasChildren) {
      setIsExpanded(!isExpanded);
    }
  };

  const handleSelect = () => {
    onSelect?.(area);
  };

  const handleAdd = (e: React.MouseEvent) => {
    e.stopPropagation();
    onAdd?.(area.id, area.tipo);
  };

  const handleEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onEdit?.(area);
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete?.(area);
  };

  return (
    <div className="select-none">
      {/* Item da árvore */}
      <div
        className={cn(
          "flex items-center gap-2 py-2 px-3 rounded-lg cursor-pointer transition-all hover:bg-accent group",
          isSelected && "bg-primary/10 border border-primary/30"
        )}
        style={{ paddingLeft: `${level * 24 + 12}px` }}
        onClick={handleSelect}
      >
        {/* Toggle Chevron */}
        <div onClick={handleToggle} className="shrink-0 w-5 flex items-center justify-center">
          {hasChildren ? (
            isExpanded
              ? <ChevronDown className="w-4 h-4 text-muted-foreground" />
              : <ChevronRight className="w-4 h-4 text-muted-foreground" />
          ) : (
            <span className="w-4" />
          )}
        </div>

        {/* Ícone do tipo */}
        <div
          className={cn(
            "w-8 h-8 rounded-lg flex items-center justify-center text-white",
            AREA_COLORS[area.tipo] || "bg-gray-500"
          )}
        >
          {AREA_ICONS[area.tipo] || <FolderTree className="w-4 h-4" />}
        </div>

        {/* Informações */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-medium truncate">{area.nome}</span>
            {area.codigo && (
              <Badge variant="outline" className="text-xs">
                {area.codigo}
              </Badge>
            )}
            <Badge variant="secondary" className="text-xs">
              {AREA_LABELS[area.tipo] || area.tipo}
            </Badge>
          </div>
          <div className="flex items-center gap-3 text-xs text-muted-foreground mt-0.5">
            {area.area_hectares || area.area_hectares_manual ? (
              <span>
                {(area.area_hectares || area.area_hectares_manual)?.toFixed(2)} ha
              </span>
            ) : null}
            {(area as any).irrigado && (
              <Badge variant="outline" className="text-[10px] h-4 px-1 border-blue-200 bg-blue-50 text-blue-600 gap-0.5">
                <Droplets className="size-2.5" />
                {(area as any).tipo_irrigacao_nome || "Irrigado"}
              </Badge>
            )}
            {(area as any).tipo_solo_nome && (
              <span className="text-[10px] font-medium text-amber-700 bg-amber-50 px-1 rounded border border-amber-100">
                {(area as any).tipo_solo_nome}
              </span>
            )}
            {(area as any).cultivo_atual && (
              <Badge variant="outline" className="text-[10px] h-4 px-1 border-emerald-200 bg-emerald-50 text-emerald-700 gap-0.5">
                <Wheat className="size-2.5" />
                {(area as any).cultivo_atual.cultura} ({(area as any).cultivo_atual.safra_nome})
              </Badge>
            )}
            {area.descricao && (
              <span className="truncate max-w-[200px]">{area.descricao}</span>
            )}
          </div>
        </div>

        {/* Ações */}
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          {!isFolha(area.tipo) && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              onClick={handleAdd}
              title="Adicionar filho"
            >
              <Plus className="w-3.5 h-3.5" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            className="h-7 w-7 p-0"
            onClick={handleEdit}
            title="Editar"
          >
            <Edit className="w-3.5 h-3.5" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="h-7 w-7 p-0 text-destructive hover:text-destructive"
            onClick={handleDelete}
            title="Remover"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      {/* Filhos (recursivo) */}
      {hasChildren && isExpanded && (
        <div className="transition-all">
          {area.filhos.map((filho: AreaRuralTree) => (
            <AreaTreeItem
              key={filho.id}
              area={filho}
              level={level + 1}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              selectedId={selectedId}
            />
          ))}
        </div>
      )}
    </div>
  );
}

interface AreaTreeProps {
  areas: AreaRuralTree[];
  onSelect?: (area: AreaRuralTree) => void;
  onAdd?: (parentId: string, parentType: string) => void;
  onEdit?: (area: AreaRuralTree) => void;
  onDelete?: (area: AreaRuralTree) => void;
  selectedId?: string | null;
  className?: string;
}

export function AreaTree({
  areas,
  onSelect,
  onAdd,
  onEdit,
  onDelete,
  selectedId,
  className,
}: AreaTreeProps) {
  if (!areas || areas.length === 0) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        <FolderTree className="w-16 h-16 mx-auto mb-4 opacity-50" />
        <p className="text-sm">Nenhuma área rural cadastrada</p>
        <p className="text-xs mt-1">
          Clique em "Nova Área" para começar
        </p>
      </div>
    );
  }

  return (
    <div className={cn("space-y-1", className)}>
      {areas.map((area) => (
        <AreaTreeItem
          key={area.id}
          area={area}
          onSelect={onSelect}
          onAdd={onAdd}
          onEdit={onEdit}
          onDelete={onDelete}
          selectedId={selectedId}
        />
      ))}
    </div>
  );
}

// Exportar helpers
export { AREA_ICONS, AREA_COLORS, AREA_LABELS };

"use client";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Construction,
  Rocket,
  Bell,
  CheckCircle2,
  ArrowLeft
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api";
import { useEffect, useState } from "react";

interface EmDesenvolvimentoProps {
  titulo?: string;
  descricao?: string;
  funcionalidades?: string[];
  previsao?: string;
  voltarPara?: string;
}

export function EmDesenvolvimento({
  titulo,
  descricao,
  funcionalidades,
  previsao,
  voltarPara,
}: EmDesenvolvimentoProps) {
  const router = useRouter();
  const [mounted, setMounted] = useState(false);

  // Busca configurações padrão do SaaS
  interface EmDesenvolvimentoConfig {
    valor?: {
      titulo?: string;
      descricao?: string;
      funcionalidades?: string[];
      previsao?: string;
      voltarPara?: string;
    };
  }

  const { data: configsData } = useQuery<EmDesenvolvimentoConfig>({
    queryKey: ["saas-config-em-desenvolvimento"],
    queryFn: () => apiFetch("/config/saas/em_desenvolvimento"),
    retry: 1,
    staleTime: 1000 * 60 * 5, // 5 min
  });

  useEffect(() => {
    setMounted(true);
  }, []);

  // Use provided props, fallback to SaaS config, then hardcoded defaults
  const tituloFinal = titulo || configsData?.valor?.titulo || "Em Desenvolvimento";
  const descricaoFinal = descricao || configsData?.valor?.descricao || "Esta funcionalidade está sendo construída com muito carinho e estará disponível em breve.";
  const funcionalidadesFinal = funcionalidades || configsData?.valor?.funcionalidades || [];
  const previsaoFinal = previsao || configsData?.valor?.previsao || undefined;
  const voltarParaFinal = voltarPara || configsData?.valor?.voltarPara || "/dashboard";

  if (!mounted) {
    return null; // Avoid hydration mismatch
  }

  return (
    <div className="flex items-center justify-center min-h-[80vh] p-8">
      <Card className="w-full max-w-2xl">
        <CardHeader className="text-center">
          <div className="flex justify-center mb-4">
            <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/10">
              <Construction className="h-10 w-10 text-primary" />
            </div>
          </div>

          <CardTitle className="text-3xl">{tituloFinal}</CardTitle>
          <CardDescription className="text-lg mt-2">
            {descricaoFinal}
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-6">
          {/* Funcionalidades que estão sendo construídas */}
          {funcionalidadesFinal.length > 0 && (
            <div className="space-y-3">
              <h3 className="font-semibold text-lg flex items-center gap-2">
                <Rocket className="h-5 w-5" />
                O que está sendo construído:
              </h3>
              <ul className="grid gap-2">
                {funcionalidadesFinal.map((func, index) => (
                  <li
                    key={index}
                    className="flex items-center gap-2 text-sm bg-muted/50 px-3 py-2 rounded-md"
                  >
                    <Rocket className="h-4 w-4 text-primary" />
                    {func}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Previsão de lançamento */}
          {previsaoFinal && (
            <div className="flex gap-3 p-4 bg-blue-50 border border-blue-200 rounded-md">
              <Bell className="h-4 w-4 text-blue-600 mt-0.5 flex-shrink-0" />
              <div className="text-blue-800 text-sm">
                <strong>Previsão de lançamento:</strong> {previsaoFinal}
              </div>
            </div>
          )}

          {/* Progresso */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">Progresso</span>
              <span className="font-medium">Em construção</span>
            </div>
            <div className="h-2 bg-muted rounded-full overflow-hidden">
              <div className="h-full w-1/3 bg-primary animate-pulse" />
            </div>
          </div>

          {/* Ações */}
          <div className="flex gap-3 pt-4">
            <Button
              variant="outline"
              onClick={() => router.back()}
              className="flex-1"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Voltar
            </Button>

            <Button
              variant="default"
              asChild
              className="flex-1"
            >
              <Link href={voltarParaFinal}>
                <CheckCircle2 className="h-4 w-4 mr-2" />
                Ir para Dashboard
              </Link>
            </Button>
          </div>

          {/* Notificação de lançamento */}
          <div className="text-center text-xs text-muted-foreground pt-4 border-t">
            <p>🚀 Quer ser notificado quando esta funcionalidade for lançada?</p>
            <p>Entre em contato com nosso suporte!</p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

